window.ENGLISH_CURRICULUM = {"version":"3.7","updatedAt":"2026-10-19","books":[{"id":"7a","title":"七年级上册","grade":7,"semester":"上册","editionLabel":"修订版 · 2024 版次","editionNote":"已核对扫描本：2024 年 7 月第 1 版，2025 年 7 月第 2 次印刷，8 个单元。当前配套依据该目录整理；未逐页比较 2026 年更新印次。","officialUrl":"https://edu.yilin.com/index.php/Category/index?cat_id=180&dt_type1=2&ebook_id=79&nav_id=5","alignmentStatus":"edition-checked","shortLabel":"七年级上册","alignmentSummary":"已核所列版本的目录与语法范围；印次差异请与手中教材对照。","referenceUrl":"https://www.scribd.com/document/942953797/2025%E6%94%B9%E7%89%88-%E8%AF%BE%E6%9C%AC-%E8%AF%91%E6%9E%97%E7%89%88%E8%8B%B1%E8%AF%AD%E4%B8%83%E5%B9%B4%E7%BA%A7%E4%B8%8A%E5%86%8C"},{"id":"7b","title":"七年级下册","grade":7,"semester":"下册","editionLabel":"修订版 · 2025 春目录","editionNote":"已核对扫描本：2024 年 12 月第 1 版、第 1 次印刷，2025 年春使用的修订体系，8 个单元。U8 为 Wonderland stories；未逐页比较 2026 更新印次，请与学校实书核对。","officialUrl":"https://edu.yilin.com/index.php/Category/index?cat_id=180&dt_type1=2&ebook_id=5&nav_id=5","alignmentStatus":"edition-checked","shortLabel":"七年级下册","alignmentSummary":"已核所列版本的目录与语法范围；印次差异请与手中教材对照。","referenceUrl":"https://www.scribd.com/document/1056071809/%E8%AF%91%E6%9E%97%E7%89%88-%E4%B8%83%E5%B9%B4%E7%BA%A7%E4%B8%8B%E5%86%8C-2025%E6%98%A5%E7%89%88-%E8%8B%B1%E8%AF%AD%E7%94%B5%E5%AD%90%E8%AF%BE%E6%9C%AC"},{"id":"8a","title":"八年级上册","grade":8,"semester":"上册","editionLabel":"修订版 · 2025 秋目录","editionNote":"已核对 2025 秋公开教材目录扫描，属于 2024 审定修订体系，共 8 个单元。2026 年已有更新信息，本次未逐页比较该印次；以学校教材实际目录为准。","officialUrl":"https://edu.yilin.com/index.php/Category/index?cat_id=180&dt_type1=2&ebook_id=78&nav_id=5","alignmentStatus":"edition-checked","shortLabel":"八年级上册","alignmentSummary":"已核所列版本的目录与语法范围；印次差异请与手中教材对照。"},{"id":"8b","title":"八年级下册","grade":8,"semester":"下册","editionLabel":"修订版 · 2026 春目录","editionNote":"已核对 2026 春公开教材目录与语法栏目扫描，共 8 个单元；版权页与 ISBN 尚未取得。配套按已核目录组织，正式版次和印次仍以正版实书为准。","officialUrl":"https://edu.yilin.com/index.php/Category/index?cat_id=180&dt_type1=2&nav_id=5","alignmentStatus":"edition-checked","shortLabel":"八年级下册","alignmentSummary":"已核所列版本的目录与语法范围；印次差异请与手中教材对照。"},{"id":"9a","title":"九年级上册","grade":9,"semester":"上册","editionLabel":"2026 新版主题配套 · 待逐页核验","editionNote":"2026 年新编版的发布已有官方信息，本站 8 个单元标题与语法范围依据公开配套资源交叉整理。尚未取得完整正版目录和各语法页逐页核验，因此按主题配套使用，不声称完整覆盖新版每一课时。","officialUrl":"https://edu.yilin.com/index.php/Category/index?cat_id=180&dt_type1=2&ebook_id=77&nav_id=5","alignmentStatus":"resource-crosschecked","shortLabel":"九年级上册","alignmentSummary":"新版单元和语法按公开配套资源交叉核对；未取得全册教材页逐页核验。"},{"id":"9b","title":"九年级下册","grade":9,"semester":"下册","editionLabel":"旧版四单元 · 参考学习","editionNote":"目前可核实的是旧版四单元结构：Asia、Great people、Robots、Life on Mars。尚未核实修订版九下目录，本站不将此册标为 2026 或 2027 新版。语法转换内容为配套复习；若学校实书目录不同，请优先按实书学习。","officialUrl":"https://edu.yilin.com/index.php/Category/index?cat_id=7&dt_type1=2&ebook_id=202&nav_id=5","alignmentStatus":"legacy-reference","shortLabel":"九年级下册（旧版复习）","alignmentSummary":"这四个单元供旧版复习；新版九下目录尚待核实。"}],"units":[{"id":"7a-u1","bookId":"7a","number":1,"title":"This is me!","theme":"认识自己，友善结识新同学","goals":["用 be 动词介绍身份、性格与喜好","从人物介绍中找出关键信息","完成一段真实、简洁的自我介绍"],"grammarKeys":["be_present"],"vocabulary":[{"word":"introduce","meaning":"介绍","example":"I introduce myself to my new group.","reviewId":0},{"word":"classmate","meaning":"同班同学","example":"My classmate sits beside me.","reviewId":1},{"word":"friendly","meaning":"友好的","example":"Our new monitor is friendly.","reviewId":2},{"word":"quiet","meaning":"安静的；文静的","example":"I am quiet in a large group.","reviewId":3},{"word":"ready","meaning":"准备好的","example":"We are ready for the first lesson.","reviewId":4},{"word":"favourite","meaning":"最喜欢的","example":"Green is my favourite colour.","reviewId":5},{"word":"name","meaning":"名字","example":"Please write your name on the card.","reviewId":6},{"word":"new","meaning":"新的","example":"This is my new school bag.","reviewId":7}],"reading":{"id":"7a-u1-reading","title":"One Small Map","level":"基础","text":"Ben is a new student at River School. He is quiet, and his voice is very soft. On his first morning, a girl named Jo gives him a blue folder. There is a small map inside it. The classrooms are yellow on the map, and the library is green. Ben loves drawing, so the map makes him smile. At lunch, Jo asks about his favourite place. Ben points to the art room. Jo is surprised because she likes art too. They are in different classes, but their lunch time is the same. On Friday, they draw a better school map together. Ben adds pictures of doors and stairs. Now other new students can use their map. Ben is still quiet, but he is no longer alone.","summary":"文静的新生 Ben 因一张校园地图结识朋友，并用自己的绘画爱好帮助更多新生。","questions":[{"prompt":"What does Jo give Ben?","options":["A red notebook.","A blue folder.","A yellow pencil.","A green lunch box."],"correctIndex":1,"explanation":"开头写到 Jo 给 Ben 一个蓝色文件夹，地图放在里面。","skill":"细节理解"},{"prompt":"Which place is green on the map?","options":["The art room.","The classroom.","The library.","The dining hall."],"correctIndex":2,"explanation":"文中明确说明，地图上的教室是黄色，图书馆是绿色。","skill":"细节理解"},{"prompt":"What do Ben and Jo both like?","options":["Art.","Running.","Music.","Cooking."],"correctIndex":0,"explanation":"Ben 喜欢画画并指向美术教室；Jo 也喜欢美术。","skill":"信息整合"},{"prompt":"Why can Ben and Jo meet at lunch?","options":["They live together.","They have no afternoon classes.","They are in the same class.","Their lunch time is the same."],"correctIndex":3,"explanation":"两人虽然不同班，但文中说明他们午餐时间相同。","skill":"细节理解"},{"prompt":"What can we learn about Ben at the end?","options":["He no longer likes drawing.","He can help others through his hobby.","He wants to leave the school.","He is now the loudest student."],"correctIndex":1,"explanation":"Ben 为地图添加门和楼梯，帮助其他新生；这说明文静的他也能用自己的爱好发挥作用。","skill":"推断"}]},"dialogue":{"title":"At the Welcome Desk","turns":[{"speaker":"Lily","text":"Hello, I am Lily. Is this your first day at our school?"},{"speaker":"Max","text":"Yes. My name is Max. I am in Class Three, but I cannot find Room B2."},{"speaker":"Lily","text":"I am in Class Three too! Room B2 is upstairs, beside the reading corner."},{"speaker":"Max","text":"Great! I love reading funny stories. Is the reading corner open at lunch?"},{"speaker":"Lily","text":"Yes, it is. I am there after lunch on Tuesdays. We can read together today."},{"speaker":"Max","text":"Thank you. I am a little nervous now, but I am happy to have a new classmate."}],"questions":[{"prompt":"Which class is Max in?","options":["Class One.","Class Two.","Class Three.","Class Four."],"correctIndex":2,"explanation":"Max 介绍自己在三班，Lily 随后说明自己也在三班。","skill":"细节理解"},{"prompt":"Where is Room B2?","options":["Upstairs beside the reading corner.","Outside the school gate.","Downstairs beside the kitchen.","Behind the sports field."],"correctIndex":0,"explanation":"Lily 说 B2 在楼上，紧邻阅读角。","skill":"细节理解"},{"prompt":"What does Max enjoy reading?","options":["Science reports.","Funny stories.","Sports news.","Travel maps."],"correctIndex":1,"explanation":"Max 直接表达自己喜欢读有趣的故事。","skill":"细节理解"},{"prompt":"What day is it likely to be?","options":["Friday.","Sunday.","Monday.","Tuesday."],"correctIndex":3,"explanation":"Lily 每周二午饭后在阅读角，并邀请 Max 今天一起阅读，因此可推断当天是周二。","skill":"推断"},{"prompt":"How does Max feel at the end?","options":["Angry about his classroom.","Sleepy after a long journey.","Nervous but happy.","Bored with his new classmate."],"correctIndex":2,"explanation":"最后一句同时提到有点紧张，以及结识新同学的高兴。","skill":"情感理解"}]},"writing":{"prompt":"为班级介绍墙写一段自我介绍，说明你的身份、一个性格特点、一项爱好和交友愿望。","outline":["介绍姓名、年级或班级。","用 I am… 描述性格，并举一个小例子。","说明爱好和希望与同学一起做的事。"],"model":"Hello, my name is Amy. I am a student in Class Two. I am quiet at first, but I am friendly. My favourite activity is drawing small animals. There are many animal pictures in my notebook. I am also interested in stories about school life. At lunch, I am usually in the reading corner. I hope to meet classmates who enjoy books or art. We can share our ideas and make our classroom a happier place."},"speakingPrompts":["How would you introduce yourself to a new classmate?","What is one thing you like about yourself?","What can you do to help a new student feel welcome?"],"textbook":{"status":"edition-checked","referenceEdition":"2024 年第 1 版 · 2025 年 7 月第 2 次印刷","grammarScope":"一般现在时Ⅰ：动词 be 的肯定、否定、一般疑问句和简答。","unitStartPage":6,"grammarPages":[11,12],"sections":[{"id":"welcome","label":"Welcome to the unit","labelZh":"导入","pageStart":7,"pageEnd":7,"pageLabel":"7"},{"id":"reading","label":"Reading","labelZh":"阅读","pageStart":8,"pageEnd":10,"pageLabel":"8–10"},{"id":"grammar","label":"Grammar","labelZh":"语法","pageStart":11,"pageEnd":12,"pageLabel":"11–12"},{"id":"pronunciation","label":"Pronunciation","labelZh":"语音","pageStart":13,"pageEnd":13,"pageLabel":"13","topicZh":"元音（一）"},{"id":"integration","label":"Integration","labelZh":"综合运用","pageStart":14,"pageEnd":16,"pageLabel":"14–16"},{"id":"assessment","label":"Assessment","labelZh":"评价","pageStart":17,"pageEnd":17,"pageLabel":"17"},{"id":"furtherStudy","label":"Further study","labelZh":"拓展学习","pageStart":17,"pageEnd":17,"pageLabel":"17"},{"id":"workbook","label":"Workbook","labelZh":"随书练习","pageStart":106,"pageEnd":108,"pageLabel":"106–108","location":"appendix"}]}},{"id":"7a-u2","bookId":"7a","number":2,"title":"Hobbies","theme":"探索爱好，并与他人分享","goals":["用一般现在时描述爱好和习惯","正确使用实义动词第三人称单数形式","说明一项爱好带来的具体收获"],"grammarKeys":["simple_present"],"vocabulary":[{"word":"hobby","meaning":"爱好","example":"My hobby is making paper boats.","reviewId":0},{"word":"collect","meaning":"收集","example":"I collect pictures of interesting doors.","reviewId":1},{"word":"practise","meaning":"练习","example":"She practises the guitar after school.","reviewId":2},{"word":"notice","meaning":"注意到","example":"He notices a bird near the window.","reviewId":3},{"word":"share","meaning":"分享","example":"We share our drawings every Friday.","reviewId":4},{"word":"camera","meaning":"相机","example":"My aunt lends me a small camera.","reviewId":5},{"word":"patient","meaning":"有耐心的","example":"A patient learner tries again.","reviewId":6},{"word":"improve","meaning":"改进；提高","example":"Short practice helps me improve.","reviewId":7}],"reading":{"id":"7a-u2-reading","title":"A Window of Small Things","level":"基础","text":"Nina does not travel far to enjoy her hobby. Every Saturday morning, she takes photos from her kitchen window. She notices things that other people walk past: wet leaves, a cat on a wall, or a red umbrella. At first, her photos are often dark. Her uncle shows her how to wait for better light. Nina practises and becomes more patient. She chooses one picture each week and writes two sentences about it. Her grandmother cannot go outside easily, so Nina sends the pictures to her. They talk about the pictures on Sunday evenings. Now Grandma sometimes suggests a new subject. Nina still uses the same small camera. She does not need a more expensive one. Her favourite part is sharing an ordinary moment with someone she loves.","summary":"Nina 在家中观察并拍摄小事物，练习耐心，也通过照片与祖母分享日常生活。","questions":[{"prompt":"Where does Nina usually take her photos?","options":["At a railway station.","From her kitchen window.","On a mountain.","Inside her classroom."],"correctIndex":1,"explanation":"开头明确交代，她每周六早晨从厨房窗边拍照。","skill":"细节理解"},{"prompt":"What does Nina's uncle teach her?","options":["How to buy a new camera.","How to draw a cat.","How to wait for better light.","How to print a book."],"correctIndex":2,"explanation":"叔叔帮助她解决照片偏暗的问题，教她等待更合适的光线。","skill":"细节理解"},{"prompt":"How often does Nina choose a picture to describe?","options":["Once a week.","Every hour.","Twice a day.","Once a year."],"correctIndex":0,"explanation":"文中说她每周选一张照片，并写两句话描述它。","skill":"细节理解"},{"prompt":"Why does Nina send pictures to her grandmother?","options":["Grandma sells cameras.","Grandma asks her to stop taking photos.","Nina needs help with every sentence.","Grandma cannot go outside easily."],"correctIndex":3,"explanation":"文中先说明祖母不方便外出，再说 Nina 把照片发给她。","skill":"因果理解"},{"prompt":"What matters most to Nina about this hobby?","options":["Winning a large prize.","Sharing daily life with Grandma.","Owning the newest camera.","Visiting famous places."],"correctIndex":1,"explanation":"结尾说明她最喜欢的是与所爱的人分享普通时刻，因此情感交流比器材或旅行更重要。","skill":"推断"}]},"dialogue":{"title":"A Hobby to Try","turns":[{"speaker":"Owen","text":"You always bring a small notebook, Eva. Do you write stories in it?"},{"speaker":"Eva","text":"No. I draw buildings on my way home. I stop for ten minutes near the old bridge."},{"speaker":"Owen","text":"Does your sister draw with you? I often see you together."},{"speaker":"Eva","text":"She takes photos while I draw. We compare the details later, but we never copy each other's work."},{"speaker":"Owen","text":"I want to try. I do not draw well, and my pictures usually look strange."},{"speaker":"Eva","text":"That is fine. Start with one window or door. Our club meets on Friday, and beginners are welcome."}],"questions":[{"prompt":"What does Eva use her notebook for?","options":["Drawing buildings.","Writing shopping lists.","Planning meals.","Collecting phone numbers."],"correctIndex":0,"explanation":"Eva 否定了写故事的猜测，说明自己用本子画建筑。","skill":"细节理解"},{"prompt":"How long does Eva stop near the bridge?","options":["Five minutes.","Twenty minutes.","An hour.","Ten minutes."],"correctIndex":3,"explanation":"Eva 说她在老桥附近停留十分钟。","skill":"细节理解"},{"prompt":"What does Eva's sister do?","options":["She sells paintings.","She takes photos.","She reads stories.","She plays music."],"correctIndex":1,"explanation":"Eva 画画时，姐姐或妹妹在拍照，之后两人比较细节。","skill":"细节理解"},{"prompt":"When does the club meet?","options":["Monday.","Wednesday.","Friday.","Sunday."],"correctIndex":2,"explanation":"最后一轮说明俱乐部在周五活动。","skill":"细节理解"},{"prompt":"What does Eva think Owen should do?","options":["Begin with a small, simple subject.","Wait until he becomes an expert.","Buy an expensive camera first.","Copy her sister's photos."],"correctIndex":0,"explanation":"Eva 建议从一扇窗或一扇门开始，体现她鼓励初学者从简单对象入手。","skill":"推断"}]},"writing":{"prompt":"介绍你的一项爱好，写清练习时间、方式，以及它怎样改变了你的生活。","outline":["用 My hobby is… 点明爱好。","用一般现在时说明什么时候、怎样练习。","用一个具体例子说明收获。"],"model":"My hobby is making simple paper models. I practise for twenty minutes on Saturday afternoons. I usually make animals, but my brother likes houses. We keep our models in a box and choose one to show our family each week. Sometimes my model falls over, so I try a different shape. This hobby teaches me to be patient. It also gives my brother and me something enjoyable to do together without a screen."},"speakingPrompts":["What do you enjoy doing in your free time?","How do you practise your hobby?","Who would you like to share your hobby with, and why?"],"textbook":{"status":"edition-checked","referenceEdition":"2024 年第 1 版 · 2025 年 7 月第 2 次印刷","grammarScope":"一般现在时Ⅱ：实义动词、第三人称单数变化，do/does 否定与疑问句。","unitStartPage":18,"grammarPages":[23,24],"sections":[{"id":"welcome","label":"Welcome to the unit","labelZh":"导入","pageStart":19,"pageEnd":19,"pageLabel":"19"},{"id":"reading","label":"Reading","labelZh":"阅读","pageStart":20,"pageEnd":22,"pageLabel":"20–22"},{"id":"grammar","label":"Grammar","labelZh":"语法","pageStart":23,"pageEnd":24,"pageLabel":"23–24"},{"id":"pronunciation","label":"Pronunciation","labelZh":"语音","pageStart":25,"pageEnd":25,"pageLabel":"25","topicZh":"元音（二）"},{"id":"integration","label":"Integration","labelZh":"综合运用","pageStart":26,"pageEnd":28,"pageLabel":"26–28"},{"id":"assessment","label":"Assessment","labelZh":"评价","pageStart":29,"pageEnd":29,"pageLabel":"29"},{"id":"furtherStudy","label":"Further study","labelZh":"拓展学习","pageStart":29,"pageEnd":29,"pageLabel":"29"},{"id":"workbook","label":"Workbook","labelZh":"随书练习","pageStart":109,"pageEnd":111,"pageLabel":"109–111","location":"appendix"}]}},{"id":"7a-u3","bookId":"7a","number":3,"title":"Welcome to our school!","theme":"介绍校园，帮助访客找到所需地点","goals":["用人称代词主格和宾格避免重复","说明校园场所的位置与用途","设计一段清楚、有礼貌的校园介绍"],"grammarKeys":["pronouns_subject_object"],"vocabulary":[{"word":"hall","meaning":"大厅；礼堂","example":"We meet our visitors in the hall.","reviewId":0},{"word":"library","meaning":"图书馆","example":"The library has a quiet reading area.","reviewId":1},{"word":"laboratory","meaning":"实验室","example":"Our science laboratory is on the second floor.","reviewId":2},{"word":"playground","meaning":"操场","example":"The playground is behind the main building.","reviewId":3},{"word":"guide","meaning":"向导；引导","example":"A student guide shows us the music room.","reviewId":4},{"word":"visitor","meaning":"访客","example":"Each visitor receives a simple map.","reviewId":5},{"word":"borrow","meaning":"借入","example":"You can borrow two books today.","reviewId":6},{"word":"direction","meaning":"方向；指示","example":"The arrow shows the right direction.","reviewId":7}],"reading":{"id":"7a-u3-reading","title":"The Best Part of the Tour","level":"基础","text":"Our school has a visitors' morning once a term. This year, Sara and I are student guides. We prepare a route from the hall to the library, then to the science laboratory. Before the visitors arrive, a teacher tells us that the laboratory is closed for repairs. We cannot show them our experiments. Sara looks worried, but I remember our small garden. We take the visitors there instead. Students grow plants in old containers and measure them every week. Sara explains the project, and I show everyone our record book. A visitor asks who looks after the plants during holidays. Three classmates raise their hands. The garden is not the largest place at school, but it tells a clear story about us.","summary":"校园参观因实验室维修临时改变路线，小花园展示出同学们的合作与责任感。","questions":[{"prompt":"Who are the student guides?","options":["Three teachers.","The visitors.","Sara and the narrator.","A gardener and a teacher."],"correctIndex":2,"explanation":"第二句说明 Sara 和叙述者是本次学生向导。","skill":"细节理解"},{"prompt":"Why is the laboratory closed?","options":["It is being repaired.","It has no windows.","A test is taking place.","The visitors are late."],"correctIndex":0,"explanation":"老师说明实验室因维修关闭，因此原定路线需要改变。","skill":"细节理解"},{"prompt":"In 'We take the visitors there instead', where is 'there'?","options":["The hall.","The library.","The classroom.","The small garden."],"correctIndex":3,"explanation":"前一句提到叙述者想起小花园，因此 there 指代小花园。","skill":"指代理解"},{"prompt":"What does the narrator show the visitors?","options":["A holiday ticket.","The plant record book.","A new science film.","A large school trophy."],"correctIndex":1,"explanation":"Sara 讲解项目时，叙述者向大家展示记录册。","skill":"细节理解"},{"prompt":"Why is the garden a good part of the tour?","options":["It is the biggest place at school.","It needs no work during holidays.","It shows students working together and taking responsibility.","It contains every kind of plant."],"correctIndex":2,"explanation":"学生定期测量植物，还有同学负责假期照料；这些行动展示了合作和责任感。","skill":"推断"}]},"dialogue":{"title":"Showing a Visitor Around","turns":[{"speaker":"Guide","text":"Welcome, Mrs Green. I am Alex, your student guide. Would you like to visit the library first?"},{"speaker":"Visitor","text":"Yes, please. I can see two buildings. Which one has the library?"},{"speaker":"Guide","text":"The smaller one. It is beside the hall. Students can borrow books from it after lunch."},{"speaker":"Visitor","text":"Those students are carrying boxes. Are they taking books to the library?"},{"speaker":"Guide","text":"No. They are bringing art materials to the hall. Their teacher asked me to help them after this tour."},{"speaker":"Visitor","text":"Then let us keep our visit short. Please show me the reading area, and you can join them soon."}],"questions":[{"prompt":"What is Alex doing?","options":["Showing a visitor around.","Selling library books.","Teaching an art lesson.","Repairing a building."],"correctIndex":0,"explanation":"Alex 自我介绍为学生向导，并邀请访客先参观图书馆。","skill":"情境理解"},{"prompt":"Where is the library?","options":["Above the kitchen.","In the larger building.","Outside the school.","In the smaller building beside the hall."],"correctIndex":3,"explanation":"Alex 指出图书馆在较小的建筑里，位于礼堂旁边。","skill":"细节理解"},{"prompt":"When can students borrow books?","options":["Before sunrise.","After lunch.","Only on Sundays.","During the art show."],"correctIndex":1,"explanation":"第三轮明确说明学生午饭后可以借书。","skill":"细节理解"},{"prompt":"Who does 'them' mean in Alex's last turn?","options":["The buildings.","The visitors.","The students carrying boxes.","The books."],"correctIndex":2,"explanation":"老师让 Alex 帮助的是正在搬美术材料的学生，them 指这些学生。","skill":"指代理解"},{"prompt":"Why does the visitor suggest a short visit?","options":["She wants Alex to help the other students soon.","She thinks the school is boring.","She cannot find any books.","She wants to carry all the boxes alone."],"correctIndex":0,"explanation":"访客知道 Alex 稍后要帮助同学，因此缩短参观时间，让他尽快加入。","skill":"推断"}]},"writing":{"prompt":"为第一次来学校的访客介绍两个校园地点，说明位置、用途和一个你喜欢的细节。","outline":["欢迎访客，并介绍第一个地点。","用 it、we、they 或 them 衔接句子。","介绍第二个地点并说明你喜欢它的原因。"],"model":"Welcome to our school. The library is beside the main hall. It is small, but it has comfortable seats near the windows. We often read there after lunch. Our librarian knows many good stories, and we enjoy talking to her. Behind the library is a garden. Students look after it in small teams. You can see their names on the plant labels. I like this place because it shows how we learn and work together."},"speakingPrompts":["Which place would you show a visitor first?","How can you explain the way to your school library?","What does your favourite school place tell visitors about your school?"],"textbook":{"status":"edition-checked","referenceEdition":"2024 年第 1 版 · 2025 年 7 月第 2 次印刷","grammarScope":"人称代词的主格和宾格。","unitStartPage":30,"grammarPages":[35,36],"sections":[{"id":"welcome","label":"Welcome to the unit","labelZh":"导入","pageStart":31,"pageEnd":31,"pageLabel":"31"},{"id":"reading","label":"Reading","labelZh":"阅读","pageStart":32,"pageEnd":34,"pageLabel":"32–34"},{"id":"grammar","label":"Grammar","labelZh":"语法","pageStart":35,"pageEnd":36,"pageLabel":"35–36"},{"id":"pronunciation","label":"Pronunciation","labelZh":"语音","pageStart":37,"pageEnd":37,"pageLabel":"37","topicZh":"辅音（一）"},{"id":"integration","label":"Integration","labelZh":"综合运用","pageStart":38,"pageEnd":40,"pageLabel":"38–40"},{"id":"assessment","label":"Assessment","labelZh":"评价","pageStart":41,"pageEnd":41,"pageLabel":"41"},{"id":"furtherStudy","label":"Further study","labelZh":"拓展学习","pageStart":41,"pageEnd":41,"pageLabel":"41"},{"id":"workbook","label":"Workbook","labelZh":"随书练习","pageStart":112,"pageEnd":114,"pageLabel":"112–114","location":"appendix"}]}},{"id":"7a-u4","bookId":"7a","number":4,"title":"School days","theme":"安排学校日常，形成有节奏的学习习惯","goals":["用时间介词说明日期、时段和钟点","用频度副词描述日常活动","根据时间安排提出一个可实行的小改进"],"grammarKeys":["prepositions_time","frequency_adverbs"],"vocabulary":[{"word":"routine","meaning":"日常安排","example":"A simple routine helps me get ready.","reviewId":0},{"word":"usually","meaning":"通常","example":"I usually eat breakfast at seven.","reviewId":1},{"word":"sometimes","meaning":"有时","example":"We sometimes read outside at lunch.","reviewId":2},{"word":"seldom","meaning":"很少","example":"She seldom forgets her notebook.","reviewId":3},{"word":"prepare","meaning":"准备","example":"I prepare my bag in the evening.","reviewId":4},{"word":"break","meaning":"休息时间","example":"We talk quietly during the short break.","reviewId":5},{"word":"timetable","meaning":"课程表；时间表","example":"Our timetable is on the classroom wall.","reviewId":6},{"word":"balance","meaning":"平衡","example":"I try to balance study and rest.","reviewId":7}],"reading":{"id":"7a-u4-reading","title":"Five Minutes in the Evening","level":"基础","text":"Toby used to look for his school things every morning. Now he has a simple routine. At eight in the evening, he checks the next day's timetable. He puts the right books in his bag and leaves his shoes by the door. It takes about five minutes. In the morning, he usually has breakfast at seven and walks to school with his sister. On Tuesdays and Thursdays, he reads in the classroom before lessons. On Fridays, he helps water the plants instead. Toby still sometimes forgets small things, but he seldom forgets a book. His sister says he looks calmer now. Toby does not get up earlier. He simply makes one decision the night before, when he has more time to think.","summary":"Toby 每晚用五分钟检查课程表、准备书包，使第二天上学更从容。","questions":[{"prompt":"When does Toby check his timetable?","options":["At seven in the morning.","At eight in the evening.","At lunchtime.","After Friday's last lesson."],"correctIndex":1,"explanation":"文中明确写到，他晚上八点检查第二天的时间表。","skill":"细节理解"},{"prompt":"How long does his evening preparation take?","options":["About five minutes.","About thirty minutes.","Two hours.","All evening."],"correctIndex":0,"explanation":"准备书本和鞋子的日常安排大约需要五分钟。","skill":"细节理解"},{"prompt":"What does Toby do before lessons on Fridays?","options":["He buys new books.","He calls his sister.","He goes back home.","He helps water the plants."],"correctIndex":3,"explanation":"周二、周四他阅读；周五则帮忙浇植物。","skill":"细节理解"},{"prompt":"How often does Toby forget a book now?","options":["Always.","Usually.","Seldom.","Every Friday."],"correctIndex":2,"explanation":"文中说他有时仍忘小东西，但很少忘带书。","skill":"词义理解"},{"prompt":"Why is Toby calmer in the morning?","options":["His school starts later.","He prepares some things the night before.","His sister does all his homework.","He no longer carries any books."],"correctIndex":1,"explanation":"结尾强调他并未更早起床，而是在前一晚有更多思考时间时做好准备。","skill":"推断"}]},"dialogue":{"title":"Finding Time for the Club","turns":[{"speaker":"Maya","text":"Do you have time for the reading club on Thursday, Sam? It starts at twenty past four."},{"speaker":"Sam","text":"Usually, yes. My last lesson ends at four, but I sometimes help my teacher put away materials."},{"speaker":"Maya","text":"The club lasts forty minutes. You can arrive a few minutes late and join our small group."},{"speaker":"Sam","text":"That helps. I usually do my maths homework before dinner, so I need to leave at five."},{"speaker":"Maya","text":"That is exactly when we finish. This week we are discussing a story about a lost dog."},{"speaker":"Sam","text":"I will check with my teacher on Wednesday. If she needs help, I can prepare the materials at lunch."}],"questions":[{"prompt":"When does the reading club start?","options":["At 4:00 on Wednesday.","At 5:00 on Thursday.","At 4:20 on Thursday.","At 4:40 on Friday."],"correctIndex":2,"explanation":"Maya 说明俱乐部在周四四点二十分开始。","skill":"细节理解"},{"prompt":"Why might Sam be late?","options":["He sometimes helps his teacher after class.","He always misses the bus.","He has dinner at four.","He has a music lesson every Thursday."],"correctIndex":0,"explanation":"Sam 有时下课后帮助老师收拾材料，所以可能稍晚到。","skill":"因果理解"},{"prompt":"How long does the club last?","options":["Twenty minutes.","An hour.","Ten minutes.","Forty minutes."],"correctIndex":3,"explanation":"Maya 在第三轮给出活动持续四十分钟。","skill":"细节理解"},{"prompt":"When does Sam usually do maths homework?","options":["After midnight.","Before dinner.","During the club.","Only at weekends."],"correctIndex":1,"explanation":"Sam 说自己通常在晚餐前做数学作业。","skill":"细节理解"},{"prompt":"What does Sam's final idea show?","options":["He wants to stop helping his teacher.","He does not enjoy reading.","He is trying to make time for both responsibilities.","He plans to leave the club before it starts."],"correctIndex":2,"explanation":"Sam 提前询问老师，并考虑午间准备材料，说明他在协调助人责任与阅读活动。","skill":"推断"}]},"writing":{"prompt":"描述一个上学日的安排，并写出你准备尝试的一项小改变。","outline":["用 at、in 或 on 介绍两项日常活动的时间。","用 usually、sometimes 或 seldom 描述频率。","提出一个能帮助你更从容的小改变。"],"model":"On school days, I usually get up at half past six. I read for ten minutes before breakfast and leave home at seven twenty. At school, I enjoy talking with friends during the morning break. I sometimes feel rushed after dinner because I cannot find the right books. This week, I want to check my timetable before going to bed. A few quiet minutes in the evening may make the next morning easier."},"speakingPrompts":["What do you usually do before your first lesson?","Which part of your school day do you enjoy most?","What small change could make your daily routine easier?"],"textbook":{"status":"edition-checked","referenceEdition":"2024 年第 1 版 · 2025 年 7 月第 2 次印刷","grammarScope":"时间介词；频度副词。","unitStartPage":42,"grammarPages":[47,48],"sections":[{"id":"welcome","label":"Welcome to the unit","labelZh":"导入","pageStart":43,"pageEnd":43,"pageLabel":"43"},{"id":"reading","label":"Reading","labelZh":"阅读","pageStart":44,"pageEnd":46,"pageLabel":"44–46"},{"id":"grammar","label":"Grammar","labelZh":"语法","pageStart":47,"pageEnd":48,"pageLabel":"47–48"},{"id":"pronunciation","label":"Pronunciation","labelZh":"语音","pageStart":49,"pageEnd":49,"pageLabel":"49","topicZh":"元音（三）"},{"id":"integration","label":"Integration","labelZh":"综合运用","pageStart":50,"pageEnd":52,"pageLabel":"50–52"},{"id":"assessment","label":"Assessment","labelZh":"评价","pageStart":53,"pageEnd":53,"pageLabel":"53"},{"id":"furtherStudy","label":"Further study","labelZh":"拓展学习","pageStart":53,"pageEnd":53,"pageLabel":"53"},{"id":"workbook","label":"Workbook","labelZh":"随书练习","pageStart":115,"pageEnd":117,"pageLabel":"115–117","location":"appendix"}]}},{"id":"7a-u5","bookId":"7a","number":5,"title":"A healthy lifestyle","theme":"认识食物与数量，观察自己的生活习惯","goals":["区分可数名词和不可数名词","用恰当的量词描述食物和饮品","具体描述饮食、活动与休息的日常安排"],"grammarKeys":["countable_uncountable"],"vocabulary":[{"word":"meal","meaning":"一餐","example":"We talk about our favourite meal.","reviewId":0},{"word":"vegetable","meaning":"蔬菜","example":"There are three kinds of vegetables on the menu.","reviewId":1},{"word":"fruit","meaning":"水果","example":"I put some fruit in my lunch box.","reviewId":2},{"word":"rice","meaning":"米饭；大米","example":"There is some rice in the bowl.","reviewId":3},{"word":"bowl","meaning":"碗","example":"I ask for a small bowl of soup.","reviewId":4},{"word":"piece","meaning":"片；块；件","example":"May I have a piece of bread?","reviewId":5},{"word":"energy","meaning":"精力；能量","example":"After a good night's sleep, I have more energy.","reviewId":6},{"word":"habit","meaning":"习惯","example":"Taking a short walk is a daily habit for me.","reviewId":7}],"reading":{"id":"7a-u5-reading","title":"A Different Lunch Question","level":"基础","text":"At Hill School, each lunch table has a small card. It does not tell students how much they must eat. Instead, it asks, 'What would you like to try today?' Leo usually chooses rice and chicken. One Monday, he notices a vegetable soup on the menu. He asks for a small bowl and a piece of bread. His friend Ada chooses an apple and some noodles. They talk about the colours and tastes of their meals. Leo likes the soup, so he asks the cook what is in it. The cook writes three vegetable names on his card. That evening, Leo shows the card to his father. They decide to make a similar soup at the weekend. A simple lunch question has given them a new activity.","summary":"午餐桌上的一个开放问题，让 Leo 尝试蔬菜汤，并把这次体验变成家庭烹饪活动。","questions":[{"prompt":"What does the card ask students?","options":["How much they must eat.","How much their lunch costs.","What they would like to try.","Who eats the fastest."],"correctIndex":2,"explanation":"桌卡不规定食量，而是询问学生今天想尝试什么。","skill":"细节理解"},{"prompt":"What does Leo usually choose?","options":["Rice and chicken.","Noodles and an apple.","Soup and bread.","Only vegetables."],"correctIndex":0,"explanation":"文中明确说明 Leo 平时选择米饭和鸡肉。","skill":"细节理解"},{"prompt":"What does Ada choose on Monday?","options":["Rice and milk.","An apple and some noodles.","Chicken and bread.","Three bowls of soup."],"correctIndex":1,"explanation":"Ada 在这一餐选择了一个苹果和一些面条。","skill":"细节理解"},{"prompt":"What does the cook write on Leo's card?","options":["A phone number.","A new timetable.","The price of lunch.","Three vegetable names."],"correctIndex":3,"explanation":"厨师在卡片上写下汤里三种蔬菜的名称。","skill":"细节理解"},{"prompt":"What does the ending suggest?","options":["Leo wants to stop eating at school.","Ada dislikes all new food.","A small new experience can lead to a shared activity.","The cook will visit Leo every weekend."],"correctIndex":2,"explanation":"Leo 与爸爸决定周末做类似的汤，说明学校里的一次尝试延伸成了家庭共同活动。","skill":"推断"}]},"dialogue":{"title":"Preparing Fruit Cups","turns":[{"speaker":"Ella","text":"We are making fruit cups for six classmates. How many apples do we have, Tom?"},{"speaker":"Tom","text":"Six apples and three bananas. There is also some plain yoghurt in the fridge."},{"speaker":"Ella","text":"Let us use one apple for each cup and cut every banana into two equal parts."},{"speaker":"Tom","text":"Then each cup can have half a banana. Do we need any juice?"},{"speaker":"Ella","text":"No. We have water to drink. Please put the yoghurt in a separate bowl so everyone can choose."},{"speaker":"Tom","text":"Good idea. I will write the ingredients on a card and put six spoons beside the cups."}],"questions":[{"prompt":"How many classmates are the fruit cups for?","options":["Three.","Six.","Eight.","Twelve."],"correctIndex":1,"explanation":"Ella 开头说明要为六位同学制作水果杯。","skill":"细节理解"},{"prompt":"How much banana will each cup have?","options":["Two bananas.","One whole banana.","A quarter of a banana.","Half a banana."],"correctIndex":3,"explanation":"三根香蕉各分为两半，共六份，因此每杯半根。","skill":"数量理解"},{"prompt":"Where will the yoghurt go?","options":["In a separate bowl.","Into every cup at once.","Into the water bottle.","Back to the shop."],"correctIndex":0,"explanation":"Ella 要求酸奶单独放在一个碗里，让每个人自行选择。","skill":"细节理解"},{"prompt":"What will the classmates drink?","options":["Orange juice.","Milk.","Water.","Hot soup."],"correctIndex":2,"explanation":"对话明确说不需要果汁，因为已有水。","skill":"细节理解"},{"prompt":"Why is the yoghurt kept separate?","options":["Nobody is allowed to try it.","The classmates can make their own choice.","There are no bowls.","It is needed for a science experiment."],"correctIndex":1,"explanation":"Ella 明确说明目的是让每个人选择是否添加，体现对个人选择的尊重。","skill":"意图理解"}]},"writing":{"prompt":"写一段关于自己日常生活的观察，介绍一餐、一次活动和一项休息习惯。","outline":["用数量表达介绍一餐，例如 a bowl of… 或 some…。","说明你通常怎样活动身体。","写出一个你愿意继续观察或调整的生活习惯。"],"model":"On most school mornings, I have an egg, some bread and a glass of milk. I choose different food when my family has more time at weekends. After school, I enjoy walking with my neighbour and talking about our day. In the evening, I put my phone away before reading in bed. I am learning to notice when I feel tired. I want to keep a simple diary of my meals, activities and rest this week."},"speakingPrompts":["What do you usually have for breakfast?","What new food would you like to learn to make?","How do you make time for activity and rest on a school day?"],"textbook":{"status":"edition-checked","referenceEdition":"2024 年第 1 版 · 2025 年 7 月第 2 次印刷","grammarScope":"可数名词与不可数名词及数量表达。","unitStartPage":56,"grammarPages":[61,62],"sections":[{"id":"welcome","label":"Welcome to the unit","labelZh":"导入","pageStart":57,"pageEnd":57,"pageLabel":"57"},{"id":"reading","label":"Reading","labelZh":"阅读","pageStart":58,"pageEnd":60,"pageLabel":"58–60"},{"id":"grammar","label":"Grammar","labelZh":"语法","pageStart":61,"pageEnd":62,"pageLabel":"61–62"},{"id":"pronunciation","label":"Pronunciation","labelZh":"语音","pageStart":63,"pageEnd":63,"pageLabel":"63","topicZh":"辅音（二）"},{"id":"integration","label":"Integration","labelZh":"综合运用","pageStart":64,"pageEnd":66,"pageLabel":"64–66"},{"id":"assessment","label":"Assessment","labelZh":"评价","pageStart":67,"pageEnd":67,"pageLabel":"67"},{"id":"furtherStudy","label":"Further study","labelZh":"拓展学习","pageStart":67,"pageEnd":67,"pageLabel":"67"},{"id":"workbook","label":"Workbook","labelZh":"随书练习","pageStart":118,"pageEnd":120,"pageLabel":"118–120","location":"appendix"}]}},{"id":"7a-u6","bookId":"7a","number":6,"title":"My clothes, my style","theme":"根据场合选择衣着，表达个人风格","goals":["区分一般疑问句、特殊疑问句和选择疑问句","说明衣物的颜色、特点和用途","用问题了解他人的衣着选择并给出理由"],"grammarKeys":["question_words"],"vocabulary":[{"word":"jacket","meaning":"夹克衫","example":"My jacket has two deep pockets.","reviewId":0},{"word":"pocket","meaning":"口袋","example":"I keep a small notebook in my pocket.","reviewId":1},{"word":"comfortable","meaning":"舒适的","example":"These shoes are comfortable for walking.","reviewId":2},{"word":"style","meaning":"风格","example":"Simple colours are part of her style.","reviewId":3},{"word":"match","meaning":"相配","example":"The blue scarf matches my coat.","reviewId":4},{"word":"button","meaning":"纽扣","example":"One button is missing from the shirt.","reviewId":5},{"word":"scarf","meaning":"围巾","example":"He wears a soft scarf on cold days.","reviewId":6},{"word":"bright","meaning":"鲜亮的；明亮的","example":"I choose a bright orange hat.","reviewId":7}],"reading":{"id":"7a-u6-reading","title":"The Star on the Pocket","level":"基础","text":"Mira needs a jacket for her class walk by the lake. She finds an old green one in the cupboard. It is comfortable, but there is a small hole near the pocket. Her brother suggests buying a new jacket. Mira has another idea. With her grandmother's help, she covers the hole with a yellow cloth star. They also replace a loose button. At school, a classmate asks where she bought the unusual jacket. Mira explains the story and shows the neat stitches. Soon two friends ask her how to repair their clothes. Mira likes bright colours, but she does not need every item to be new. On the walk, her notebook fits inside the repaired pocket. The star makes the jacket different, and the pocket still does its job.","summary":"Mira 修补旧夹克，并用一颗黄色布星表达自己的风格，让衣物同时保有实用性。","questions":[{"prompt":"Why does Mira need a jacket?","options":["For a class walk by the lake.","For a swimming lesson.","For a stage dance.","For a trip to a clothes factory."],"correctIndex":0,"explanation":"开头说明她需要穿夹克参加班级湖边步行活动。","skill":"细节理解"},{"prompt":"What is wrong with the old jacket?","options":["It has no sleeves.","It has a hole near the pocket.","It is too small to wear.","Its colour has completely disappeared."],"correctIndex":1,"explanation":"文中说夹克穿着舒适，但口袋附近有一个小洞。","skill":"细节理解"},{"prompt":"Who helps Mira repair it?","options":["Her classmate.","Her brother.","Her grandmother.","Her teacher."],"correctIndex":2,"explanation":"Mira 在祖母帮助下用布星补洞，还换了松动的纽扣。","skill":"细节理解"},{"prompt":"What does Mira put in the pocket during the walk?","options":["A camera.","A new button.","A cloth star.","Her notebook."],"correctIndex":3,"explanation":"结尾提到她的笔记本正好放进修补好的口袋。","skill":"细节理解"},{"prompt":"What can we infer about Mira's idea of style?","options":["Clothes can be useful and personal without being new.","Only expensive clothes can look unusual.","Every jacket must have a yellow star.","Repairing clothes always makes them uncomfortable."],"correctIndex":0,"explanation":"Mira 喜欢色彩，用修补表达个人特点，同时保留口袋用途，说明风格不一定依靠新衣。","skill":"推断"}]},"dialogue":{"title":"Choosing Clothes for an Outdoor Talk","turns":[{"speaker":"Dan","text":"Is our class talk indoors or outdoors tomorrow, Rosa? I am choosing my clothes."},{"speaker":"Rosa","text":"Outdoors, in the school garden. We are meeting at nine, and it may be cool in the morning."},{"speaker":"Dan","text":"Which looks better with my grey trousers, the blue jacket or the red one?"},{"speaker":"Rosa","text":"I like the blue one. Its pockets are useful for your cards, and you can move your arms easily in it."},{"speaker":"Dan","text":"Good point. Why are you bringing a green scarf? Is it part of your talk?"},{"speaker":"Rosa","text":"Yes. My talk is about reusing cloth. My aunt made this scarf from a piece she did not need."}],"questions":[{"prompt":"Where will the class talk take place?","options":["In a theatre.","In a shopping centre.","In the school garden.","In the library."],"correctIndex":2,"explanation":"Rosa 说活动在户外的学校花园举行。","skill":"细节理解"},{"prompt":"What time will the class meet?","options":["At nine.","At ten.","At eight.","At eleven."],"correctIndex":0,"explanation":"第二轮给出集合时间为九点。","skill":"细节理解"},{"prompt":"Which jacket does Rosa prefer?","options":["The grey one.","The green one.","The red one.","The blue one."],"correctIndex":3,"explanation":"Rosa 回答自己更喜欢蓝色夹克。","skill":"细节理解"},{"prompt":"Why is Rosa bringing the scarf?","options":["She plans to sell it.","It is an example for her talk.","Dan asks to borrow it.","It belongs to the school."],"correctIndex":1,"explanation":"Rosa 的发言主题是布料再利用，围巾正是姨妈用剩余布料制作的例子。","skill":"意图理解"},{"prompt":"What matters in Rosa's advice about the jacket?","options":["Only its price.","Only its brand.","Its colour, useful pockets and comfort.","Whether every classmate owns one."],"correctIndex":2,"explanation":"Rosa 既评价颜色，又提到放卡片的口袋及手臂活动方便，体现实用性和舒适度。","skill":"信息整合"}]},"writing":{"prompt":"为一次校园活动选择一套衣着，介绍颜色、实用细节和你的选择理由。","outline":["说明活动场合和衣物选择。","用两个问题引出颜色或功能，例如 Why…? Which…?","用 because 说明舒适度、用途或个人风格。"],"model":"Our class is visiting a park on Saturday. I want to wear a blue jacket, dark trousers and comfortable shoes. Why do I choose the jacket? It has large pockets for my notebook and a small map. Which hat should I take, the black one or the yellow one? I prefer the yellow one because I like its bright colour. These clothes are simple, but they help me feel comfortable and ready for the day."},"speakingPrompts":["What do you usually wear for an outdoor school activity?","Which item of clothing shows your personal style?","What questions would you ask before choosing clothes for an event?"],"textbook":{"status":"edition-checked","referenceEdition":"2024 年第 1 版 · 2025 年 7 月第 2 次印刷","grammarScope":"一般疑问句、特殊疑问句、选择疑问句三类问句。","unitStartPage":68,"grammarPages":[73,74],"sections":[{"id":"welcome","label":"Welcome to the unit","labelZh":"导入","pageStart":69,"pageEnd":69,"pageLabel":"69"},{"id":"reading","label":"Reading","labelZh":"阅读","pageStart":70,"pageEnd":72,"pageLabel":"70–72"},{"id":"grammar","label":"Grammar","labelZh":"语法","pageStart":73,"pageEnd":74,"pageLabel":"73–74"},{"id":"pronunciation","label":"Pronunciation","labelZh":"语音","pageStart":75,"pageEnd":75,"pageLabel":"75","topicZh":"元音（四）"},{"id":"integration","label":"Integration","labelZh":"综合运用","pageStart":76,"pageEnd":78,"pageLabel":"76–78"},{"id":"assessment","label":"Assessment","labelZh":"评价","pageStart":79,"pageEnd":79,"pageLabel":"79"},{"id":"furtherStudy","label":"Further study","labelZh":"拓展学习","pageStart":79,"pageEnd":79,"pageLabel":"79"},{"id":"workbook","label":"Workbook","labelZh":"随书练习","pageStart":121,"pageEnd":123,"pageLabel":"121–123","location":"appendix"}]}},{"id":"7a-u7","bookId":"7a","number":7,"title":"Be wise with money","theme":"区分需要与想要，记录一次合理消费","goals":["在情境中使用 some、any 和 there be","读懂简单价格信息并说明购买理由","用预算和记录描述一次消费决定"],"grammarKeys":["some_any","there_be"],"vocabulary":[{"word":"budget","meaning":"预算","example":"Our group has a budget of thirty yuan.","reviewId":0},{"word":"price","meaning":"价格","example":"I compare the prices of two notebooks.","reviewId":1},{"word":"cost","meaning":"价钱为；花费","example":"The string costs four yuan.","reviewId":2},{"word":"save","meaning":"节省；储蓄","example":"We save the remaining money for another project.","reviewId":3},{"word":"spend","meaning":"花费","example":"I spend five yuan on a useful folder.","reviewId":4},{"word":"choice","meaning":"选择","example":"We explain our choice to the class.","reviewId":5},{"word":"receipt","meaning":"收据","example":"I keep the receipt in my notebook.","reviewId":6},{"word":"reusable","meaning":"可重复使用的","example":"This reusable bag holds our art materials.","reviewId":7}],"reading":{"id":"7a-u7-reading","title":"A Welcome Sign for Ten Yuan","level":"基础","text":"Class Seven has thirty yuan for a welcome display. In a shop, a colourful banner costs eighteen yuan. It looks attractive, but Lin asks everyone to check their classroom first. There is some old cardboard in a cupboard, and there are several pots of paint. There is not any string. The group decides to make its own sign. They spend four yuan on string and six yuan on blank name cards. Each student paints one letter, while Lin writes the costs in a notebook. The finished display is not exactly straight, but every name is easy to read. Twenty yuan remains for another class project. Lin keeps the receipt beside a photo of their work. The group is proud of both the sign and the decision behind it.","summary":"同学们先检查已有材料，再花十元制作欢迎展示，记录支出并保留余款。","questions":[{"prompt":"What is the group's original budget?","options":["Ten yuan.","Eighteen yuan.","Twenty yuan.","Thirty yuan."],"correctIndex":3,"explanation":"开头说明班级欢迎展示的预算是三十元。","skill":"细节理解"},{"prompt":"What does Lin ask the group to do before buying the banner?","options":["Check the classroom for materials.","Borrow money from visitors.","Choose the largest shop.","Cancel the project."],"correctIndex":0,"explanation":"Lin 建议大家先检查教室里已有的材料。","skill":"细节理解"},{"prompt":"Which item is missing from the classroom?","options":["Cardboard.","String.","Paint.","A cupboard."],"correctIndex":1,"explanation":"教室有旧纸板和几罐颜料，但没有绳子。","skill":"细节理解"},{"prompt":"How much money remains after the purchases?","options":["Six yuan.","Ten yuan.","Twenty yuan.","Twenty-six yuan."],"correctIndex":2,"explanation":"绳子四元，姓名卡六元，共十元；三十元减十元剩二十元。","skill":"数量理解"},{"prompt":"What makes the group's decision thoughtful?","options":["They choose the most expensive banner.","They spend every yuan immediately.","They avoid keeping any records.","They use existing materials and record the necessary costs."],"correctIndex":3,"explanation":"先盘点已有材料，只购买缺少的物品，并记录支出、保存收据，体现了有依据的消费决定。","skill":"推断"}]},"dialogue":{"title":"Checking the Total","turns":[{"speaker":"Nora","text":"I have fifteen yuan. I need two exercise books and a pen for our writing club."},{"speaker":"Shopkeeper","text":"There are some exercise books on this shelf. The plain ones are four yuan each, and the picture ones are seven."},{"speaker":"Nora","text":"The plain ones are fine. Do you have any black pens that cost three yuan?"},{"speaker":"Shopkeeper","text":"Yes. There are some in the box beside you. Two plain books and one black pen cost eleven yuan altogether."},{"speaker":"Nora","text":"I will take those, please. There are pretty stickers too, but I do not need them for the club."},{"speaker":"Shopkeeper","text":"Here are your things, your receipt and four yuan change. You can check the total on the receipt."}],"questions":[{"prompt":"What does Nora need?","options":["Two pens and one picture book.","Two exercise books and a pen.","A sticker album.","Four notebooks and a ruler."],"correctIndex":1,"explanation":"Nora 开头说明需要两本练习本和一支笔。","skill":"细节理解"},{"prompt":"How much is one plain exercise book?","options":["Three yuan.","Seven yuan.","Four yuan.","Eleven yuan."],"correctIndex":2,"explanation":"店主说明普通封面的练习本每本四元。","skill":"细节理解"},{"prompt":"Where are the three-yuan black pens?","options":["In the box beside Nora.","Behind the shop door.","Inside the exercise books.","Under the receipt."],"correctIndex":0,"explanation":"店主指向 Nora 身旁的盒子，里面有符合价格的黑笔。","skill":"细节理解"},{"prompt":"How much change does Nora receive?","options":["One yuan.","Three yuan.","Eleven yuan.","Four yuan."],"correctIndex":3,"explanation":"她带十五元，购买总额十一元，找回四元。","skill":"数量理解"},{"prompt":"Why does Nora leave the stickers?","options":["They are not for sale.","She focuses on what she needs for the club.","She does not have any money left.","The shopkeeper refuses to sell them."],"correctIndex":1,"explanation":"Nora 认为贴纸好看，但明确说活动用不到，说明她在区分需要和想要。","skill":"推断"}]},"writing":{"prompt":"记录一次小额购买或班级采购，写出预算、已有物品、实际购买和余款用途。","outline":["说明你要完成什么任务以及预算。","用 there be 和 some/any 描述已有或缺少的物品。","记录选择、总花费和理由。"],"model":"Our group has twenty yuan to make a reading display. There is some coloured paper in our classroom, but there are not any clips. We decide to use the paper we already have. At the shop, we buy a small packet of clips for six yuan. We keep fourteen yuan for another activity. I write the cost in our group notebook and keep the receipt. Our display looks simple, and everyone can explain how we used the money."},"speakingPrompts":["How do you decide whether you need something?","What could your class reuse before buying new materials?","Why might it be useful to keep a receipt or a spending record?"],"textbook":{"status":"edition-checked","referenceEdition":"2024 年第 1 版 · 2025 年 7 月第 2 次印刷","grammarScope":"some/any；there be 结构。","unitStartPage":80,"grammarPages":[85,86],"sections":[{"id":"welcome","label":"Welcome to the unit","labelZh":"导入","pageStart":81,"pageEnd":81,"pageLabel":"81"},{"id":"reading","label":"Reading","labelZh":"阅读","pageStart":82,"pageEnd":84,"pageLabel":"82–84"},{"id":"grammar","label":"Grammar","labelZh":"语法","pageStart":85,"pageEnd":86,"pageLabel":"85–86"},{"id":"pronunciation","label":"Pronunciation","labelZh":"语音","pageStart":87,"pageEnd":87,"pageLabel":"87","topicZh":"辅音（三）"},{"id":"integration","label":"Integration","labelZh":"综合运用","pageStart":88,"pageEnd":90,"pageLabel":"88–90"},{"id":"assessment","label":"Assessment","labelZh":"评价","pageStart":91,"pageEnd":91,"pageLabel":"91"},{"id":"furtherStudy","label":"Further study","labelZh":"拓展学习","pageStart":91,"pageEnd":91,"pageLabel":"91"},{"id":"workbook","label":"Workbook","labelZh":"随书练习","pageStart":124,"pageEnd":126,"pageLabel":"124–126","location":"appendix"}]}},{"id":"7a-u8","bookId":"7a","number":8,"title":"Let’s celebrate!","theme":"参与庆祝活动，关注每个人的体验","goals":["用现在进行时描述正在进行的活动","根据现场细节理解人物分工和感受","写一段庆祝活动的现场报道"],"grammarKeys":["present_continuous"],"vocabulary":[{"word":"celebrate","meaning":"庆祝","example":"We celebrate the end of our reading project.","reviewId":0},{"word":"decorate","meaning":"装饰","example":"They are decorating the community room.","reviewId":1},{"word":"lantern","meaning":"灯笼","example":"A paper lantern hangs beside the door.","reviewId":2},{"word":"invitation","meaning":"邀请；请柬","example":"I am writing an invitation for our neighbours.","reviewId":3},{"word":"prepare","meaning":"准备","example":"My friends are preparing a short performance.","reviewId":4},{"word":"perform","meaning":"表演","example":"Two students are performing a funny play.","reviewId":5},{"word":"wish","meaning":"愿望；祝愿","example":"She writes a kind wish on the card.","reviewId":6},{"word":"together","meaning":"一起","example":"We are making the display together.","reviewId":7}],"reading":{"id":"7a-u8-reading","title":"A Place for Every Wish","level":"基础","text":"It is the evening of our neighbourhood's autumn celebration. People are carrying chairs into the community room. Near the door, Lila is hanging paper lanterns. Her brother is playing a short tune on his flute. I am helping children put wish cards on a large board. One small boy, Sam, is standing back and holding a blank card. I ask if he needs a pen. He shakes his head and points to the board. It is too high for him. Lila notices us and moves the board to a lower table. Sam draws a picture of a dog and puts his card in the middle. Soon other children are adding pictures beside it. The room is getting noisier, but Sam is smiling. His wish now has a place too.","summary":"庆祝活动中，大家发现小朋友够不到心愿板，便调整布置，让他也能参与。","questions":[{"prompt":"Where is the celebration taking place?","options":["In a railway station.","In the school library.","In a community room.","On a boat."],"correctIndex":2,"explanation":"人们正把椅子搬进社区活动室，故事在这里展开。","skill":"细节理解"},{"prompt":"What is Lila doing near the door at first?","options":["Hanging paper lanterns.","Writing invitations.","Playing the flute.","Serving soup."],"correctIndex":0,"explanation":"开头描写 Lila 在门边挂纸灯笼。","skill":"细节理解"},{"prompt":"Why is Sam standing back?","options":["He has lost his card.","He does not like drawing.","He is waiting for a dog.","The wish board is too high for him."],"correctIndex":3,"explanation":"Sam 指向心愿板，随后叙述说明它对他来说太高了。","skill":"因果理解"},{"prompt":"What does Sam draw?","options":["A lantern.","A dog.","A flute.","A chair."],"correctIndex":1,"explanation":"板子移低后，Sam 画了一只狗并把卡片贴在中间。","skill":"细节理解"},{"prompt":"Why is Sam probably smiling at the end?","options":["The celebration has finished.","He has won a drawing prize.","He can now take part in the shared activity.","The room has become completely quiet."],"correctIndex":2,"explanation":"Sam 原本无法贴卡片，调整后成功参与并看到其他孩子加入，可推断他因被接纳而高兴。","skill":"推断"}]},"dialogue":{"title":"Before the Celebration Begins","turns":[{"speaker":"June","text":"What are you doing with those cards, Ravi? The guests are arriving in ten minutes."},{"speaker":"Ravi","text":"I am putting names on the tables. My cousin is checking the music, and Dad is moving the chairs."},{"speaker":"June","text":"Are you making a place for Mrs Hall near the front? She wants to watch the children's dance."},{"speaker":"Ravi","text":"Yes. Her card is on this table. Why are you carrying a basket of small paper flowers?"},{"speaker":"June","text":"The children are giving one to each guest. They made the flowers during yesterday's art club."},{"speaker":"Ravi","text":"Lovely. I am finishing the last table now. After that, I can help them welcome everyone at the door."}],"questions":[{"prompt":"When are the guests arriving?","options":["In an hour.","In ten minutes.","Tomorrow morning.","After two days."],"correctIndex":1,"explanation":"June 开头说明客人将在十分钟后到达。","skill":"细节理解"},{"prompt":"What is Ravi's cousin doing?","options":["Moving chairs.","Making paper flowers.","Writing wish cards.","Checking the music."],"correctIndex":3,"explanation":"Ravi 介绍分工时说表亲正在检查音乐。","skill":"细节理解"},{"prompt":"Why does Mrs Hall want a place near the front?","options":["To watch the children's dance.","To sell paper flowers.","To leave before the guests arrive.","To repair the tables."],"correctIndex":0,"explanation":"June 说明 Mrs Hall 想观看孩子们的舞蹈。","skill":"细节理解"},{"prompt":"When did the children make the flowers?","options":["Last month.","This morning.","During yesterday's art club.","While the guests were arriving."],"correctIndex":2,"explanation":"June 说纸花是在昨天的美术社团活动中制作的。","skill":"细节理解"},{"prompt":"What can we infer about Ravi?","options":["He is refusing to help anyone.","He is ready to help with another job after finishing his own.","He has forgotten every guest's name.","He wants to cancel the dance."],"correctIndex":1,"explanation":"他打算完成桌牌工作后到门口帮忙迎客，说明愿意继续协作。","skill":"推断"}]},"writing":{"prompt":"想象你正在参加一次班级或社区庆祝活动，给未到场的朋友写一段现场消息。","outline":["说明地点、活动和此刻的气氛。","用 am/is/are doing 描述至少三人的活动。","补充一个温暖或有趣的细节。"],"model":"Hello, Mia! We are celebrating our reading month in the school hall. Some students are putting their favourite book covers on a board. Our teacher is taking photos, and two classmates are preparing a short play. I am helping at the welcome table. A younger student is showing us a tiny book she made herself. Everyone is asking her questions. The hall is busy and cheerful. I hope you can join us before the play begins."},"speakingPrompts":["What are people doing at a celebration you can imagine?","How can you help someone join a group activity?","What kind of celebration would your class like to organise?"],"textbook":{"status":"edition-checked","referenceEdition":"2024 年第 1 版 · 2025 年 7 月第 2 次印刷","grammarScope":"现在进行时。","unitStartPage":92,"grammarPages":[97,98],"sections":[{"id":"welcome","label":"Welcome to the unit","labelZh":"导入","pageStart":93,"pageEnd":93,"pageLabel":"93"},{"id":"reading","label":"Reading","labelZh":"阅读","pageStart":94,"pageEnd":96,"pageLabel":"94–96"},{"id":"grammar","label":"Grammar","labelZh":"语法","pageStart":97,"pageEnd":98,"pageLabel":"97–98"},{"id":"pronunciation","label":"Pronunciation","labelZh":"语音","pageStart":99,"pageEnd":99,"pageLabel":"99","topicZh":"/w/ 与 /v/"},{"id":"integration","label":"Integration","labelZh":"综合运用","pageStart":100,"pageEnd":102,"pageLabel":"100–102"},{"id":"assessment","label":"Assessment","labelZh":"评价","pageStart":103,"pageEnd":103,"pageLabel":"103"},{"id":"furtherStudy","label":"Further study","labelZh":"拓展学习","pageStart":103,"pageEnd":103,"pageLabel":"103"},{"id":"workbook","label":"Workbook","labelZh":"随书练习","pageStart":127,"pageEnd":129,"pageLabel":"127–129","location":"appendix"}]}},{"id":"7b-u1","bookId":"7b","number":1,"title":"Home","theme":"用数字和细节介绍温暖的家","goals":["读写日常地址、数量中的基数词","用序数词说明楼层和顺序","结合位置、房间和生活细节介绍自己的家"],"grammarKeys":["numbers_cardinal_ordinal"],"vocabulary":[{"word":"address","meaning":"地址","example":"I write our new address clearly.","reviewId":0},{"word":"floor","meaning":"楼层；地板","example":"Our flat is on the fourth floor.","reviewId":1},{"word":"entrance","meaning":"入口","example":"The entrance is beside the small tree.","reviewId":2},{"word":"balcony","meaning":"阳台","example":"We grow two plants on the balcony.","reviewId":3},{"word":"bedroom","meaning":"卧室","example":"My bedroom has a desk near the window.","reviewId":4},{"word":"kitchen","meaning":"厨房","example":"My father is cooking in the kitchen.","reviewId":5},{"word":"shelf","meaning":"架子","example":"The photo is on the second shelf.","reviewId":6},{"word":"welcome","meaning":"欢迎","example":"A small card says welcome to our home.","reviewId":7}],"reading":{"id":"7b-u1-reading","title":"Numbers on the Welcome Card","level":"基础","text":"Mei's grandparents are visiting her family's new home on Saturday. The family lives in Building Twenty-eight, in Flat 403 on the fourth floor. Mei writes these numbers on a welcome card. She also draws the entrance and the lift, because her grandparents have never visited the building. Inside the flat, there are two bedrooms and a small study. Mei's favourite place is the balcony, where she keeps three pots of flowers. Before lunch, she puts four plates on the table as usual. Then she laughs and adds two more for her grandparents. When they arrive, Grandpa holds up her card. 'We found every number,' he says. Grandma points to Mei's little flower drawings. She says those pictures made the new address feel like a home already.","summary":"Mei 为祖父母制作包含楼栋、楼层和图画的欢迎卡，用清楚的信息和温暖细节介绍新家。","questions":[{"prompt":"Which building does Mei's family live in?","options":["Building Four.","Building Twenty-eight.","Building Three.","Building Forty-three."],"correctIndex":1,"explanation":"开头给出楼栋号为二十八。","skill":"细节理解"},{"prompt":"On which floor is Flat 403?","options":["The first floor.","The second floor.","The fourth floor.","The third floor."],"correctIndex":2,"explanation":"文中明确说明 403 室位于四楼。","skill":"细节理解"},{"prompt":"What is Mei's favourite place in the flat?","options":["The balcony.","The kitchen.","The study.","The lift."],"correctIndex":0,"explanation":"Mei 最喜欢阳台，那里放着三盆花。","skill":"细节理解"},{"prompt":"How many plates does Mei put on the table in total?","options":["Two.","Three.","Four.","Six."],"correctIndex":3,"explanation":"她先摆了平时用的四个盘子，又为祖父母增加两个，共六个。","skill":"数量理解"},{"prompt":"Why does Grandma like the card's flower pictures?","options":["They replace all the numbers.","They make the address feel personal and welcoming.","They show where to buy flowers.","They explain how the lift works."],"correctIndex":1,"explanation":"祖母说小花图让新地址已经有了家的感觉，说明图画传递出熟悉、温暖的欢迎。","skill":"推断"}]},"dialogue":{"title":"Finding My New Home","turns":[{"speaker":"Ben","text":"I am coming to your home after lunch, Anya. Is your building number fifteen or fifty?"},{"speaker":"Anya","text":"Fifteen. Our flat is 302, on the third floor. The building has five floors altogether."},{"speaker":"Ben","text":"Thanks. Which entrance should I use? I can see two on your drawing."},{"speaker":"Anya","text":"Use the second entrance, beside the blue noticeboard. Take the lift to the third floor, and our door is on the right."},{"speaker":"Ben","text":"I have got it. Fifteen, three hundred and two, third floor, second entrance. Shall I bring my board game?"},{"speaker":"Anya","text":"Yes, please. There will be four of us, and I have a table with four chairs ready in the living room."}],"questions":[{"prompt":"What is Anya's building number?","options":["Fifty.","Thirty.","Five.","Fifteen."],"correctIndex":3,"explanation":"Anya 在第二轮纠正并确认楼栋号为十五。","skill":"细节理解"},{"prompt":"What is the flat number?","options":["302.","203.","503.","320."],"correctIndex":0,"explanation":"对话直接说明公寓号为 302。","skill":"细节理解"},{"prompt":"Which entrance should Ben use?","options":["The first entrance.","The second entrance.","The third entrance.","The fifth entrance."],"correctIndex":1,"explanation":"Anya 要 Ben 使用蓝色公告板旁的第二个入口。","skill":"顺序理解"},{"prompt":"How many people will play together?","options":["Two.","Three.","Four.","Five."],"correctIndex":2,"explanation":"Anya 最后说一共有四个人，并准备了四把椅子。","skill":"细节理解"},{"prompt":"Why does Ben repeat the numbers?","options":["He wants Anya to change her address.","He is counting the chairs.","He has decided not to visit.","He is checking that he has understood the directions."],"correctIndex":3,"explanation":"Ben 在听完地址和路线后逐一复述，体现他在核对关键信息。","skill":"推断"}]},"writing":{"prompt":"为第一次到你家的朋友写一段介绍。可使用虚构地址，说明楼层、入口、房间和一个欢迎细节。","outline":["清楚写出楼栋或门牌数字及楼层。","用 first、second 等序数词说明入口或位置。","介绍一个生活空间和你准备的活动。"],"model":"Welcome to my home. We live in Building Six, in Flat 201 on the second floor. Please use the first entrance beside the small garden. Our flat has two bedrooms and a bright living room. My favourite place is the desk near the window. There are three small plants on it and a shelf of storybooks above it. I will put a welcome card on our door. We can read or play a board game after lunch."},"speakingPrompts":["How would you help a friend find your home?","Which place at home do you like most, and why?","What numbers are useful when you describe a home?"],"textbook":{"status":"edition-checked","referenceEdition":"2024 年 12 月第 1 版第 1 次印刷","grammarScope":"基数词；序数词。","unitStartPage":6,"grammarPages":[11,12],"sections":[{"id":"welcome","label":"Welcome to the unit","labelZh":"导入","pageStart":7,"pageEnd":7,"pageLabel":"7"},{"id":"reading","label":"Reading","labelZh":"阅读","pageStart":8,"pageEnd":10,"pageLabel":"8–10"},{"id":"grammar","label":"Grammar","labelZh":"语法","pageStart":11,"pageEnd":12,"pageLabel":"11–12"},{"id":"pronunciation","label":"Pronunciation","labelZh":"语音","pageStart":13,"pageEnd":13,"pageLabel":"13","topicZh":"单词中的音节"},{"id":"integration","label":"Integration","labelZh":"综合运用","pageStart":14,"pageEnd":16,"pageLabel":"14–16"},{"id":"assessment","label":"Assessment","labelZh":"评价","pageStart":17,"pageEnd":17,"pageLabel":"17"},{"id":"furtherStudy","label":"Further study","labelZh":"拓展学习","pageStart":17,"pageEnd":17,"pageLabel":"17"},{"id":"workbook","label":"Workbook","labelZh":"随书练习","pageStart":106,"pageEnd":108,"pageLabel":"106–108","location":"appendix"}]}},{"id":"7b-u2","bookId":"7b","number":2,"title":"Neighbourhood","theme":"了解社区需要，制订互助计划","goals":["用 will 表达临时决定或承诺","用 be going to 说明已有计划","提出分工清楚、能落实的邻里互助活动"],"grammarKeys":["future_will","be_going_to"],"vocabulary":[{"word":"neighbour","meaning":"邻居","example":"Our neighbour helps us carry the empty boxes.","reviewId":0},{"word":"community","meaning":"社区","example":"The community room is open on Saturdays.","reviewId":1},{"word":"volunteer","meaning":"志愿者；自愿做","example":"Three volunteers will welcome the visitors.","reviewId":2},{"word":"repair","meaning":"修理","example":"An adult volunteer will repair the loose chair.","reviewId":3},{"word":"offer","meaning":"主动提供","example":"I offer to write the labels.","reviewId":4},{"word":"noticeboard","meaning":"公告板","example":"We put our plan on the noticeboard.","reviewId":5},{"word":"appointment","meaning":"约定；预约","example":"Please choose an appointment time.","reviewId":6},{"word":"support","meaning":"支持；帮助","example":"Neighbours support the project in different ways.","reviewId":7}],"reading":{"id":"7b-u2-reading","title":"A Saturday Help Table","level":"基础","text":"Our neighbourhood is going to hold a help morning on Saturday. At first, the student volunteers plan to collect old toys. Then they ask residents what they need. Several people have loose chair legs or torn bags, so the plan changes. Adult volunteers are going to run a small repair table in the community room. Students will welcome visitors, write labels and keep each person's things together. We are not going to repair electrical items. Those need trained workers and suitable equipment. My friend Yusuf is going to make appointment cards, so visitors do not all arrive at once. I will explain the waiting area to anyone who looks unsure. We hope the morning will bring neighbours together, even when an item cannot be repaired.","summary":"学生先倾听居民需求，再协助成人开展维修互助，明确分工、服务边界和预约安排。","questions":[{"prompt":"What do the students plan to collect at first?","options":["Old toys.","New chairs.","School uniforms.","Food packets."],"correctIndex":0,"explanation":"最初计划是收集旧玩具，了解居民需要后才调整。","skill":"细节理解"},{"prompt":"Why does the plan change?","options":["The weather is too hot.","No students want to help.","The room is closed.","Residents describe things they need repaired."],"correctIndex":3,"explanation":"几位居民提到椅腿松动、包破损等需求，所以计划改为维修互助。","skill":"因果理解"},{"prompt":"Who will carry out repairs at the table?","options":["Only young children.","Adult volunteers.","Every visitor alone.","The bus drivers."],"correctIndex":1,"explanation":"原文说明成人志愿者负责维修台，学生承担接待、标签等工作。","skill":"细节理解"},{"prompt":"Why is Yusuf making appointment cards?","options":["To sell them to neighbours.","To replace all the item labels.","To spread out visitors' arrival times.","To count the old toys."],"correctIndex":2,"explanation":"预约卡的目的是避免所有访客同时到达。","skill":"细节理解"},{"prompt":"What is the most important lesson from the changed plan?","options":["Good help begins with listening to people's needs.","Students should repair every electrical item.","A plan should never change.","Collecting toys is always useless."],"correctIndex":0,"explanation":"学生先询问居民，再根据反馈调整服务，说明有效互助应建立在真实需要上。","skill":"推断"}]},"dialogue":{"title":"A New Neighbour's First Visit","turns":[{"speaker":"Iris","text":"Our new neighbour is coming to the community book corner tomorrow. I am going to show her around."},{"speaker":"Luke","text":"That sounds helpful. I will make an extra name card now. What time are you meeting her?"},{"speaker":"Iris","text":"At ten by the front gate. She is bringing her younger brother, who likes picture books."},{"speaker":"Luke","text":"Then I will put a few picture books on the low shelf. Our group is going to organise that shelf this afternoon anyway."},{"speaker":"Iris","text":"Thanks. I am going to ask what kinds of stories they enjoy, so we can make useful suggestions."},{"speaker":"Luke","text":"Good idea. I will join you at the book corner after I finish putting up the opening-hours sign."}],"questions":[{"prompt":"Where will Iris meet the new neighbour?","options":["At the bus station.","Inside the library office.","By the front gate.","At the repair table."],"correctIndex":2,"explanation":"Iris 说明会在十点于前门会面。","skill":"细节理解"},{"prompt":"Who likes picture books?","options":["The neighbour's younger brother.","Luke's teacher.","Iris's grandmother.","The group leader."],"correctIndex":0,"explanation":"新邻居会带弟弟来，弟弟喜欢绘本。","skill":"细节理解"},{"prompt":"What will Luke make immediately?","options":["A new bookshelf.","A bus timetable.","A storybook.","An extra name card."],"correctIndex":3,"explanation":"Luke 听到新邻居要来后，临时决定现在多做一张姓名卡。","skill":"细节理解"},{"prompt":"What was the group already planning to do this afternoon?","options":["Paint the front gate.","Organise the low shelf.","Close the book corner.","Visit another town."],"correctIndex":1,"explanation":"Luke 说小组原本就打算当天下午整理那个低书架。","skill":"计划理解"},{"prompt":"Why will Iris ask about their favourite stories?","options":["She wants to test them before they enter.","She wants them to bring more money.","She wants to suggest books that suit them.","She wants them to leave quickly."],"correctIndex":2,"explanation":"Iris 明确说了解喜好后可以给出有用建议，体现按来访者兴趣提供帮助。","skill":"意图理解"}]},"writing":{"prompt":"为一个社区互助活动写计划，说明要解决的问题、已有安排和你愿意承担的工作。","outline":["说明活动对象与一个具体需要。","用 be going to 写两项已计划的安排。","用 will 表达你愿意承担的具体工作。"],"model":"Our community is going to open a small book corner next Saturday. Some younger children want more places to read with friends. We are going to clean the shelves and sort books by topic on Friday afternoon. Adult volunteers will help us check the furniture. I will make clear labels and welcome new visitors. My partner is going to prepare a suggestion box. We hope everyone can help choose the books and feel part of the project."},"speakingPrompts":["What might people in your neighbourhood need help with?","What are you going to do in a community activity?","What could you offer to do when a plan changes?"],"textbook":{"status":"edition-checked","referenceEdition":"2024 年 12 月第 1 版第 1 次印刷","grammarScope":"will 和 be going to 表达的一般将来时。","unitStartPage":18,"grammarPages":[23,24],"sections":[{"id":"welcome","label":"Welcome to the unit","labelZh":"导入","pageStart":19,"pageEnd":19,"pageLabel":"19"},{"id":"reading","label":"Reading","labelZh":"阅读","pageStart":20,"pageEnd":22,"pageLabel":"20–22"},{"id":"grammar","label":"Grammar","labelZh":"语法","pageStart":23,"pageEnd":24,"pageLabel":"23–24"},{"id":"pronunciation","label":"Pronunciation","labelZh":"语音","pageStart":25,"pageEnd":25,"pageLabel":"25","topicZh":"连读"},{"id":"integration","label":"Integration","labelZh":"综合运用","pageStart":26,"pageEnd":28,"pageLabel":"26–28"},{"id":"assessment","label":"Assessment","labelZh":"评价","pageStart":29,"pageEnd":29,"pageLabel":"29"},{"id":"furtherStudy","label":"Further study","labelZh":"拓展学习","pageStart":29,"pageEnd":29,"pageLabel":"29"},{"id":"workbook","label":"Workbook","labelZh":"随书练习","pageStart":109,"pageEnd":111,"pageLabel":"109–111","location":"appendix"}]}},{"id":"7b-u3","bookId":"7b","number":3,"title":"My hometown","theme":"发现家乡细节，清楚介绍地点与路线","goals":["在介绍地点时恰当使用 a、an 和 the","用地点介词说明相对位置","结合路线与生活细节介绍家乡"],"grammarKeys":["articles","prepositions_place"],"vocabulary":[{"word":"hometown","meaning":"家乡","example":"My hometown has a quiet riverside path.","reviewId":0},{"word":"square","meaning":"广场","example":"People meet in the square after dinner.","reviewId":1},{"word":"bridge","meaning":"桥","example":"An old bridge crosses the narrow river.","reviewId":2},{"word":"museum","meaning":"博物馆","example":"The museum shows pictures of our town.","reviewId":3},{"word":"lane","meaning":"小巷","example":"A small bookshop stands in the lane.","reviewId":4},{"word":"opposite","meaning":"在……对面","example":"The post office is opposite the museum.","reviewId":5},{"word":"corner","meaning":"角落；拐角","example":"Turn left at the next corner.","reviewId":6},{"word":"local","meaning":"当地的","example":"A local artist draws the old street.","reviewId":7}],"reading":{"id":"7b-u3-reading","title":"Two Maps of Our Town","level":"基础","text":"For a school project, Lian makes a map of her hometown, Brookfield. She marks the main square, an old bridge and the town museum. Then she asks her grandfather to add his favourite places. He draws a tiny bench beside the river and a lane behind the museum. Lian is surprised. Neither place looks important on a tourist map. They take a walk together that afternoon. At the bench, Grandpa meets a friend who tells stories about the old river boats. In the lane, a woman is painting a shop sign by hand. Lian takes notes instead of only taking photos. Her final map has two colours: blue for buildings and orange for people's stories. She learns that a hometown is also made of small, ordinary connections.","summary":"Lian 在地标地图之外记录长椅、小巷和人们的故事，重新认识家乡。","questions":[{"prompt":"Which place does Lian mark on her first map?","options":["An airport.","A mountain school.","A sports stadium.","The town museum."],"correctIndex":3,"explanation":"最初她标出了主广场、老桥和镇博物馆。","skill":"细节理解"},{"prompt":"Where is Grandpa's favourite bench?","options":["Beside the river.","Inside the museum.","Behind the school.","Under a shop sign."],"correctIndex":0,"explanation":"祖父在地图上画的是河边的一张小长椅。","skill":"细节理解"},{"prompt":"What is the woman in the lane doing?","options":["Selling boat tickets.","Painting a shop sign by hand.","Repairing the bridge.","Drawing a tourist map."],"correctIndex":1,"explanation":"两人走进小巷时，看见一位女士手绘店铺招牌。","skill":"细节理解"},{"prompt":"What does orange represent on Lian's final map?","options":["Roads.","Buildings.","People's stories.","River water."],"correctIndex":2,"explanation":"结尾说明蓝色代表建筑，橙色代表人们的故事。","skill":"细节理解"},{"prompt":"What changes in Lian's understanding of her hometown?","options":["She thinks only museums are interesting.","She decides to remove every building from the map.","She no longer wants to speak to local people.","She begins to value everyday places and relationships."],"correctIndex":3,"explanation":"普通长椅和小巷承载了人物故事，Lian 因此认识到家乡也由日常联系构成。","skill":"推断"}]},"dialogue":{"title":"A Short Walk around Town","turns":[{"speaker":"Visitor","text":"I have an hour before my bus leaves. Is there a place nearby where I can learn about the town?"},{"speaker":"Ming","text":"Yes. There is a small museum opposite the post office. It is five minutes away on foot."},{"speaker":"Visitor","text":"That sounds good. Is the entrance on the main road?"},{"speaker":"Ming","text":"No. Turn into the lane beside the post office. The museum entrance faces a little garden behind the main building."},{"speaker":"Visitor","text":"Thank you. After the museum, can I walk through the square on my way back to the bus stop?"},{"speaker":"Ming","text":"Yes. The square is between the museum and the bus stop. There is a clear clock above the flower stall, so you can watch the time."}],"questions":[{"prompt":"How much time does the visitor have before the bus leaves?","options":["Ten minutes.","An hour.","Two hours.","A whole day."],"correctIndex":1,"explanation":"访客第一句说明距离发车还有一小时。","skill":"细节理解"},{"prompt":"What is opposite the museum?","options":["The railway station.","The school.","The post office.","The river."],"correctIndex":2,"explanation":"Ming 说小博物馆在邮局对面。","skill":"位置理解"},{"prompt":"Where does the museum entrance face?","options":["A little garden.","The main road.","A large car park.","The bus platform."],"correctIndex":0,"explanation":"入口朝向主楼后面的小花园，而不是主路。","skill":"细节理解"},{"prompt":"Where is the square?","options":["Inside the museum.","Beyond the railway line.","Beside the visitor's home.","Between the museum and the bus stop."],"correctIndex":3,"explanation":"最后一轮给出广场位于博物馆与公交站之间。","skill":"位置理解"},{"prompt":"Why does Ming mention the clock?","options":["He wants the visitor to buy it.","It can help the visitor return for the bus on time.","The museum has no exhibits.","The clock is the town's only attraction."],"correctIndex":1,"explanation":"访客有发车时间限制，Ming 提醒广场有清楚的时钟，方便掌握回程时间。","skill":"推断"}]},"writing":{"prompt":"为朋友写一段家乡步行导览，介绍两个地点、它们的相对位置和一处生活细节。","outline":["用 a 或 an 引入一个地点，再用 the 指代。","用 beside、opposite 或 between 说明位置。","加入与当地人或生活有关的小细节。"],"model":"My hometown is a small place called Brookfield. There is an old bridge near the town square. The bridge is a good place to watch the river. Opposite the square is a small museum with pictures of local life. Behind it, you can find a quiet lane and a bookshop. The owner puts a chair outside for readers on sunny days. I like showing visitors this corner because it feels friendly and full of stories."},"speakingPrompts":["Which two places would you show a visitor in your hometown?","How would you explain the way from one place to another?","What small local detail makes your hometown special to you?"],"textbook":{"status":"edition-checked","referenceEdition":"2024 年 12 月第 1 版第 1 次印刷","grammarScope":"不定冠词、定冠词；地点介词。","unitStartPage":30,"grammarPages":[35,36],"sections":[{"id":"welcome","label":"Welcome to the unit","labelZh":"导入","pageStart":31,"pageEnd":31,"pageLabel":"31"},{"id":"reading","label":"Reading","labelZh":"阅读","pageStart":32,"pageEnd":34,"pageLabel":"32–34"},{"id":"grammar","label":"Grammar","labelZh":"语法","pageStart":35,"pageEnd":36,"pageLabel":"35–36"},{"id":"pronunciation","label":"Pronunciation","labelZh":"语音","pageStart":37,"pageEnd":37,"pageLabel":"37","topicZh":"单词重音"},{"id":"integration","label":"Integration","labelZh":"综合运用","pageStart":38,"pageEnd":40,"pageLabel":"38–40"},{"id":"assessment","label":"Assessment","labelZh":"评价","pageStart":41,"pageEnd":41,"pageLabel":"41"},{"id":"furtherStudy","label":"Further study","labelZh":"拓展学习","pageStart":41,"pageEnd":41,"pageLabel":"41"},{"id":"workbook","label":"Workbook","labelZh":"随书练习","pageStart":112,"pageEnd":114,"pageLabel":"112–114","location":"appendix"}]}},{"id":"7b-u4","bookId":"7b","number":4,"title":"Chinese folk art","theme":"体验民间艺术，尊重创作与传承","goals":["使用名词所有格说明归属","区分形容词性和名词性物主代词","介绍一件手工作品的作者、特点与意义"],"grammarKeys":["possessives"],"vocabulary":[{"word":"craft","meaning":"手工艺；工艺品","example":"We learn a simple paper craft.","reviewId":0},{"word":"pattern","meaning":"图案","example":"The pattern has flowers and small circles.","reviewId":1},{"word":"paper-cutting","meaning":"剪纸","example":"Our club invites an artist to teach paper-cutting.","reviewId":2},{"word":"clay","meaning":"黏土","example":"He shapes a bird from a small piece of clay.","reviewId":3},{"word":"fold","meaning":"折叠","example":"Fold the paper before drawing the line.","reviewId":4},{"word":"display","meaning":"展示；陈列","example":"Each work has a label in the display.","reviewId":5},{"word":"tradition","meaning":"传统","example":"Grandpa shares a craft tradition with our class.","reviewId":6},{"word":"creator","meaning":"创作者","example":"The creator's name is beside the picture.","reviewId":7}],"reading":{"id":"7b-u4-reading","title":"Two Windows on One Sheet","level":"基础","text":"Qing's grandfather enjoys paper-cutting. For the school craft display, he shows her a round flower pattern. Qing practises on scrap paper, then makes her own design. Her paper window has a bicycle beside a tree, because she rides past that tree every morning. Grandpa's work is perfectly even; hers is a little uneven near the wheel. Qing wants to hide that part, but Grandpa asks her to explain the design instead. At the display, she puts both works side by side. One label gives her grandfather's name, and the other gives hers. Visitors notice the different subjects and ask about them. Qing explains what she learned and what she changed. She feels proud because her work carries an old skill and a story from her own life.","summary":"Qing 学习祖父的剪纸技法，并加入自己的日常故事，展示传承与个人创作之间的联系。","questions":[{"prompt":"What pattern does Grandpa show Qing?","options":["A round flower pattern.","A map of the town.","A picture of a train.","A large fish pattern."],"correctIndex":0,"explanation":"祖父先教 Qing 一个圆形花卉图案。","skill":"细节理解"},{"prompt":"Why does Qing include a bicycle and a tree?","options":["They are in every paper-cutting design.","Her teacher requires those shapes.","She wants to copy Grandpa exactly.","They are part of her daily journey."],"correctIndex":3,"explanation":"她每天骑车经过那棵树，所以把日常经历放入设计。","skill":"因果理解"},{"prompt":"In 'hers is a little uneven', whose work is 'hers'?","options":["The teacher's work.","Qing's work.","A visitor's work.","Grandpa's work."],"correctIndex":1,"explanation":"句子先比较祖父的作品，再用 hers 指 Qing 自己的作品。","skill":"指代理解"},{"prompt":"What do the two labels show?","options":["Only the prices.","The visitors' names.","Each creator's name.","The number of visitors."],"correctIndex":2,"explanation":"两张标签分别写祖父与 Qing 的名字，清楚标明创作者。","skill":"细节理解"},{"prompt":"Why does Qing feel proud at the end?","options":["She combines a learned skill with her own experience.","Nobody notices her work.","Her work is more expensive than Grandpa's.","She no longer needs to practise."],"correctIndex":0,"explanation":"结尾说明作品既承载旧技艺，也承载她自己的生活故事，体现传承中的个人表达。","skill":"推断"}]},"dialogue":{"title":"Labels for the Craft Display","turns":[{"speaker":"Wen","text":"Whose clay bird is this, Lucy? I need to finish the labels before the visitors arrive."},{"speaker":"Lucy","text":"It is mine. The blue bowl beside it is my brother's. His name is Peter."},{"speaker":"Wen","text":"Thanks. Are these paper fish yours too? They have the same small flower pattern."},{"speaker":"Lucy","text":"No, they are the art club's. The members made them together, so their label should name the whole group."},{"speaker":"Wen","text":"I understand. I will write your name for the bird, Peter's for the bowl and the club's name for the fish."},{"speaker":"Lucy","text":"Please add one more note: our grandmother taught us how to shape the clay. We want to thank her for sharing her skill."}],"questions":[{"prompt":"Whose clay bird is it?","options":["Peter’s.","The whole art club’s.","Lucy’s.","Wen’s."],"correctIndex":2,"explanation":"Lucy 说 It is mine，mine 表示黏土鸟属于她。","skill":"归属理解"},{"prompt":"Which item belongs to Peter?","options":["The blue bowl.","The clay bird.","All the paper fish.","The label board."],"correctIndex":0,"explanation":"Lucy 指出蓝碗是她哥哥或弟弟 Peter 的作品。","skill":"细节理解"},{"prompt":"Why should the fish label name the whole art club?","options":["Nobody knows who brought them.","The visitors made them.","They are for sale together.","The members made them together."],"correctIndex":3,"explanation":"纸鱼是社团成员共同完成的，因此应标注集体创作。","skill":"因果理解"},{"prompt":"Who taught Lucy and Peter to shape clay?","options":["Wen's teacher.","Their grandmother.","The visitors.","A shop owner."],"correctIndex":1,"explanation":"Lucy 最后补充，祖母教他们黏土塑形技法。","skill":"细节理解"},{"prompt":"What do Lucy's requests suggest?","options":["She wants all the work labelled as hers.","She is worried about the display's price.","She thinks creators and teachers should receive credit.","She does not want any visitors to come."],"correctIndex":2,"explanation":"Lucy 区分个人、社团作品，并要求感谢祖母，说明她重视创作与传授者的贡献。","skill":"推断"}]},"writing":{"prompt":"介绍一件你制作、见过或学习过的民间工艺作品，清楚说明作者与学习来源。","outline":["说明作品是什么、是谁的。","描写材料、图案或制作中的一个细节。","说明从谁那里学习，以及这件作品对你意味着什么。"],"model":"This paper picture is mine. It shows a small fish beside two water plants. My aunt taught me how to fold the paper and plan the shapes. Her work is very neat, while mine has a few uneven edges. I keep both pictures in my folder because they show my progress. For our class display, I will write my name and thank my aunt on the label. This small craft connects her skill with my own ideas."},"speakingPrompts":["What Chinese folk art would you like to try?","How would you describe a handmade object and its creator?","How can you thank someone who teaches you a traditional skill?"],"textbook":{"status":"edition-checked","referenceEdition":"2024 年 12 月第 1 版第 1 次印刷","grammarScope":"名词所有格；形容词性与名词性物主代词。","unitStartPage":42,"grammarPages":[47,48],"sections":[{"id":"welcome","label":"Welcome to the unit","labelZh":"导入","pageStart":43,"pageEnd":43,"pageLabel":"43"},{"id":"reading","label":"Reading","labelZh":"阅读","pageStart":44,"pageEnd":46,"pageLabel":"44–46"},{"id":"grammar","label":"Grammar","labelZh":"语法","pageStart":47,"pageEnd":48,"pageLabel":"47–48"},{"id":"pronunciation","label":"Pronunciation","labelZh":"语音","pageStart":49,"pageEnd":49,"pageLabel":"49","topicZh":"句子重音"},{"id":"integration","label":"Integration","labelZh":"综合运用","pageStart":50,"pageEnd":52,"pageLabel":"50–52"},{"id":"assessment","label":"Assessment","labelZh":"评价","pageStart":53,"pageEnd":53,"pageLabel":"53"},{"id":"furtherStudy","label":"Further study","labelZh":"拓展学习","pageStart":53,"pageEnd":53,"pageLabel":"53"},{"id":"workbook","label":"Workbook","labelZh":"随书练习","pageStart":115,"pageEnd":117,"pageLabel":"115–117","location":"appendix"}]}},{"id":"7b-u5","bookId":"7b","number":5,"title":"Animal friends","theme":"描述动物特点，学会尊重与照顾","goals":["用形容词描述动物的外表和状态","用 can、could 说明现在与过去的能力","用恰当的情态动词请求许可"],"grammarKeys":["adjectives_basic","modals_ability","modals_permission"],"vocabulary":[{"word":"gentle","meaning":"温和的","example":"The old dog is gentle with visitors.","reviewId":0},{"word":"curious","meaning":"好奇的","example":"The curious cat watches the moving toy.","reviewId":1},{"word":"feather","meaning":"羽毛","example":"A grey feather lies beside the gate.","reviewId":2},{"word":"paw","meaning":"爪子；脚掌","example":"The cat puts one paw on the box.","reviewId":3},{"word":"owner","meaning":"主人","example":"Ask the owner before touching the dog.","reviewId":4},{"word":"permission","meaning":"许可","example":"We need permission to enter the animal room.","reviewId":5},{"word":"patient","meaning":"有耐心的","example":"A patient visitor gives the shy dog space.","reviewId":6},{"word":"observe","meaning":"观察","example":"We observe the animals without disturbing them.","reviewId":7}],"reading":{"id":"7b-u5-reading","title":"Letting Pip Choose","level":"基础","text":"When Hana first visits her aunt, she wants to play with Pip, a small brown dog. Pip stays under a chair. Hana's aunt explains that he is gentle but shy around new people. 'May I bring him a toy?' Hana asks. Her aunt agrees and gives her a soft ball. Hana places it nearby and sits quietly with a book. After a while, Pip comes out and touches the ball with one paw. Hana smiles but does not reach for him. On her next visit, Pip brings the ball to her. Her aunt says that last year he could not stay calmly beside visitors. Now he can. Hana learns that making an animal friend is not only about what she wants. It also means noticing what the animal is ready for.","summary":"Hana 尊重小狗 Pip 的节奏，用耐心建立信任，并从观察中理解动物的状态。","questions":[{"prompt":"Where does Pip stay when Hana first arrives?","options":["On the table.","Under a chair.","Behind the garden gate.","In Hana's bag."],"correctIndex":1,"explanation":"开头写到 Pip 躲在椅子下面。","skill":"细节理解"},{"prompt":"What does Hana ask permission to bring?","options":["A bowl of food.","A new collar.","A soft toy ball.","A camera."],"correctIndex":2,"explanation":"Hana 询问能否带玩具给 Pip，姨妈给她的是一个软球。","skill":"细节理解"},{"prompt":"What does Hana do after putting the ball nearby?","options":["She sits quietly with a book.","She pulls Pip out.","She calls loudly.","She leaves the house immediately."],"correctIndex":0,"explanation":"Hana 把球放在附近，然后安静地坐着读书，没有强迫 Pip 接近。","skill":"细节理解"},{"prompt":"What can Pip do now that he could not do calmly last year?","options":["Drive a car.","Read Hana's book.","Open every door.","Stay beside visitors."],"correctIndex":3,"explanation":"姨妈说明去年 Pip 还不能平静待在访客身边，现在可以了。","skill":"信息整合"},{"prompt":"What helps Hana become Pip's friend?","options":["Giving him every kind of food.","Respecting his pace and observing his behaviour.","Making him play at once.","Showing that she is louder than he is."],"correctIndex":1,"explanation":"Hana 安静等待、不急着触摸，最后懂得关注动物是否准备好，这些细节支持尊重和观察的重要性。","skill":"推断"}]},"dialogue":{"title":"At the Animal Learning Centre","turns":[{"speaker":"Student","text":"That rabbit looks very soft. May I open the gate and go closer?"},{"speaker":"Keeper","text":"Please stay outside the gate for now. You can watch from this bench while I finish cleaning the space."},{"speaker":"Student","text":"Of course. Could I take a photo from here without using a flash?"},{"speaker":"Keeper","text":"Yes, you may. Keep your voice low. This rabbit could not relax near visitors last month, but it is much calmer now."},{"speaker":"Student","text":"I can see it moving its ears. Is the rabbit curious about the sounds around it?"},{"speaker":"Keeper","text":"It seems interested. You are noticing small details, which is useful. After the cleaning, I can tell you more about its daily activities."}],"questions":[{"prompt":"What does the student first ask to do?","options":["Clean the whole centre.","Buy the rabbit.","Open the gate and go closer.","Feed every animal."],"correctIndex":2,"explanation":"学生看到兔子后先请求打开门靠近观察。","skill":"细节理解"},{"prompt":"Where may the student wait?","options":["On a bench outside the gate.","Inside the rabbit's space.","Behind a locked door.","In the keeper's car."],"correctIndex":0,"explanation":"管理员让学生先留在门外，从长椅处观察。","skill":"许可理解"},{"prompt":"What photo condition does the student mention?","options":["Using a loud toy.","Standing inside the gate.","Taking photos only at night.","Not using a flash."],"correctIndex":3,"explanation":"学生请求在当前位置不使用闪光灯拍照，管理员同意。","skill":"细节理解"},{"prompt":"How is the rabbit different from last month?","options":["It is louder.","It is calmer near visitors.","It can talk.","It has stopped moving its ears."],"correctIndex":1,"explanation":"管理员说它上个月在访客附近还不能放松，现在平静多了。","skill":"比较理解"},{"prompt":"What does the keeper appreciate about the student?","options":["The student ignores the rules.","The student wants to take the rabbit home.","The student observes small details respectfully.","The student finishes all the cleaning."],"correctIndex":2,"explanation":"管理员肯定学生注意耳朵动作等细节；学生也一直先请求许可并遵守安排。","skill":"推断"}]},"writing":{"prompt":"介绍一位动物朋友，描述外表、性格、会做的事，以及你如何与它相处。","outline":["用形容词说明外表和性格。","用 can 或 could 描写一项能力或变化。","说明你如何观察它、尊重主人的安排或请求许可。"],"model":"My neighbour has a small grey dog called Moss. He has soft ears and a curious face. He can find his favourite toy under a blanket. When I first met him, he could not stay near me for long. Now he sometimes rests beside my chair. I always ask his owner before playing with him. I enjoy watching his small actions and learning what they mean. Being his friend teaches me to be patient and gentle."},"speakingPrompts":["How would you describe an animal you know?","What can this animal do, and what could it do before?","What would you ask before touching or feeding someone else's animal?"],"textbook":{"status":"edition-checked","referenceEdition":"2024 年 12 月第 1 版第 1 次印刷","grammarScope":"形容词作定语、表语；can/could 表示现在或过去的能力，can/could/may 请求或给予许可。","unitStartPage":56,"grammarPages":[61,62],"sections":[{"id":"welcome","label":"Welcome to the unit","labelZh":"导入","pageStart":57,"pageEnd":57,"pageLabel":"57"},{"id":"reading","label":"Reading","labelZh":"阅读","pageStart":58,"pageEnd":60,"pageLabel":"58–60"},{"id":"grammar","label":"Grammar","labelZh":"语法","pageStart":61,"pageEnd":62,"pageLabel":"61–62"},{"id":"pronunciation","label":"Pronunciation","labelZh":"语音","pageStart":63,"pageEnd":63,"pageLabel":"63","topicZh":"诗歌与押韵"},{"id":"integration","label":"Integration","labelZh":"综合运用","pageStart":64,"pageEnd":66,"pageLabel":"64–66"},{"id":"assessment","label":"Assessment","labelZh":"评价","pageStart":67,"pageEnd":67,"pageLabel":"67"},{"id":"furtherStudy","label":"Further study","labelZh":"拓展学习","pageStart":67,"pageEnd":67,"pageLabel":"67"},{"id":"workbook","label":"Workbook","labelZh":"随书练习","pageStart":118,"pageEnd":120,"pageLabel":"118–120","location":"appendix"}]}},{"id":"7b-u6","bookId":"7b","number":6,"title":"Beautiful landscapes","theme":"观察自然景观，发现小尺度的美","goals":["恰当使用指人或指物的不定代词","用 what 和 how 表达赞叹","从整体景色和细节两方面描述一处景观"],"grammarKeys":["indefinite_pronouns","exclamations"],"vocabulary":[{"word":"landscape","meaning":"风景；地貌","example":"The painting shows a peaceful landscape.","reviewId":0},{"word":"valley","meaning":"山谷","example":"A narrow stream runs through the valley.","reviewId":1},{"word":"stream","meaning":"小溪","example":"We watch the stream from the path.","reviewId":2},{"word":"shore","meaning":"岸；滨","example":"Small stones lie along the lake shore.","reviewId":3},{"word":"reflection","meaning":"倒影","example":"The tree's reflection moves on the water.","reviewId":4},{"word":"mist","meaning":"薄雾","example":"Mist covers the distant hills.","reviewId":5},{"word":"peaceful","meaning":"宁静的","example":"The quiet valley looks peaceful.","reviewId":6},{"word":"detail","meaning":"细节","example":"A careful observer notices a small detail.","reviewId":7}],"reading":{"id":"7b-u6-reading","title":"When the Wide View Disappeared","level":"基础","text":"Our class arrives at Pine Valley hoping to see the distant hills. Mist covers everything beyond the visitor centre. Someone says there is nothing worth drawing. Our teacher gives us a different task: find something beautiful within ten steps of the path. I notice a shallow puddle beside a stone. A tiny branch lies across it, and the grey sky appears in the water. 'What a quiet little world!' I say. My partner finds drops of water on a spider's web. Nobody needs to leave the marked path to look closely. We sit on a dry bench and sketch these details. Before we leave, the mist begins to lift. The hills are lovely, but my favourite drawing is still the puddle. A landscape can surprise us at more than one scale.","summary":"远山被雾遮住后，学生转而观察水洼与蛛网上的水滴，发现景观的美也存在于细节。","questions":[{"prompt":"Why can the class not see the distant hills at first?","options":["It is completely dark.","A wall blocks the path.","The class is indoors all day.","Mist covers the view."],"correctIndex":3,"explanation":"开头说明薄雾遮住了游客中心以外的远景。","skill":"细节理解"},{"prompt":"What task does the teacher give?","options":["Find something beautiful near the path.","Run to the highest hill.","Collect every stone.","Wait without doing anything."],"correctIndex":0,"explanation":"老师要求在步道附近十步范围内寻找美的事物。","skill":"细节理解"},{"prompt":"What does the narrator draw?","options":["A bus.","A shallow puddle.","The visitor centre's roof.","A large animal."],"correctIndex":1,"explanation":"叙述者观察石头旁浅水洼及倒影，最喜欢的画也是水洼。","skill":"细节理解"},{"prompt":"What does the partner discover?","options":["A lost camera.","A painted sign.","Water drops on a spider's web.","A hidden boat."],"correctIndex":2,"explanation":"伙伴在蜘蛛网上发现了水滴。","skill":"细节理解"},{"prompt":"What does the narrator learn?","options":["Only distant hills count as landscapes.","Mist always ruins a visit.","Drawing is useful only on sunny days.","Small details can be as interesting as a wide view."],"correctIndex":3,"explanation":"即使散雾后的远山很美，叙述者仍偏爱水洼画，说明局部细节同样值得欣赏。","skill":"推断"}]},"dialogue":{"title":"Choosing a Landscape Sketch","turns":[{"speaker":"Aria","text":"What a beautiful lake! Is everyone going to draw the mountains on the other side?"},{"speaker":"Noel","text":"Some people are. I want to draw something nearer: the reflections beside those reeds."},{"speaker":"Aria","text":"I cannot see anything clearly in the water. A little wind is moving the surface."},{"speaker":"Noel","text":"Look at the changing shapes instead of waiting for a perfect picture. How quickly the colours move!"},{"speaker":"Aria","text":"Now I see them. There is a patch of gold from the reeds and some blue from the sky."},{"speaker":"Noel","text":"Exactly. Nobody needs the same subject. We can sit on this bench and compare our sketches when we finish."}],"questions":[{"prompt":"What does Noel want to draw?","options":["A boat inside a building.","Reflections beside the reeds.","A mountain road.","The students' bags."],"correctIndex":1,"explanation":"Noel 选择的是近处芦苇旁的倒影，而不是远山。","skill":"细节理解"},{"prompt":"Why are the reflections changing?","options":["Someone is painting the water.","The lake is empty.","Wind is moving the surface.","The students are moving the reeds."],"correctIndex":2,"explanation":"Aria 说明微风在吹动水面，所以看不清稳定的倒影。","skill":"因果理解"},{"prompt":"What colour comes from the reeds?","options":["Gold.","Purple.","Black.","Pink."],"correctIndex":0,"explanation":"Aria 后来看到芦苇映出金色，天空映出蓝色。","skill":"细节理解"},{"prompt":"Where will Aria and Noel sit?","options":["On the mountain top.","In a boat.","Inside the lake.","On a bench."],"correctIndex":3,"explanation":"Noel 提议坐在眼前的长椅上画完后比较作品。","skill":"细节理解"},{"prompt":"What is Noel encouraging Aria to do?","options":["Wait until every reflection is still.","Find beauty in changing shapes.","Copy everyone's drawing.","Choose only the most distant object."],"correctIndex":1,"explanation":"Noel 让 Aria 观察变化中的形状，不必等待完美静止的画面，强调动态的美。","skill":"推断"}]},"writing":{"prompt":"描述一处你见过或想象的景观，既写整体印象，也写一个小细节，并使用感叹句。","outline":["交代观察地点与整体景色。","用 something、everyone 或 nobody 等不定代词补充现场观察。","使用 What…! 或 How…! 表达真实感受。"],"model":"Yesterday, I imagined a quiet valley for an art task. A small stream runs between the hills, and there is a wooden bench beside the path. What a peaceful place it is! At first, everyone might notice the high trees. I want to draw something smaller: a yellow leaf floating past a stone. How gently it moves! This detail makes the whole landscape feel alive. I would like visitors to slow down and look carefully."},"speakingPrompts":["What landscape would you like to describe or draw?","What small natural detail have you noticed recently?","How can you use what or how to express your feelings about a view?"],"textbook":{"status":"edition-checked","referenceEdition":"2024 年 12 月第 1 版第 1 次印刷","grammarScope":"不定代词；what/how 感叹句。","unitStartPage":68,"grammarPages":[73,74],"sections":[{"id":"welcome","label":"Welcome to the unit","labelZh":"导入","pageStart":69,"pageEnd":69,"pageLabel":"69"},{"id":"reading","label":"Reading","labelZh":"阅读","pageStart":70,"pageEnd":72,"pageLabel":"70–72"},{"id":"grammar","label":"Grammar","labelZh":"语法","pageStart":73,"pageEnd":74,"pageLabel":"73–74"},{"id":"pronunciation","label":"Pronunciation","labelZh":"语音","pageStart":75,"pageEnd":75,"pageLabel":"75","topicZh":"语调"},{"id":"integration","label":"Integration","labelZh":"综合运用","pageStart":76,"pageEnd":78,"pageLabel":"76–78"},{"id":"assessment","label":"Assessment","labelZh":"评价","pageStart":79,"pageEnd":79,"pageLabel":"79"},{"id":"furtherStudy","label":"Further study","labelZh":"拓展学习","pageStart":79,"pageEnd":79,"pageLabel":"79"},{"id":"workbook","label":"Workbook","labelZh":"随书练习","pageStart":121,"pageEnd":123,"pageLabel":"121–123","location":"appendix"}]}},{"id":"7b-u7","bookId":"7b","number":7,"title":"Outdoor fun","theme":"记录户外经历，体会合作与观察的乐趣","goals":["用一般过去时叙述已发生的活动","识别并正确使用常见规则与不规则过去式","按时间顺序说明经历和收获"],"grammarKeys":["simple_past"],"vocabulary":[{"word":"trail","meaning":"小径；步道","example":"We followed the marked trail through the park.","reviewId":0},{"word":"clue","meaning":"线索","example":"The first clue was beside the entrance.","reviewId":1},{"word":"route","meaning":"路线","example":"Our teacher checked the route before the walk.","reviewId":2},{"word":"set off","meaning":"出发","example":"We set off after checking the map.","reviewId":3},{"word":"discover","meaning":"发现","example":"We discovered a small sign near the bridge.","reviewId":4},{"word":"record","meaning":"记录","example":"I recorded the answer in my notebook.","reviewId":5},{"word":"teamwork","meaning":"团队合作","example":"The activity taught us the value of teamwork.","reviewId":6},{"word":"return","meaning":"返回","example":"We returned to the meeting point at eleven.","reviewId":7}],"reading":{"id":"7b-u7-reading","title":"Three Clues on the Trail","level":"基础","text":"Last Wednesday, our teacher took us to a park for a team challenge. Each group received a map and three questions about places along the marked trail. I wanted to finish first, so I walked ahead quickly. At the first stop, I could not answer the question about a date on the gate. I had hurried past it. My teammate Bo suggested going back together. We found the date, wrote it down and agreed to look more carefully. Later, Bo noticed a bird shape on a sign that everyone else missed. I drew it in our notebook. We returned after two other teams, but all our answers were clear. The teacher asked what helped us most. I said, 'Slowing down enough to let everyone notice something.'","summary":"一次步道线索挑战中，叙述者从抢先赶路转向细心观察与团队合作。","questions":[{"prompt":"What did each group receive?","options":["A bike and a helmet.","A meal and a ticket.","A map and three questions.","A camera and five prizes."],"correctIndex":2,"explanation":"开头说明每组得到一张地图和三个有关步道地点的问题。","skill":"细节理解"},{"prompt":"Why did the narrator miss the date on the gate?","options":["The narrator hurried past it.","The date was covered by snow.","The gate was locked inside a room.","Bo removed the sign."],"correctIndex":0,"explanation":"叙述者想抢先完成，匆忙走过大门，没有注意日期。","skill":"因果理解"},{"prompt":"What did Bo notice later?","options":["A lost phone.","A new bus stop.","A broken umbrella.","A bird shape on a sign."],"correctIndex":3,"explanation":"Bo 后来注意到标牌上其他人遗漏的鸟形图案。","skill":"细节理解"},{"prompt":"How many teams returned before the narrator's team?","options":["One.","Two.","Three.","None."],"correctIndex":1,"explanation":"他们在另外两支队伍之后返回，因此有两组先到。","skill":"细节理解"},{"prompt":"What did the narrator learn about teamwork?","options":["The fastest person should make every decision.","Only one person needs to look at the clues.","Giving everyone time to observe can improve the result.","Returning first matters more than clear answers."],"correctIndex":2,"explanation":"结尾强调放慢速度让每个人观察；Bo 的发现和共同记录也证明了合作的价值。","skill":"推断"}]},"dialogue":{"title":"After the Outdoor Sketch Walk","turns":[{"speaker":"Tara","text":"How was your sketch walk on Sunday, Finn? Did you go to the river with your class?"},{"speaker":"Finn","text":"Yes. We walked there with our teacher at nine. I took a notebook and three pencils."},{"speaker":"Tara","text":"What did you draw? The old bridge or the boats?"},{"speaker":"Finn","text":"I drew the bridge first. Then rain started, so we moved into the visitor centre and looked at our sketches together."},{"speaker":"Tara","text":"Did the rain spoil the activity?"},{"speaker":"Finn","text":"Not really. I saw how my friends drew the same bridge differently. We gave each other ideas, and I added a new detail when I got home."}],"questions":[{"prompt":"When did Finn's class start walking to the river?","options":["At nine on Sunday.","At ten on Saturday.","At noon on Friday.","At eight on Monday."],"correctIndex":0,"explanation":"Finn 说周日九点与老师一起步行前往河边。","skill":"细节理解"},{"prompt":"What did Finn take?","options":["A tent and a sleeping bag.","Only a camera.","A notebook and three pencils.","A map and six brushes."],"correctIndex":2,"explanation":"第二轮明确给出携带物为笔记本和三支铅笔。","skill":"细节理解"},{"prompt":"What did Finn draw first?","options":["The boats.","The visitor centre.","His teacher.","The old bridge."],"correctIndex":3,"explanation":"Finn 回答自己先画了桥。","skill":"细节理解"},{"prompt":"Why did the class enter the visitor centre?","options":["They needed to buy tickets.","Rain started.","They lost all their pencils.","The teacher cancelled the walk before it began."],"correctIndex":1,"explanation":"下雨后，师生移到游客中心一起看画。","skill":"因果理解"},{"prompt":"Why did Finn still enjoy the activity?","options":["He had a chance to learn from different sketches.","Nobody else drew anything.","He stayed dry at home all morning.","The rain removed every mistake."],"correctIndex":0,"explanation":"室内交流让 Finn 看到同一座桥的不同画法，得到新想法，回家后还补充了细节。","skill":"推断"}]},"writing":{"prompt":"记叙一次户外活动，按出发、过程、结束的顺序说明发生了什么，并写出一项收获。","outline":["用过去时间表达交代活动。","使用至少四个过去式描述具体行动。","说明一个变化、问题或有趣发现，以及你的感受。"],"model":"Last Saturday, my class visited a small park with our teacher. We followed a marked trail and looked for three interesting shapes in nature. I found a leaf like a tiny hand and drew it in my notebook. My partner noticed a round shadow under a bench. We shared our drawings at the end of the walk. I did not bring home any leaves, but I brought home several new ideas. The activity helped me look more carefully."},"speakingPrompts":["What did you do during a recent outdoor activity?","What unexpected thing happened, and how did you respond?","What did you learn from doing an activity with others?"],"textbook":{"status":"edition-checked","referenceEdition":"2024 年 12 月第 1 版第 1 次印刷","grammarScope":"一般过去时Ⅰ：过去事件、过去时间表达、规则和不规则动词过去式。","unitStartPage":80,"grammarPages":[85,86],"sections":[{"id":"welcome","label":"Welcome to the unit","labelZh":"导入","pageStart":81,"pageEnd":81,"pageLabel":"81"},{"id":"reading","label":"Reading","labelZh":"阅读","pageStart":82,"pageEnd":84,"pageLabel":"82–84"},{"id":"grammar","label":"Grammar","labelZh":"语法","pageStart":85,"pageEnd":86,"pageLabel":"85–86"},{"id":"pronunciation","label":"Pronunciation","labelZh":"语音","pageStart":87,"pageEnd":87,"pageLabel":"87","topicZh":"-ed 词尾发音"},{"id":"integration","label":"Integration","labelZh":"综合运用","pageStart":88,"pageEnd":90,"pageLabel":"88–90"},{"id":"assessment","label":"Assessment","labelZh":"评价","pageStart":91,"pageEnd":91,"pageLabel":"91"},{"id":"furtherStudy","label":"Further study","labelZh":"拓展学习","pageStart":91,"pageEnd":91,"pageLabel":"91"},{"id":"workbook","label":"Workbook","labelZh":"随书练习","pageStart":124,"pageEnd":126,"pageLabel":"124–126","location":"appendix"}]}},{"id":"7b-u8","bookId":"7b","number":8,"title":"Wonderland stories","theme":"走进原创幻想世界，按线索讲述故事","goals":["用一般过去时的肯定、否定和疑问句叙述故事","根据细节推断人物动机和故事寓意","创作有起因、变化和结尾的短篇幻想故事"],"grammarKeys":["simple_past"],"vocabulary":[{"word":"mysterious","meaning":"神秘的","example":"A mysterious box appeared on the empty desk.","reviewId":0},{"word":"whisper","meaning":"低声说；低语","example":"The little clock began to whisper.","reviewId":1},{"word":"key","meaning":"钥匙；关键","example":"The silver key opened a very small door.","reviewId":2},{"word":"vanish","meaning":"突然消失","example":"The bright path vanished at sunrise.","reviewId":3},{"word":"wonder","meaning":"想知道；惊奇","example":"I wondered who had left the message.","reviewId":4},{"word":"courage","meaning":"勇气","example":"She found the courage to ask the strange visitor a question.","reviewId":5},{"word":"promise","meaning":"承诺","example":"He made a promise to return the borrowed star.","reviewId":6},{"word":"imagine","meaning":"想象","example":"Imagine a garden where clocks grow on trees.","reviewId":7}],"reading":{"id":"7b-u8-reading","title":"The Clock with a Green Leaf","level":"基础","text":"In a quiet second-hand shop, Mina found a clock with a green leaf instead of a minute hand. The owner said it did not measure ordinary time. 'It counts moments when someone truly listens,' she explained. Mina did not believe her, but she took the clock home. That evening, her little brother wanted to describe a strange dream. Mina almost walked away. Then she sat beside him and asked what happened next. The leaf moved once. The next day, Mina listened to an old neighbour's story about a lost kite. A second leaf appeared. By Friday, the clock looked like a tiny tree. It never told Mina whether she was early or late. It showed her something else: how many stories she had made room for.","summary":"一只长叶子的神奇时钟记录的不是普通时间，而是 Mina 真正倾听他人的时刻。","questions":[{"prompt":"What did the clock have instead of a minute hand?","options":["A silver key.","A paper kite.","A small feather.","A green leaf."],"correctIndex":3,"explanation":"开头写到这只钟用绿叶代替分针。","skill":"细节理解"},{"prompt":"What did the owner say the clock counted?","options":["Moments of true listening.","The number of shop visitors.","Every minute of sleep.","The price of old objects."],"correctIndex":0,"explanation":"店主解释它记录的是有人认真倾听的时刻。","skill":"细节理解"},{"prompt":"When did the first leaf move?","options":["When Mina bought the clock.","When Mina listened to her brother's dream.","When Mina ran to school.","When Mina repaired the minute hand."],"correctIndex":1,"explanation":"Mina 坐下听弟弟讲梦，并追问后来发生什么，叶子随之移动。","skill":"细节理解"},{"prompt":"What was the neighbour's story about?","options":["A tiny tree.","A closed shop.","A lost kite.","A green bicycle."],"correctIndex":2,"explanation":"第二天，Mina 听邻居讲一个丢失风筝的故事。","skill":"细节理解"},{"prompt":"What does the magical clock suggest about time?","options":["Being late is always helpful.","Only clocks can remember stories.","Listening is useful only to children.","Time spent attending to other people has value."],"correctIndex":3,"explanation":"时钟不提示迟早，却长出代表倾听的叶子，寓意是留时间认真关注别人也很珍贵。","skill":"推断"}]},"dialogue":{"title":"Questions about a Vanishing Bridge","turns":[{"speaker":"Milo","text":"Did the silver bridge appear in your story before or after the rain stopped, Sana?"},{"speaker":"Sana","text":"After it stopped. My character, Nell, saw it between two clouds. She did not cross it at once."},{"speaker":"Milo","text":"Why not? Was she afraid of the height?"},{"speaker":"Sana","text":"She was nervous, but that was not the main reason. A tiny guard asked her to leave her loudest worry in a box first."},{"speaker":"Milo","text":"Did she do that? What happened to the bridge?"},{"speaker":"Sana","text":"She wrote her worry on a card and put it inside. The bridge became a path through her own garden. It helped her see a familiar place differently."}],"questions":[{"prompt":"When did the silver bridge appear?","options":["During a snowstorm.","After the rain stopped.","Before Nell woke up.","At the end of the school year."],"correctIndex":1,"explanation":"Sana 明确回答，银桥在雨停后出现。","skill":"细节理解"},{"prompt":"Where did Nell first see the bridge?","options":["Under the kitchen table.","Across a busy road.","Between two clouds.","Inside a bookshop."],"correctIndex":2,"explanation":"第二轮说明 Nell 最初在两朵云之间看见桥。","skill":"细节理解"},{"prompt":"What did the guard ask Nell to leave in the box?","options":["Her loudest worry.","Her favourite shoes.","A silver coin.","A garden key."],"correctIndex":0,"explanation":"守卫要她先把最困扰自己的担忧放进盒子。","skill":"细节理解"},{"prompt":"What did the bridge become?","options":["A large ship.","A locked door.","A classroom window.","A path through Nell's garden."],"correctIndex":3,"explanation":"Nell 写下担忧后，桥变成穿过自己花园的一条小径。","skill":"细节理解"},{"prompt":"What might the change of the bridge mean?","options":["Nell must leave home forever.","Changing her view can make a familiar place feel different.","The guard wants to sell the garden.","Every worry disappears permanently after one sentence."],"correctIndex":1,"explanation":"结尾直接说小径帮助 Nell 重新看待熟悉的地方，因此变化象征视角的调整，并未声称担忧永远消失。","skill":"推断"}]},"writing":{"prompt":"写一个原创幻想故事：一个普通物品出现了奇妙变化，人物作出一个选择，故事有清楚的结尾。","outline":["用过去时交代人物、地点和奇妙物品。","写出人物没有立刻做什么，以及随后作出的选择。","安排一个简短结局，让变化与人物的选择相关。"],"model":"One evening, I found a tiny door inside an empty picture frame. I knocked, but nobody answered. Then a paper bird flew out and dropped a blank map. I did not know where to go, so I drew my grandmother's house on it. A bright path appeared across the page. When I followed it with my finger, I heard her laugh. I put the map beside my phone and called her. The little door quietly closed."},"speakingPrompts":["What ordinary object could become magical in your story?","What did your character do, and what did they decide not to do?","What might your fantasy story help readers think about?"],"textbook":{"status":"edition-checked","referenceEdition":"2024 年 12 月第 1 版第 1 次印刷","grammarScope":"一般过去时Ⅱ：实义动词和 be 的肯定、否定、一般疑问句与简答。","unitStartPage":92,"grammarPages":[97,98],"sections":[{"id":"welcome","label":"Welcome to the unit","labelZh":"导入","pageStart":93,"pageEnd":93,"pageLabel":"93"},{"id":"reading","label":"Reading","labelZh":"阅读","pageStart":94,"pageEnd":96,"pageLabel":"94–96"},{"id":"grammar","label":"Grammar","labelZh":"语法","pageStart":97,"pageEnd":98,"pageLabel":"97–98"},{"id":"pronunciation","label":"Pronunciation","labelZh":"语音","pageStart":99,"pageEnd":99,"pageLabel":"99","topicZh":"意群"},{"id":"integration","label":"Integration","labelZh":"综合运用","pageStart":100,"pageEnd":102,"pageLabel":"100–102"},{"id":"assessment","label":"Assessment","labelZh":"评价","pageStart":103,"pageEnd":103,"pageLabel":"103"},{"id":"furtherStudy","label":"Further study","labelZh":"拓展学习","pageStart":103,"pageEnd":103,"pageLabel":"103"},{"id":"workbook","label":"Workbook","labelZh":"随书练习","pageStart":127,"pageEnd":129,"pageLabel":"127–129","location":"appendix"}]}},{"id":"8a-u1","bookId":"8a","number":1,"title":"Friendship","theme":"友谊与朋友","goals":["从人物的行为推断朋友的品质","用比较级和最高级描述朋友的特点","介绍一次体现友谊的小事"],"grammarKeys":["comparatives","superlatives"],"vocabulary":[{"word":"patient","meaning":"耐心的","example":"Nora is patient when I explain a difficult idea.","reviewId":0},{"word":"honest","meaning":"诚实的","example":"An honest friend tells me when I make a mistake.","reviewId":1},{"word":"support","meaning":"支持；帮助","example":"Our classmates offered support before the show.","reviewId":2},{"word":"promise","meaning":"承诺","example":"I made a promise to return the notebook.","reviewId":3},{"word":"notice","meaning":"注意到","example":"Did you notice the empty chair by the window?","reviewId":4},{"word":"proud","meaning":"自豪的","example":"We felt proud of our first radio programme.","reviewId":5},{"word":"mistake","meaning":"错误","example":"One mistake does not end a friendship.","reviewId":6},{"word":"trust","meaning":"信任","example":"I trust Leo to keep our plan secret.","reviewId":7}],"reading":{"id":"8a-u1-reading","title":"The Empty Chair","level":"进阶","text":"When our class started a lunchtime radio club, I wanted to work with my best friend, Nora. She was the funniest person I knew. However, our teacher put me with Arun, a new student who rarely spoke in class. I thought our programme would be boring.\n\nWe had to record a three-minute story about school life. I spoke quickly and made several mistakes. Arun did not laugh. He quietly marked the difficult sentences and asked whether I wanted to try again. Later, I discovered that he could make wonderful sound effects with paper and a small box.\n\nOn Friday, Nora was ill, so her chair in the recording room was empty. Arun suggested sending her our story before anyone else heard it. We added a short message wishing her well.\n\nNora replied that the message was the best part of her day. I still enjoy her jokes, but I have learnt something about friendship. The loudest person is not always the most helpful, and a quiet classmate may have much to share.","summary":"一次校园广播合作让叙述者重新认识安静的新同学，也理解了友谊中的耐心与关心。","questions":[{"prompt":"Who worked with the writer on the radio story?","options":["Nora","Arun","The head teacher","Nora’s brother"],"correctIndex":1,"explanation":"老师把叙述者与新同学 Arun 分到一组。","skill":"细节理解"},{"prompt":"How long did the story have to be?","options":["One minute","Two minutes","Three minutes","Five minutes"],"correctIndex":2,"explanation":"第二段明确要求录制一段三分钟的校园生活故事。","skill":"细节理解"},{"prompt":"What did Arun do when the writer made mistakes?","options":["He marked difficult sentences.","He stopped the club.","He laughed loudly.","He asked Nora to replace the writer."],"correctIndex":0,"explanation":"Arun 安静地标出难句，并询问叙述者是否想再试一次。","skill":"细节理解"},{"prompt":"Why was Nora’s chair empty on Friday?","options":["She left the school.","She forgot the meeting.","She had a music lesson.","She was ill."],"correctIndex":3,"explanation":"第三段说 Nora 生病了，所以没有到录音室。","skill":"细节理解"},{"prompt":"What can we learn about Arun from his actions?","options":["He dislikes working with others.","He is thoughtful and supportive.","He only wants to win a prize.","He is afraid of every new task."],"correctIndex":1,"explanation":"他耐心帮助搭档，还主动提议给生病的 Nora 送去问候，可推断他体贴并愿意支持朋友。","skill":"推断人物品质"}]},"dialogue":{"title":"Choosing a Club Partner","turns":[{"speaker":"Mia","text":"We need a partner for Saturday’s poster project. Shall we ask Daniel?"},{"speaker":"Ben","text":"Good idea. He draws more carefully than I do, and he always finishes his work on time."},{"speaker":"Mia","text":"Let’s meet at the school library at ten. We can make a poster about helping new students."},{"speaker":"Ben","text":"Daniel has a swimming lesson then. Could we meet at eleven instead?"},{"speaker":"Mia","text":"Eleven is fine. I’ll bring the coloured paper. Can you bring the glue?"},{"speaker":"Ben","text":"Yes. I’ll also ask Daniel which part he would like to do. Everyone should have a choice."}],"questions":[{"prompt":"Who does Ben say draws carefully?","options":["Mia","Daniel","His teacher","His sister"],"correctIndex":1,"explanation":"Ben 说 Daniel 画画比自己更细致。","skill":"细节理解"},{"prompt":"Where will they meet?","options":["At a swimming pool","At Ben’s home","At the school library","At a bus stop"],"correctIndex":2,"explanation":"Mia 建议的地点是学校图书馆，后文没有更改地点。","skill":"细节理解"},{"prompt":"What time do they finally agree on?","options":["Eleven","Nine","Ten","Twelve"],"correctIndex":0,"explanation":"Daniel 十点有游泳课，因此两人最终同意十一点见面。","skill":"细节理解"},{"prompt":"What will Mia bring?","options":["Paint","A camera","Scissors","Coloured paper"],"correctIndex":3,"explanation":"Mia 明确说自己会带彩纸。","skill":"细节理解"},{"prompt":"Why will Ben ask Daniel which part he wants to do?","options":["Ben wants to cancel the project.","Ben wants everyone to have a choice.","Daniel cannot read the task.","Mia has already finished everything."],"correctIndex":1,"explanation":"Ben 最后说每个人都应有选择，因此会询问 Daniel 的意愿。","skill":"细节理解"}]},"writing":{"prompt":"写一段80—110词的短文，介绍一位朋友，并用一件小事说明你为什么信任他或她。至少使用一个比较级或最高级。","outline":["介绍朋友及主要特点：My friend ... is ...","叙述一件具体小事：Last ..., we ...","说明自己的感受和学到的道理：I learnt that ..."],"model":"My friend Leo is quieter than most students in our class, but he is one of the most thoughtful people I know. Last month, I lost my notes before a history presentation. Leo stayed after school and helped me put my ideas in order. He did not write the speech for me. Instead, he asked patient questions and listened while I practised. Our presentation was not perfect, but I felt much calmer. I trust Leo because he helps me become more confident. I hope I can offer him the same support when he needs it."},"speakingPrompts":["What qualities do you value most in a friend?","Who is more patient, you or your best friend? Why?","How could you help a classmate who feels left out?"],"textbook":{"status":"edition-checked","referenceEdition":"已核 2025 秋目录；未逐页比较 2026 印次","grammarScope":"形容词比较级和最高级","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"8a-u2","bookId":"8a","number":2,"title":"School life","theme":"学校生活与比较","goals":["比较校园作息与活动安排","用数量比较和as ... as表达异同","用证据提出一条校园改进建议"],"grammarKeys":["quantity_comparison","comparatives"],"vocabulary":[{"word":"schedule","meaning":"时间安排","example":"Our new schedule includes a longer lunch break.","reviewId":0},{"word":"choice","meaning":"选择","example":"Students have a choice of two quiet activities.","reviewId":1},{"word":"queue","meaning":"队伍；排队","example":"The lunch queue moves faster today.","reviewId":2},{"word":"space","meaning":"空间","example":"We need more space for reading.","reviewId":3},{"word":"survey","meaning":"调查","example":"Our class completed a survey about school clubs.","reviewId":4},{"word":"improve","meaning":"改善","example":"Small changes can improve school life.","reviewId":5},{"word":"amount","meaning":"数量","example":"We compared the amount of time spent waiting.","reviewId":6},{"word":"comfortable","meaning":"舒适的","example":"The new reading seats are more comfortable.","reviewId":7}],"reading":{"id":"8a-u2-reading","title":"A Better Lunch Break","level":"进阶","text":"Our school used to give students twenty minutes for lunch. Many of us spent more time in the queue than at the table. When the student council asked for ideas, our class suggested a thirty-five-minute break.\n\nThe head teacher agreed to try the change for one week. Lessons still began at the same time, but the afternoon break became shorter. During the trial, we counted the students waiting outside the dining room. The queue was usually shorter because different classes arrived at different times.\n\nSome students used the extra minutes to read in the courtyard. Others walked around the playground. I expected everyone to love the change, but our survey told a different story. Several students preferred a longer afternoon break because they enjoyed basketball.\n\nAt our next meeting, we shared both opinions. We proposed keeping some afternoon exercise time and changing the lunch schedule on busy days. The head teacher thanked us for bringing information instead of only complaints. We had not found a perfect plan, but we had learnt how to make a fairer one.","summary":"学生用一周试行和问卷反馈评估午休调整，学习用证据兼顾不同需求。","questions":[{"prompt":"How long was the original lunch break?","options":["Fifteen minutes","Twenty minutes","Thirty minutes","Thirty-five minutes"],"correctIndex":1,"explanation":"第一句说明原来的午餐时间是二十分钟。","skill":"细节理解"},{"prompt":"How long did the school test the change?","options":["One day","Two days","One week","One month"],"correctIndex":2,"explanation":"校长同意先尝试一周。","skill":"细节理解"},{"prompt":"Why was the queue usually shorter during the trial?","options":["Classes arrived at different times.","Nobody ate lunch.","Students brought fewer books.","The dining room moved outside."],"correctIndex":0,"explanation":"第二段直接说明各班在不同时间到达，队伍通常更短。","skill":"细节理解"},{"prompt":"Why did some students want a longer afternoon break?","options":["They wanted to leave school early.","They enjoyed more homework.","They needed extra lunch.","They liked playing basketball."],"correctIndex":3,"explanation":"问卷显示一些学生喜欢打篮球，因此希望下午课间更长。","skill":"细节理解"},{"prompt":"Which follow-up proposal would best fit what the class learnt?","options":["Ask only students who liked the first plan.","Collect views from both basketball players and quiet readers.","Cancel every afternoon activity immediately.","Use only the shortest lunch queue as evidence."],"correctIndex":1,"explanation":"调查中既有人喜欢延长午休，也有人重视篮球活动；后续方案应继续兼顾不同群体的意见。","skill":"推断后续行动"}]},"dialogue":{"title":"Two School Libraries","turns":[{"speaker":"Anna","text":"My cousin’s school library opens at eight. Ours opens at half past eight."},{"speaker":"Sam","text":"Does it have more books than ours?"},{"speaker":"Anna","text":"No. It has about two thousand books, while ours has three thousand. But its reading room has more seats."},{"speaker":"Sam","text":"I wish we had a quiet reading club there. I can help on Wednesdays."},{"speaker":"Anna","text":"Our librarian is free on Thursdays. Shall we ask her to start a club then?"},{"speaker":"Sam","text":"Yes. We should first ask classmates how many would join, so we know how much space we need."}],"questions":[{"prompt":"When does Anna’s school library open?","options":["At seven","At eight","At half past eight","At nine"],"correctIndex":2,"explanation":"Anna 说自己学校的图书馆八点半开放；八点是表亲学校的时间。","skill":"细节理解"},{"prompt":"How many books does Anna’s school library have?","options":["Three thousand","Two thousand","One thousand","Five hundred"],"correctIndex":0,"explanation":"对话中的 ours 指 Anna 所在学校，其藏书约三千本。","skill":"细节理解"},{"prompt":"Which library has more seats in its reading room?","options":["The town library","Anna’s school library","The library near Sam’s home","Anna’s cousin’s school library"],"correctIndex":3,"explanation":"Anna 说表亲学校的图书馆藏书较少，但阅览室座位更多。","skill":"细节理解"},{"prompt":"On which day is their librarian free?","options":["Monday","Thursday","Wednesday","Friday"],"correctIndex":1,"explanation":"Anna 明确提到图书管理员周四有空。","skill":"细节理解"},{"prompt":"What will they ask classmates first?","options":["What lunch they want","Which bus they take","How many would join the club","When their cousin will visit"],"correctIndex":2,"explanation":"Sam 建议先了解愿意参加的人数，以判断需要多少空间。","skill":"细节理解"}]},"writing":{"prompt":"写80—110词，提出一项让校园生活更好的建议。比较现在的情况与预期变化，并说明如何收集同学意见。","outline":["描述现状：At present, our school ...","提出变化与比较：We could ... / There would be more ...","说明调查或试行方法：We should ask ..."],"model":"I would like our school to create a quiet corner in the courtyard. At present, there are fewer seats outside than in the library, and many students cannot find a place to read after lunch. We could add several benches near the trees. The corner should be as welcoming as the library, but students would need to keep their voices low. Before buying anything, we should ask classmates when they would use it. We could then try the idea for two weeks and collect their opinions. A small change may make lunchtime more enjoyable."},"speakingPrompts":["What would you change about your school day?","Does your class have more reading time than sports time?","How can a school listen fairly to different students?"],"textbook":{"status":"edition-checked","referenceEdition":"已核 2025 秋目录；未逐页比较 2026 印次","grammarScope":"比较事物的数量；as ... as 同级比较","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"8a-u3","bookId":"8a","number":3,"title":"To be a good learner","theme":"学习方法与学习者成长","goals":["理解尝试、记录与调整学习方法的过程","运用副词比较等级和反身代词","制定可观察、可调整的一周学习计划"],"grammarKeys":["adverbs_comparison","reflexives"],"vocabulary":[{"word":"method","meaning":"方法","example":"I tried a different method for remembering names.","reviewId":0},{"word":"record","meaning":"记录","example":"Keep a record of the words you find difficult.","reviewId":1},{"word":"review","meaning":"复习；回顾","example":"We review yesterday’s notes before learning more.","reviewId":2},{"word":"progress","meaning":"进步","example":"A short diary helps me notice my progress.","reviewId":3},{"word":"explain","meaning":"解释","example":"Can you explain the rule in your own words?","reviewId":4},{"word":"clearly","meaning":"清楚地","example":"Speak clearly when you record your answer.","reviewId":5},{"word":"regularly","meaning":"定期地","example":"I practise regularly instead of waiting until Sunday.","reviewId":6},{"word":"myself","meaning":"我自己","example":"I asked myself why the task was difficult.","reviewId":7}],"reading":{"id":"8a-u3-reading","title":"The Notebook Experiment","level":"进阶","text":"For a long time, I copied every new English word ten times. My pages looked tidy, but I often forgot the words a few days later. One Monday, my teacher asked me to examine the way I studied instead of simply studying longer.\n\nI chose twelve words and divided them into three groups. For the first group, I wrote short sentences. For the second, I drew small pictures. For the third, I recorded myself saying the words in a story. I spent the same amount of time on each group.\n\nOn Wednesday, my sister read the meanings aloud and I wrote the words without looking. On Friday, I tried again. I remembered the words in sentences most easily, although pictures helped with two difficult nouns.\n\nThe experiment did not prove that one method was best for everyone. It showed me what worked better for this particular task. Now I keep a small learning notebook. Beside each activity, I write what helped and what I should change. My notebook is less beautiful, but it tells me more.","summary":"叙述者比较三种记词方法，用两次回顾了解本次任务中适合自己的做法，而非把一种方法当作通用答案。","questions":[{"prompt":"What did the writer do before the experiment?","options":["Copied each new word ten times","Only drew pictures","Never used a notebook","Asked a sister to write all the words"],"correctIndex":0,"explanation":"开头说叙述者过去把每个新词抄写十遍。","skill":"细节理解"},{"prompt":"How many words did the writer choose?","options":["Six","Eight","Ten","Twelve"],"correctIndex":3,"explanation":"第二段写到挑选十二个词，分成三组。","skill":"细节理解"},{"prompt":"What was the same for the three groups?","options":["The number of pictures","The amount of study time","The length of every sentence","The recording speed"],"correctIndex":1,"explanation":"文中明确说在每组上花的学习时间相同。","skill":"细节理解"},{"prompt":"Which approach helped the writer remember most easily in this task?","options":["Copying a whole page","Reading only the meanings","Writing short sentences","Using no notes"],"correctIndex":2,"explanation":"两次回顾后，叙述者发现本次最容易记住的是写进句子的词。","skill":"细节理解"},{"prompt":"If a new study method worked poorly next week, what would the writer most likely do?","options":["Keep using it because a tidy page is all that matters.","Tell everyone to stop studying.","Copy every word more times without checking.","Review the notes and adjust the method."],"correctIndex":3,"explanation":"叙述者已学会记录什么有效、什么要改，并承认方法与任务有关，因此更可能回顾和调整。","skill":"推断后续行动"}]},"dialogue":{"title":"Preparing for a Short Talk","turns":[{"speaker":"Ella","text":"I have a two-minute English talk on Friday, and I’m worried about speaking too quickly."},{"speaker":"Jay","text":"Why not record yourself? You can listen again and mark the sentences that sound unclear."},{"speaker":"Ella","text":"I tried that yesterday. My introduction was clear, but I rushed through the example about my dog."},{"speaker":"Jay","text":"Then practise that example more slowly. You do not need to repeat the whole talk every time."},{"speaker":"Ella","text":"Good idea. Could you listen to me after lunch tomorrow?"},{"speaker":"Jay","text":"Of course. Let’s meet in the empty classroom. I’ll give you feedback on speed and clarity."}],"questions":[{"prompt":"When is Ella’s talk?","options":["Monday","Wednesday","Friday","Sunday"],"correctIndex":2,"explanation":"Ella 第一轮说演讲安排在周五。","skill":"细节理解"},{"prompt":"What worries Ella?","options":["Speaking too quickly","Choosing a school","Losing her lunch","Drawing a dog"],"correctIndex":0,"explanation":"她担心自己说得太快。","skill":"细节理解"},{"prompt":"Which part did Ella rush through?","options":["Her introduction","Her conclusion","A poem","The example about her dog"],"correctIndex":3,"explanation":"Ella 说自己讲到狗的例子时太急了。","skill":"细节理解"},{"prompt":"When will Jay listen to Ella?","options":["Before school today","After lunch tomorrow","On Friday evening","At the weekend"],"correctIndex":1,"explanation":"Ella 请求明天午餐后让 Jay 听，Jay 同意了。","skill":"细节理解"},{"prompt":"What will Jay focus on?","options":["Spelling and handwriting","Clothes and gestures","Speed and clarity","The talk’s title only"],"correctIndex":2,"explanation":"Jay 最后明确会反馈语速和清晰度。","skill":"细节理解"}]},"writing":{"prompt":"写80—110词，介绍你想尝试的一种学习方法。说明目标、具体安排及一周后如何判断是否需要调整。","outline":["确定小目标：This week, I want to ...","安排练习与记录：I will ... for ... minutes.","回顾结果并调整：At the end of the week, I will ..."],"model":"This week, I want to explain my ideas more clearly in English. I will choose one familiar topic each evening and record myself speaking for one minute. Then I will listen and note one sentence that is difficult to understand. I will practise that sentence more slowly and record it again. On Friday, I will ask my partner whether the second recording is clearer than the first. I will not count every small mistake. Instead, I will check whether my main idea is easy to follow. If the plan is too tiring, I will practise on fewer evenings."},"speakingPrompts":["Which learning activity helps you explain ideas more clearly?","How do you check your own progress?","What would you change if a study plan did not work well?"],"textbook":{"status":"edition-checked","referenceEdition":"已核 2025 秋目录；未逐页比较 2026 印次","grammarScope":"副词比较级和最高级；反身代词","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"8a-u4","bookId":"8a","number":4,"title":"Hands-on fun","theme":"动手制作与实践","goals":["理解设计、试作和修改的过程","用祈使句和建议表达交流制作步骤","说明一个简单手工作品的用途与改进"],"grammarKeys":["imperatives","modals_advice"],"vocabulary":[{"word":"cardboard","meaning":"硬纸板","example":"We used cardboard to make a small stage.","reviewId":0},{"word":"measure","meaning":"测量","example":"Measure the box before cutting the paper.","reviewId":1},{"word":"fold","meaning":"折叠","example":"Fold the paper along the blue line.","reviewId":2},{"word":"attach","meaning":"固定；贴上","example":"Attach a handle to the back of the puppet.","reviewId":3},{"word":"design","meaning":"设计","example":"Our first design was too heavy.","reviewId":4},{"word":"tool","meaning":"工具","example":"Put each tool back after the workshop.","reviewId":5},{"word":"reuse","meaning":"再次使用","example":"We can reuse this box for another project.","reviewId":6},{"word":"improve","meaning":"改进","example":"A wider opening will improve the little theatre.","reviewId":7}],"reading":{"id":"8a-u4-reading","title":"A Theatre in a Box","level":"进阶","text":"Our class wanted to tell stories to younger children during the school open day. Buying a puppet theatre was too expensive, so our group decided to make one from a large cardboard box.\n\nAt first, everyone wanted to decorate the outside. Then Lin asked a useful question: could the audience actually see the puppets? We measured the box and drew a wide opening on the front. Our teacher helped us cut it. We painted the background on separate sheets so that we could change scenes easily.\n\nDuring our first practice, the paper trees fell over and one puppet disappeared behind a hill. We laughed, then wrote down the problems. Lin suggested shorter trees, and I attached longer handles to the puppets. We also made a simple list showing who would move each character.\n\nOn open day, the children sat close to the stage and asked for a second story. They hardly noticed the plain outside of our theatre. We learnt that a useful design begins with its audience, and that testing an idea can matter more than decorating it.","summary":"学生用纸箱搭建木偶剧场，在试演中修改视线和操作问题，体会设计要服务使用者。","questions":[{"prompt":"Why did the group make its own theatre?","options":["The shop was closed.","Buying one cost too much.","The children disliked stories.","The teacher forbade all toys."],"correctIndex":1,"explanation":"买剧场太贵，所以他们决定用大纸箱制作。","skill":"细节理解"},{"prompt":"What did Lin ask them to consider first?","options":["The ticket price","The colour of their clothes","Whether the audience could see the puppets","The length of the open day"],"correctIndex":2,"explanation":"Lin 提醒大家先考虑观众能否看见木偶。","skill":"细节理解"},{"prompt":"Who helped cut the opening?","options":["Their teacher","A younger child","The school cook","The librarian"],"correctIndex":0,"explanation":"第二段说明老师帮助他们切出开口。","skill":"细节理解"},{"prompt":"What change did the writer make after the first practice?","options":["Bought a new box","Removed all the puppets","Painted the floor","Added longer puppet handles"],"correctIndex":3,"explanation":"叙述者在第一次试演后给木偶装上更长的把手。","skill":"细节理解"},{"prompt":"If the group built another theatre, what would it most likely check early?","options":["How well the audience can see the puppets","Whether the outside looks expensive","How to avoid every practice","Whether all scenery can be made taller"],"correctIndex":0,"explanation":"第一次制作中，观众视线和试演暴露的问题决定了修改方向，可推断下次会较早检查观看效果。","skill":"推断经验迁移"}]},"dialogue":{"title":"Making a Message Board","turns":[{"speaker":"Owen","text":"Let’s turn this old frame into a message board for the reading corner."},{"speaker":"Lily","text":"Great. We should measure the inside first. It is forty centimetres wide and thirty centimetres high."},{"speaker":"Owen","text":"I have a piece of cardboard that fits. Shall we cover it with blue paper?"},{"speaker":"Lily","text":"Yes, but leave the top clear for the title. We had better use clips for messages so we can change them."},{"speaker":"Owen","text":"I’ll write Reading Together at the top. Could you bring six small clips tomorrow?"},{"speaker":"Lily","text":"Certainly. Let’s ask the librarian before putting the board beside the door."}],"questions":[{"prompt":"What are they making?","options":["A puppet","A message board","A bookshelf","A picture book"],"correctIndex":1,"explanation":"Owen 想把旧相框做成阅读角的留言板。","skill":"细节理解"},{"prompt":"How wide is the inside of the frame?","options":["Twenty centimetres","Thirty centimetres","Forty centimetres","Sixty centimetres"],"correctIndex":2,"explanation":"Lily 说内部宽四十厘米，高三十厘米。","skill":"细节理解"},{"prompt":"What colour paper will they use?","options":["Blue","Green","Red","Yellow"],"correctIndex":0,"explanation":"Owen 提议用蓝纸，Lily 同意。","skill":"细节理解"},{"prompt":"How many clips will Lily bring?","options":["Two","Three","Four","Six"],"correctIndex":3,"explanation":"Owen 请求 Lily 第二天带六个小夹子。","skill":"细节理解"},{"prompt":"Why do they choose clips?","options":["Clips are needed to paint the title.","Messages can be changed easily.","The frame has no sides.","The librarian dislikes paper."],"correctIndex":1,"explanation":"Lily 明确说明用夹子便于更换留言。","skill":"细节理解"}]},"writing":{"prompt":"写80—110词，介绍一个用旧材料制作的小作品。说明用途、主要步骤和一次可以进行的改进。至少用一句建议表达。","outline":["说明材料与用途：We can turn ... into ...","按顺序描述：First, ... Next, ... Finally, ...","提出试用与改进建议：We should ... / We had better ..."],"model":"We can turn a small cardboard box into a desk organiser. First, decide what it needs to hold, such as pencils, cards and a ruler. Next, measure the box and ask an adult for help with any difficult cutting. Add cardboard sections inside, then cover the outside with paper from an old magazine. We should test the organiser before decorating every part. If the pencils fall over, we can make their section narrower. Finally, write small labels for each space. This project gives an old box a new use and helps us keep our desks tidy."},"speakingPrompts":["What useful object could you make from an old box?","Why should you test a design before finishing it?","What advice would you give to a group starting a craft project?"],"textbook":{"status":"edition-checked","referenceEdition":"已核 2025 秋目录；未逐页比较 2026 印次","grammarScope":"祈使句；should 与 had better 表达建议","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"8a-u5","bookId":"8a","number":5,"title":"Wild animals","theme":"野生动物与保护","goals":["理解观察野生动物时的行为选择","用不定式表达目的和计划","根据观察记录作出有分寸的推断"],"grammarKeys":["infinitives"],"vocabulary":[{"word":"observe","meaning":"观察","example":"We observed the bird from the marked path.","reviewId":0},{"word":"distance","meaning":"距离","example":"Keep enough distance to avoid disturbing the animal.","reviewId":1},{"word":"quietly","meaning":"安静地","example":"The group waited quietly beside the sign.","reviewId":2},{"word":"habitat","meaning":"栖息地","example":"The river bank is part of the bird’s habitat.","reviewId":3},{"word":"recording","meaning":"录制品；记录","example":"Our recording includes the sound of running water.","reviewId":4},{"word":"disturb","meaning":"打扰","example":"We did not want to disturb the resting birds.","reviewId":5},{"word":"return","meaning":"返回","example":"The heron returned after the visitors had left.","reviewId":6},{"word":"protect","meaning":"保护","example":"A clear path can help protect a special place.","reviewId":7}],"reading":{"id":"8a-u5-reading","title":"Watching from a Distance","level":"进阶","text":"Our nature club went to the river to make a short film about a grey heron. We hoped to show younger students how to watch wildlife responsibly. Before the visit, our teacher asked us to plan where to stand and what to record.\n\nAt the river bend, we found a marked viewing area. The heron stood near the water, but a group of visitors moved closer to take photographs. The bird flew away. We stayed behind the sign and waited for twenty minutes before it returned.\n\nBen wanted to say in our film that people always frightened birds away. Our teacher asked him to look carefully at our notes. We had seen one bird on one morning. We could describe that event, but we could not explain every bird’s behaviour.\n\nWe changed the film’s final message. Instead of making a big claim, we showed the viewing sign and explained our choice to keep a distance. We included the time, weather and place in our record. Our film became shorter, but our observations became more careful.","summary":"一次河边拍摄让学生学会保持距离，也学会区分一次观察与普遍结论。","questions":[{"prompt":"Why did the club visit the river?","options":["To race boats","To build a bridge","To make a film about a heron","To collect fish"],"correctIndex":2,"explanation":"第一段说明他们去河边拍摄关于苍鹭的短片。","skill":"细节理解"},{"prompt":"Where did the club wait?","options":["Behind the viewing sign","In the water","Beside the heron","On a boat"],"correctIndex":0,"explanation":"访客靠近后，社团成员留在标志后方等待。","skill":"细节理解"},{"prompt":"How long did they wait before the heron returned?","options":["Five minutes","Ten minutes","Fifteen minutes","Twenty minutes"],"correctIndex":3,"explanation":"第二段写明等待二十分钟后苍鹭返回。","skill":"细节理解"},{"prompt":"What did they include in their observation record?","options":["Only the bird’s colour","The time, weather and place","Visitors’ home addresses","The price of their camera"],"correctIndex":1,"explanation":"最后一段列出他们记录的时间、天气和地点。","skill":"细节理解"},{"prompt":"Why did the teacher question Ben’s claim?","options":["She wanted a longer film.","She had not seen the river.","One observation cannot explain every bird’s behaviour.","She believed visitors never affect animals."],"correctIndex":2,"explanation":"他们只观察了一天中的一只鸟，证据不足以支持“总是”这样的结论。","skill":"推断论证限制"}]},"dialogue":{"title":"Planning a Wildlife Visit","turns":[{"speaker":"Zoe","text":"The wildlife club will visit the riverside viewing area on Sunday. We will leave school at eight."},{"speaker":"Max","text":"Should I bring my camera? I would like to take pictures of the birds."},{"speaker":"Zoe","text":"Yes, but we must stay on the marked path. The guide will lend us binoculars to see distant birds."},{"speaker":"Max","text":"I’ll bring a notebook too. What information should I write down?"},{"speaker":"Zoe","text":"Record the time, place and what you actually see. Please do not guess the names of birds you cannot identify."},{"speaker":"Max","text":"Understood. I’ll draw them and ask the guide. We can compare our notes when we return at noon."}],"questions":[{"prompt":"On which day is the visit?","options":["Saturday","Sunday","Monday","Friday"],"correctIndex":1,"explanation":"Zoe 说河边观察活动在周日进行。","skill":"细节理解"},{"prompt":"When will the group leave school?","options":["At six","At seven","At eight","At noon"],"correctIndex":2,"explanation":"出发时间明确为八点。","skill":"细节理解"},{"prompt":"Who will lend them binoculars?","options":["The guide","Max’s father","The school cook","Zoe’s cousin"],"correctIndex":0,"explanation":"Zoe 说导览员会借双筒望远镜给他们。","skill":"细节理解"},{"prompt":"What should Max do if he cannot identify a bird?","options":["Give it a new name","Ignore all his notes","Move off the path","Draw it and ask the guide"],"correctIndex":3,"explanation":"Max 最后决定先画下来，再问导览员。","skill":"细节理解"},{"prompt":"When will they compare their notes?","options":["Before leaving school","When they return at noon","During dinner","Next month"],"correctIndex":1,"explanation":"最后一句说明中午返回时比较笔记。","skill":"细节理解"}]},"writing":{"prompt":"写80—110词，为一次观察野生动物的活动制定计划。说明观察目的、如何记录以及如何避免干扰动物。","outline":["说明目的：We plan to ... / We hope to ...","说明安排与记录：We will record ...","说明行为选择：To avoid disturbing ..., we will ..."],"model":"Our club plans to visit a wetland viewing area next Saturday. We hope to learn how to observe birds without disturbing them. Before the trip, we will check the visitor information and prepare notebooks. At the site, we will follow the guide and stay on the marked path. We will record the time, weather and behaviours we actually see. If we cannot identify a bird, we will sketch it and ask for help. We will compare our notes afterwards. Our aim is to become more careful observers, not to get the closest photograph."},"speakingPrompts":["Why might a good wildlife photograph require patience?","What would you record during a wildlife observation?","How can you explain the purpose of keeping a distance?"],"textbook":{"status":"edition-checked","referenceEdition":"已核 2025 秋目录；未逐页比较 2026 印次","grammarScope":"动词后接带to不定式；不定式表示目的；动词+宾语+带to或不带to不定式","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"8a-u6","bookId":"8a","number":6,"title":"Seasons","theme":"四季与天气","goals":["理解四季观察记录中的细节与变化","辨认句子中的主语、动词、宾语或表语","用具体感官信息描述一个季节"],"grammarKeys":["sentence_patterns"],"vocabulary":[{"word":"branch","meaning":"树枝","example":"A small kite rested on the highest branch.","reviewId":0},{"word":"shadow","meaning":"影子","example":"The tree’s shadow reached across the bench.","reviewId":1},{"word":"breeze","meaning":"微风","example":"A cool breeze moved the curtain.","reviewId":2},{"word":"bare","meaning":"光秃的","example":"The tree looked bare in January.","reviewId":3},{"word":"surface","meaning":"表面","example":"Drops of rain covered the surface of the bench.","reviewId":4},{"word":"season","meaning":"季节","example":"Each season changed the view outside the window.","reviewId":5},{"word":"sunlight","meaning":"阳光","example":"Soft sunlight filled the reading room.","reviewId":6},{"word":"description","meaning":"描述","example":"Her description included sounds as well as colours.","reviewId":7}],"reading":{"id":"8a-u6-reading","title":"The Same Window","level":"进阶","text":"In September, our English teacher gave us an unusual task. Each month, we had to describe the view from the same school window. I chose the library window facing a tree and a wooden bench. At first, I thought the view would hardly change.\n\nIn October, yellow leaves covered half the bench. A boy waited there after school and watched the leaves fall. In January, the branches were bare. Rain left small shining pools on the seat, and almost nobody stopped to rest.\n\nBy April, fresh leaves softened the afternoon sunlight. Two students sat under the tree to practise a dialogue. In June, the shadow grew wider, and the bench became a popular place to read.\n\nWhen I placed four of my descriptions together, I noticed more than changes in colour. The weather had also changed the way people used the space. My teacher circled a sentence: “The tree gives readers a cool place.” She asked us to identify its parts. Suddenly, sentence structures felt connected to a real view that I knew well.","summary":"学生通过同一扇窗连续观察，发现季节既改变景物，也改变人们使用校园空间的方式。","questions":[{"prompt":"Which window did the writer choose?","options":["A classroom window facing a road","The library window facing a tree and a bench","A kitchen window facing a car park","A window in the sports hall"],"correctIndex":1,"explanation":"第一段交代所选的是面对一棵树和长椅的图书馆窗户。","skill":"细节理解"},{"prompt":"What covered half the bench in October?","options":["Snow","Books","Yellow leaves","Newspapers"],"correctIndex":2,"explanation":"第二段说十月的黄叶盖住了半张长椅。","skill":"细节理解"},{"prompt":"What were two students doing under the tree in April?","options":["Practising a dialogue","Repairing the bench","Playing football","Eating breakfast"],"correctIndex":0,"explanation":"四月两名学生在树下练习对话。","skill":"细节理解"},{"prompt":"What did the teacher ask students to identify?","options":["The species of the tree","The name of the boy","The owner of the bench","The parts of a sentence"],"correctIndex":3,"explanation":"最后一段中，老师圈出一句话并让学生辨认句子成分。","skill":"细节理解"},{"prompt":"Why would the bench probably appeal to readers on a hot June afternoon?","options":["It was moved inside the library.","The wider tree shadow would offer shade.","No one else knew where it was.","The January rain was still on the seat."],"correctIndex":1,"explanation":"六月树影变大，长椅也更受阅读者欢迎；结合热天情境，可推断树荫是吸引读者的原因。","skill":"推断行为原因"}]},"dialogue":{"title":"Choosing a Photo for the Wall","turns":[{"speaker":"Finn","text":"We need one seasonal photograph for the classroom wall. I have a picture of our garden in autumn."},{"speaker":"Ava","text":"What can we see in it?"},{"speaker":"Finn","text":"There are orange leaves on the path, and my grandfather is carrying a basket near the gate."},{"speaker":"Ava","text":"That sounds interesting. My winter picture shows an empty bench after rain, but it is quite dark."},{"speaker":"Finn","text":"Let’s use the autumn picture this month. You could add one sentence about how the garden feels."},{"speaker":"Ava","text":"All right. I’ll write, The soft light makes the garden peaceful. We can display my winter picture in December."}],"questions":[{"prompt":"Where will they display the photograph?","options":["On the classroom wall","At the railway station","In a shop window","On a library door"],"correctIndex":0,"explanation":"Finn 说照片要放在教室墙上。","skill":"细节理解"},{"prompt":"Which season appears in Finn’s picture?","options":["Spring","Summer","Winter","Autumn"],"correctIndex":3,"explanation":"Finn 的照片拍的是秋天的花园。","skill":"细节理解"},{"prompt":"Who is carrying a basket?","options":["Finn’s teacher","Finn’s grandfather","Ava’s sister","Their classmate"],"correctIndex":1,"explanation":"照片中的人物是 Finn 的爷爷。","skill":"细节理解"},{"prompt":"What problem does Ava mention about her photo?","options":["It is torn.","It has no bench.","It is quite dark.","It is too large."],"correctIndex":2,"explanation":"Ava 说自己的冬季照片比较暗。","skill":"细节理解"},{"prompt":"When do they plan to display Ava’s winter picture?","options":["In December","Next week","In April","In July"],"correctIndex":0,"explanation":"Ava 最后提出十二月再展示冬季照片。","skill":"细节理解"}]},"writing":{"prompt":"写80—110词，描述你熟悉的一个季节景象。至少包含一种声音或触感，并说明人们会在这个季节做什么。","outline":["交代地点与季节：In ..., the ... looks ...","加入感官细节：I can see/hear/feel ...","连接景色与活动：The weather gives us ..."],"model":"Autumn is my favourite season in our school garden. The leaves turn yellow, and a gentle breeze moves them across the path. In the afternoon, sunlight falls through the branches and makes bright shapes on the ground. I can hear dry leaves under my shoes when I walk to the reading corner. Some students sit on the benches with books, while others sketch the trees. The air feels cooler than in summer, so I usually carry a light jacket. I like this view because it changes a little each day and gives me something new to notice."},"speakingPrompts":["How does your neighbourhood change with the seasons?","Which sounds or colours remind you of autumn?","Can you describe a seasonal scene in three different sentence patterns?"],"textbook":{"status":"edition-checked","referenceEdition":"已核 2025 秋目录；未逐页比较 2026 印次","grammarScope":"动词与基本句子结构（第一部分）","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"8a-u7","bookId":"8a","number":7,"title":"The natural world","theme":"自然世界与生态系统","goals":["从观察图中理解自然环境里的联系","使用基本句型及and、but、or、so组织信息","说明一个保护校园自然角的想法"],"grammarKeys":["sentence_patterns","conjunctions"],"vocabulary":[{"word":"pond","meaning":"池塘","example":"Our class drew a map of the small pond.","reviewId":0},{"word":"edge","meaning":"边缘","example":"We observed the plants near the edge.","reviewId":1},{"word":"shelter","meaning":"躲避处；遮蔽物","example":"The thick leaves provided shelter for tiny animals.","reviewId":2},{"word":"insect","meaning":"昆虫","example":"An insect landed on the notebook.","reviewId":3},{"word":"connection","meaning":"联系","example":"The map showed a connection between plants and shade.","reviewId":4},{"word":"shade","meaning":"阴凉处","example":"The shaded part of the path stayed cool.","reviewId":5},{"word":"compare","meaning":"比较","example":"We compared two drawings of the same place.","reviewId":6},{"word":"environment","meaning":"环境","example":"A quiet visit helped us understand the local environment.","reviewId":7}],"reading":{"id":"8a-u7-reading","title":"More Than a Blue Circle","level":"进阶","text":"When our class drew maps of the school grounds, most groups represented the small pond as a blue circle. Our science teacher asked us to visit it again and find out what the simple symbol had missed.\n\nWe worked in pairs and observed from the path. My partner drew the plants around the edge, while I marked sunny and shaded places. We saw insects above the water and tiny movements between the leaves. We could not identify every animal, so we used numbers and added descriptions rather than inventing names.\n\nBack in class, we joined our drawings. The new map showed places where living things could find shade or shelter. It also showed a narrow section of path where visitors often stepped towards the water.\n\nWe suggested adding a small viewing marker there. We wanted people to see the pond, but we also wanted them to protect its edges. Our final map looked less simple than a blue circle. It was more useful because it showed connections, observations and questions that we still needed to explore.","summary":"学生重新绘制校园池塘地图，用观察替代简单符号，呈现环境联系并提出进一步的问题。","questions":[{"prompt":"How did most groups first show the pond?","options":["As a green square","As a blue circle","As a red line","As a yellow triangle"],"correctIndex":1,"explanation":"第一段说大多数组用蓝色圆圈表示池塘。","skill":"细节理解"},{"prompt":"What did the writer mark during the second visit?","options":["The cost of the plants","The depth of every part","Sunny and shaded places","The ages of the trees"],"correctIndex":2,"explanation":"搭档画植物，叙述者标注向阳和阴凉的位置。","skill":"细节理解"},{"prompt":"What did they do when they could not identify an animal?","options":["Used a number and a description","Invented a name","Removed it from the pond","Asked visitors to catch it"],"correctIndex":0,"explanation":"第二段说明他们用编号并附描述，没有编造名称。","skill":"细节理解"},{"prompt":"What did they suggest adding?","options":["A large bridge","A food stall","A fishing platform","A small viewing marker"],"correctIndex":3,"explanation":"第四段建议在狭窄路段增加一个小型观察标记。","skill":"细节理解"},{"prompt":"If the group revisited the pond a month later, which action would best fit its approach?","options":["Copy the first blue circle and ignore new details.","Remove any animal it could not name.","Repeat observations and compare them with the earlier map.","Assume that no part of the pond could change."],"correctIndex":2,"explanation":"小组的做法是详细观察、记录不确定性和提出问题，因此重访时再次观察并比较更符合其研究方法。","skill":"推断经验迁移"}]},"dialogue":{"title":"A Nature Corner","turns":[{"speaker":"Ruby","text":"Our class can look after the nature corner beside the playground. What should we record first?"},{"speaker":"Noah","text":"Let’s list the plants and draw a map. The left side gets afternoon sun, but the right side stays shaded."},{"speaker":"Ruby","text":"I noticed three different kinds of leaves there yesterday. We can photograph them without picking them."},{"speaker":"Noah","text":"Good plan. I’ll bring the school tablet, and you can bring a ruler for measuring fallen leaves."},{"speaker":"Ruby","text":"Shall we meet after the science lesson on Tuesday?"},{"speaker":"Noah","text":"Yes. If we find something we cannot name, we can ask our science teacher instead of guessing."}],"questions":[{"prompt":"Where is the nature corner?","options":["Beside the playground","Behind the station","Inside the library","Near Noah’s home"],"correctIndex":0,"explanation":"Ruby 第一轮说明自然角在操场旁边。","skill":"细节理解"},{"prompt":"Which side stays shaded?","options":["The front","The left","Both sides","The right"],"correctIndex":3,"explanation":"Noah 说右边一直处在阴凉中。","skill":"细节理解"},{"prompt":"How many kinds of leaves did Ruby notice?","options":["Two","Three","Four","Five"],"correctIndex":1,"explanation":"Ruby 昨天观察到三种不同叶片。","skill":"细节理解"},{"prompt":"What will Noah bring?","options":["A ruler","A basket","The school tablet","A football"],"correctIndex":2,"explanation":"Noah 负责带学校的平板电脑，Ruby 带尺子。","skill":"细节理解"},{"prompt":"Who can help them name something unfamiliar?","options":["Their science teacher","A bus driver","The librarian’s neighbour","Noah’s younger brother"],"correctIndex":0,"explanation":"Noah 建议请教科学老师，而非随意猜名字。","skill":"细节理解"}]},"writing":{"prompt":"写80—110词，提出一项认识或保护校园自然角的小活动。说明如何观察、记录与提出问题。","outline":["介绍自然角：There is ... near ...","说明观察办法：We can ..., and ...","解释保护与研究的关系：We want to ..., but ..."],"model":"There is a small garden beside our sports hall, but many students walk past without noticing it. Our class could make a simple observation map. We can draw the plants and mark places that receive sunlight or shade. We should describe unfamiliar insects instead of guessing their names. Each group could add one question for the science teacher. We also want to keep the garden tidy, so we will ask where a waste bin would be useful. The activity would help us see that a small natural space contains many connections worth exploring."},"speakingPrompts":["What can you observe in a small pond or garden?","Why is it useful to record a question you cannot answer?","How can a viewing area help both visitors and nature?"],"textbook":{"status":"edition-checked","referenceEdition":"已核 2025 秋目录；未逐页比较 2026 印次","grammarScope":"动词与基本句子结构（第二部分）；and、but、or、so连接成分或句子","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"8a-u8","bookId":"8a","number":8,"title":"Safe and sound","theme":"安全与灾害应对","goals":["按时间顺序理解一次突发情况","用过去进行时描述当时正在发生的动作","表达求助、清点与保持联系的重要性"],"grammarKeys":["past_continuous"],"vocabulary":[{"word":"power","meaning":"电力","example":"The power went out during our rehearsal.","reviewId":0},{"word":"torch","meaning":"手电筒","example":"The caretaker brought a battery torch.","reviewId":1},{"word":"calm","meaning":"镇静的","example":"Our teacher’s calm voice helped us listen.","reviewId":2},{"word":"entrance","meaning":"入口","example":"The group waited away from the main entrance.","reviewId":3},{"word":"instruction","meaning":"指示","example":"We listened carefully to the teacher’s instructions.","reviewId":4},{"word":"contact","meaning":"联系","example":"The office contacted our families.","reviewId":5},{"word":"rehearsal","meaning":"排练","example":"We were having a rehearsal when the room became dark.","reviewId":6},{"word":"account for","meaning":"确认全员在场","example":"The teacher checked the list to account for everyone.","reviewId":7}],"reading":{"id":"8a-u8-reading","title":"When the Room Went Dark","level":"进阶","text":"We were rehearsing a play at the community centre when the lights suddenly went out. A storm was passing over the town. For a moment, everyone stopped speaking. I was holding a cardboard moon, and my partner was moving a chair across the stage.\n\nOur teacher asked us to stay where we were while she spoke to the caretaker. Soon he arrived with battery torches and explained that the whole building had lost power. Following the centre’s instructions, the adults guided us to a waiting room away from the stage equipment.\n\nWhile the teacher checked our names, the office contacted our families. My younger brother was in a different activity upstairs. I wanted to look for him, but the teacher told me that his group was already with another adult. A few minutes later, they joined us.\n\nWe did not finish our rehearsal that evening. The next day, however, we discussed what had helped: clear instructions, a class list and adults sharing information. I remembered every sound from the dark room, but I also remembered how reassuring a familiar voice could be.","summary":"社区中心停电时，排练中的学生在工作人员引导下集合，事后回顾清晰指示与及时沟通的作用。","questions":[{"prompt":"What were the students doing when the lights went out?","options":["Watching a film","Rehearsing a play","Playing a match","Taking a test"],"correctIndex":1,"explanation":"第一句说明当时正在社区中心排练戏剧。","skill":"细节理解"},{"prompt":"What was the writer holding?","options":["A battery torch","A class list","A cardboard moon","A school bag"],"correctIndex":2,"explanation":"第一段写到叙述者手中拿着硬纸板做的月亮。","skill":"细节理解"},{"prompt":"Who brought battery torches?","options":["The caretaker","The writer’s brother","A parent","The music teacher"],"correctIndex":0,"explanation":"第二段说明看管员带来了电池手电筒。","skill":"细节理解"},{"prompt":"Where was the younger brother when the writer first worried about him?","options":["Alone outside","At home","On the stage","With another adult and his group"],"correctIndex":3,"explanation":"老师说明弟弟所在小组已经有另一位成年人照看。","skill":"细节理解"},{"prompt":"How would the writer most likely feel when the younger brother’s group arrived?","options":["Bored because no one spoke","Angry that the play was changed","Proud of causing the power cut","Relieved that the brother was with his group and an adult"],"correctIndex":3,"explanation":"叙述者先担心弟弟并想去找他；随后确认弟弟有成人照看且来到同一处，可推断其感到放心。","skill":"推断人物感受"}]},"dialogue":{"title":"Checking the Group","turns":[{"speaker":"Tara","text":"I’m writing our report about yesterday’s practice. What were you doing when the bell rang?"},{"speaker":"Alex","text":"I was putting away paintbrushes in the art room. Ms Chen asked our group to follow the school’s practice route."},{"speaker":"Tara","text":"I was reading in the library. Our group reached the meeting point at ten fifteen."},{"speaker":"Alex","text":"We arrived two minutes later. Ms Chen checked fourteen names, but she expected fifteen."},{"speaker":"Tara","text":"Was anyone missing?"},{"speaker":"Alex","text":"No. The office confirmed that one student had gone home with a parent before the practice. Ms Chen updated the list."}],"questions":[{"prompt":"What is Tara writing?","options":["An invitation","A report about the practice","A shopping list","A film review"],"correctIndex":1,"explanation":"Tara 在写关于昨天演练的报告。","skill":"细节理解"},{"prompt":"What was Alex doing when the bell rang?","options":["Reading a novel","Eating lunch","Putting away paintbrushes","Playing the piano"],"correctIndex":2,"explanation":"Alex 说铃响时自己正在收拾画笔。","skill":"细节理解"},{"prompt":"When did Tara’s group reach the meeting point?","options":["At 10:15","At 10:05","At 10:17","At 10:30"],"correctIndex":0,"explanation":"Tara 明确说本组十点十五分到达集合点。","skill":"细节理解"},{"prompt":"How many students did Ms Chen originally expect?","options":["Twelve","Thirteen","Fourteen","Fifteen"],"correctIndex":3,"explanation":"Ms Chen 查到十四人，但名单预期人数为十五人。","skill":"细节理解"},{"prompt":"Why was one student absent from the practice?","options":["The student hid in the art room.","The student had gone home with a parent.","The student forgot the bell.","The student went shopping alone."],"correctIndex":1,"explanation":"办公室确认该生在演练前已由家长接回家。","skill":"细节理解"}]},"writing":{"prompt":"写80—110词，描述一次校园演练或虚构的突发小事件。说明当时大家正在做什么、如何在老师指引下处理以及学到了什么。","outline":["交代背景：We were ... when ...","叙述处理过程：While ..., our teacher ...","总结经验：The experience showed me ..."],"model":"Yesterday, our class took part in a school practice. I was reading a magazine when the signal sounded. Our teacher asked us to follow the route we had discussed earlier. At the meeting point, she checked the class list while another teacher shared information with the office. One classmate felt nervous, so I stood beside him and listened with him. Everyone in our group was accounted for. Afterwards, we talked about the importance of clear instructions and an accurate list. I learnt that listening carefully and staying with the group can help a practice run smoothly."},"speakingPrompts":["What were you doing when a recent school practice began?","Why is an accurate class list useful?","How could you help a nervous classmate during a supervised practice?"],"textbook":{"status":"edition-checked","referenceEdition":"已核 2025 秋目录；未逐页比较 2026 印次","grammarScope":"过去进行时","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"8b-u1","bookId":"8b","number":1,"title":"Past and present","theme":"过去与现在的变化","goals":["比较过去与现在并区分变化与延续","用现在完成时描述与现在有关的变化","通过采访和图文记录呈现社区故事"],"grammarKeys":["present_perfect"],"vocabulary":[{"word":"recently","meaning":"最近","example":"We have recently collected stories about our street.","reviewId":0},{"word":"replace","meaning":"替换","example":"The new bridge has replaced a narrow wooden one.","reviewId":1},{"word":"memory","meaning":"记忆","example":"The old photograph brought back a happy memory.","reviewId":2},{"word":"interview","meaning":"采访","example":"I prepared three questions for the interview.","reviewId":3},{"word":"develop","meaning":"发展","example":"The neighbourhood has developed around the station.","reviewId":4},{"word":"remain","meaning":"仍然是；留下","example":"The old tree remains beside the gate.","reviewId":5},{"word":"former","meaning":"以前的","example":"The former market building is now a library.","reviewId":6},{"word":"change","meaning":"变化","example":"Our map shows changes in the town centre.","reviewId":7}],"reading":{"id":"8b-u1-reading","title":"A Map with Two Dates","level":"进阶","text":"For our local history project, I drew a map of the square near my home. I marked the library, the bus stop and a small garden. Then my grandmother brought out a photograph taken thirty years earlier.\n\nThe library building was already there, but it was a market at that time. A narrow bridge crossed the stream behind it. Today, the bridge has become wider, and a walking path has been added along the water. The old fig tree still stands beside the entrance.\n\nI asked Grandma what she missed most. I expected her to name a building. Instead, she remembered a woman who sold warm bread and knew every customer’s name. No map could show that friendship clearly.\n\nWe interviewed two neighbours and added their memories beside the places on my map. Some changes have made the square easier to use, but the stories helped us understand what the buildings had meant to people. My final project has two dates and several voices. It shows not only what has changed, but also what people hope to remember.","summary":"祖孙对照地图与旧照片，又采访邻居，把建筑变化和居民记忆一起记录下来。","questions":[{"prompt":"What was the writer’s project about?","options":["Local history","A sports club","A cooking lesson","A mountain trip"],"correctIndex":0,"explanation":"开头说明这是本地历史项目。","skill":"细节理解"},{"prompt":"What was the present library building thirty years ago?","options":["A hospital","A cinema","A station","A market"],"correctIndex":3,"explanation":"第二段说同一座建筑以前用作市场。","skill":"细节理解"},{"prompt":"What still stands beside the entrance?","options":["A bread stall","The old fig tree","A wooden bus stop","A red telephone box"],"correctIndex":1,"explanation":"文中明确指出入口旁的老无花果树仍在。","skill":"细节理解"},{"prompt":"How many neighbours did they interview?","options":["One","Four","Two","Six"],"correctIndex":2,"explanation":"最后一段说他们采访了两位邻居。","skill":"细节理解"},{"prompt":"Why did they add memories beside the places on the map?","options":["Places also carry personal relationships and experiences.","The writer could not draw buildings.","The photograph had no date.","Every old building had disappeared."],"correctIndex":0,"explanation":"奶奶最怀念的是熟悉的卖面包人，说明地方的意义也来自人与经历，地图上的口述记忆补充了这些内容。","skill":"推断记录价值"}]},"dialogue":{"title":"An Old Street, a New Use","turns":[{"speaker":"Clara","text":"Have you seen the old post office recently? It has become a community reading room."},{"speaker":"Eric","text":"Really? I last went inside it three years ago. When did the reading room open?"},{"speaker":"Clara","text":"It opened in March. Volunteers have collected about six hundred books since then."},{"speaker":"Eric","text":"Has the big clock above the entrance gone?"},{"speaker":"Clara","text":"No, it is still there. The reading tables are new, but the wooden counter has been kept for displays."},{"speaker":"Eric","text":"I’d like to visit on Saturday. I can bring a photograph of the building from my grandfather’s collection."}],"questions":[{"prompt":"What has the old post office become?","options":["A café","A reading room","A museum shop","A music classroom"],"correctIndex":1,"explanation":"Clara 说旧邮局已变成社区阅览室。","skill":"细节理解"},{"prompt":"When did it open for its new use?","options":["In January","In February","In March","In June"],"correctIndex":2,"explanation":"Clara 明确说明三月开放。","skill":"细节理解"},{"prompt":"About how many books have volunteers collected?","options":["Six hundred","Three hundred","Sixty","Three thousand"],"correctIndex":0,"explanation":"对话中的数目是约六百本。","skill":"细节理解"},{"prompt":"What has happened to the big clock?","options":["It has been sold.","It has been moved upstairs.","It has been broken.","It is still above the entrance."],"correctIndex":3,"explanation":"Clara 回答大钟仍在原处。","skill":"细节理解"},{"prompt":"What does Eric plan to bring?","options":["A new table","An old photograph of the building","A box of stamps","A model clock"],"correctIndex":1,"explanation":"Eric 想带爷爷收藏的一张建筑旧照片。","skill":"细节理解"}]},"writing":{"prompt":"写80—110词，比较你熟悉的一个地方过去和现在的样子。说明至少一个变化、一个保留下来的事物，以及你的看法。","outline":["介绍地点及过去：... used to ...","描述变化与延续：... has changed ... / ... is still ...","说明变化的意义：I think ... because ..."],"model":"The small square near my home has changed a lot. A few years ago, it was mainly a place where people parked bicycles. Now it has a reading shelter and several benches. The council has also added a walking path beside the trees. However, the old stone sign is still at the entrance. My grandfather remembers meeting friends there after work. I think the square is more comfortable now, but its older features are also valuable. I would like to collect residents’ memories so that the new space keeps a connection with its past."},"speakingPrompts":["What has changed in your neighbourhood?","Which old place or object would you like to keep?","How can an interview add something that a map cannot show?"],"textbook":{"status":"edition-checked","referenceEdition":"已核 2026 春目录；版权页未取得","grammarScope":"现在完成时","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"8b-u2","bookId":"8b","number":2,"title":"Amazing China","theme":"中国风景与旅行","goals":["理解旅行计划中的信息与不同需求","区分have been与have gone并描述经历","制定有取舍、含备用方案的旅行计划"],"grammarKeys":["present_perfect","perfect_duration"],"vocabulary":[{"word":"destination","meaning":"目的地","example":"We discussed two possible destinations for our trip.","reviewId":0},{"word":"route","meaning":"路线","example":"Our route includes time to rest.","reviewId":1},{"word":"attraction","meaning":"景点；有吸引力的事物","example":"The small garden is our first attraction.","reviewId":2},{"word":"reservation","meaning":"预订","example":"Dad checked the hotel reservation again.","reviewId":3},{"word":"journey","meaning":"旅程","example":"A good plan can make a journey less tiring.","reviewId":4},{"word":"souvenir","meaning":"纪念品","example":"Grandma kept a postcard as a souvenir.","reviewId":5},{"word":"experience","meaning":"经历；体验","example":"Mei shared her experience of travelling with her family.","reviewId":6},{"word":"instead","meaning":"代替；反而","example":"We chose one museum instead of three.","reviewId":7}],"reading":{"id":"8b-u2-reading","title":"A Plan for Three Travellers","level":"进阶","text":"My father, my grandmother and I are planning a short trip to Suzhou. At first, I filled two pages with places I wanted to visit. Dad looked at the list and asked when we would have time to enjoy any of them.\n\nMy cousin Mei has been to Suzhou twice, so I asked for her advice. She suggested choosing one main activity each day and leaving time for unexpected discoveries. Grandma has collected postcards for many years. She wanted to sit in a garden and sketch a view rather than hurry from place to place.\n\nWe changed our plan. On the first day, we will visit a museum and explore one nearby street. On the second, we will spend the morning in a garden. I will carry a small notebook so we can draw or write about what interests us.\n\nOur plan now contains fewer stops, but all three travellers have helped shape it. We have also written down an indoor alternative in case it rains. I have begun to understand that a successful journey is not simply a long list of attractions.","summary":"一家三代调整旅行计划，把不同兴趣、休息与备用方案纳入考虑。","questions":[{"prompt":"Where are the three family members planning to go?","options":["Nanjing","Suzhou","Beijing","Chengdu"],"correctIndex":1,"explanation":"第一句明确说明计划前往苏州。","skill":"细节理解"},{"prompt":"How many times has Mei been there?","options":["Once","Three times","Twice","Four times"],"correctIndex":2,"explanation":"第二段说明表亲 Mei 去过苏州两次。","skill":"细节理解"},{"prompt":"What does Grandma want to do?","options":["Sketch a garden view","Visit every shop","Climb a mountain","Buy a camera"],"correctIndex":0,"explanation":"奶奶想坐在园林里画风景，不想赶景点。","skill":"细节理解"},{"prompt":"What have they prepared in case of rain?","options":["Extra tickets for every site","A longer outdoor walk","A third travel day","An indoor alternative"],"correctIndex":3,"explanation":"最后一段写到他们已准备室内备用活动。","skill":"细节理解"},{"prompt":"Why does the writer feel better about the shorter plan?","options":["It removes Grandma’s interests.","It gives everyone a part in shaping the trip.","It guarantees perfect weather.","It avoids all new experiences."],"correctIndex":1,"explanation":"新方案减少了停留点，但三人的兴趣都有参与，可推断计划更贴合同行者。","skill":"推断计划评价"}]},"dialogue":{"title":"Postcards from a Journey","turns":[{"speaker":"Sophie","text":"Have you ever been to Nanjing, Jack? I’m planning a family visit."},{"speaker":"Jack","text":"Yes, I went there last spring. My sister has gone there again this week, but she has not returned yet."},{"speaker":"Sophie","text":"What did you enjoy most on your visit?"},{"speaker":"Jack","text":"I enjoyed a small museum and an evening walk with my cousins. We stayed for two nights."},{"speaker":"Sophie","text":"My father wants to visit a garden, and I want to write postcards. We will choose one main activity each day."},{"speaker":"Jack","text":"That sounds sensible. I’ll show you my travel notebook tomorrow. It includes our route and things we would change."}],"questions":[{"prompt":"Which city does Sophie plan to visit?","options":["Nanjing","Suzhou","Hangzhou","Shanghai"],"correctIndex":0,"explanation":"Sophie 第一轮询问南京的旅行经历并说明计划家庭出游。","skill":"细节理解"},{"prompt":"When did Jack visit the city?","options":["Yesterday","This week","Last winter","Last spring"],"correctIndex":3,"explanation":"Jack 说自己去年春天去过。","skill":"细节理解"},{"prompt":"Who is still away on a visit there?","options":["Jack’s father","Jack’s sister","Sophie’s cousin","Their teacher"],"correctIndex":1,"explanation":"Jack 说姐姐这周去了，目前还没有回来。","skill":"细节理解"},{"prompt":"How many nights did Jack stay?","options":["One","Three","Two","Four"],"correctIndex":2,"explanation":"Jack 明确说住了两个晚上。","skill":"细节理解"},{"prompt":"What will Jack show Sophie tomorrow?","options":["His travel notebook","His sister’s ticket","A garden painting","A new suitcase"],"correctIndex":0,"explanation":"Jack 最后答应明天给 Sophie 看旅行笔记。","skill":"细节理解"}]},"writing":{"prompt":"写80—110词，介绍一次已完成的旅行经历，或为一家人制定短途旅行计划。说明如何照顾不同兴趣和天气变化。","outline":["介绍目的地或经历：I have been to ... / We plan to ...","说明取舍：We will choose ... instead of ...","加入备用安排和期望：If ..., we can ..."],"model":"My family plans to spend a weekend in Nanjing. I have been there once, but my younger brother has never visited the city. We will choose one main activity each day instead of filling every hour. My brother wants to see a museum, while my mother enjoys drawing in quiet places. We will leave time for both interests and a relaxed lunch. If it rains, we can choose an indoor activity from our backup list. I will keep a small travel diary. I hope the journey gives us shared memories as well as photographs."},"speakingPrompts":["Which place in China would you like to explore? Why?","Have you been somewhere that another family member has not visited?","How would you plan a trip for people with different interests?"],"textbook":{"status":"edition-checked","referenceEdition":"已核 2026 春目录；版权页未取得","grammarScope":"have/has been 与 have/has gone；延续性动词与 for、since","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"8b-u3","bookId":"8b","number":3,"title":"The world at one click","theme":"网络旅行与世界见闻","goals":["比较不同时间发布的网络信息","区分一般过去时与现在完成时","说明线上参观的收获与仍需核实的问题"],"grammarKeys":["past_vs_perfect"],"vocabulary":[{"word":"online","meaning":"在线的","example":"Our class joined an online visit to a harbour town.","reviewId":0},{"word":"screen","meaning":"屏幕","example":"A live picture appeared on the classroom screen.","reviewId":1},{"word":"source","meaning":"来源","example":"Always check the source of a surprising claim.","reviewId":2},{"word":"update","meaning":"更新","example":"The museum has updated its visitor page.","reviewId":3},{"word":"recent","meaning":"最近的","example":"A recent photograph showed the repaired bridge.","reviewId":4},{"word":"guide","meaning":"导游；向导","example":"The guide answered questions from the students.","reviewId":5},{"word":"compare","meaning":"对照；比较","example":"We compared an old image with the live view.","reviewId":6},{"word":"reliable","meaning":"可靠的","example":"A clear date can help us judge how reliable a page is.","reviewId":7}],"reading":{"id":"8b-u3-reading","title":"Not Today’s Picture","level":"进阶","text":"Last Thursday, our class joined an online tour of Harbour Town, a place created for our international school project. Each partner class had designed part of the town and prepared a history for it.\n\nBefore the tour, I found a picture on the project website. It showed an unfinished bridge and a sign saying that the riverside library was closed. I wrote a question about the problem in my notebook.\n\nDuring the live session, a student guide showed us a very different view. The bridge was complete, and people were reading beside the library windows. Our partner class had updated the town model in May, but the old photograph was still in an early project folder.\n\nI asked why both pictures remained online. The guide explained that the older image was useful for showing how the design had developed. It was not wrong; it simply represented another time. We added dates and clearer labels to our own pages after the visit. The tour taught us about the town, but it also reminded us to check when information was created.","summary":"虚构城市的线上参观中，新旧图片看似矛盾；学生通过核对时间理解了资料的不同用途。","questions":[{"prompt":"What was Harbour Town?","options":["A holiday hotel","A place created for a school project","The writer’s home town","A real online shop"],"correctIndex":1,"explanation":"第一段明确说明 Harbour Town 是校际项目中设计的地点。","skill":"细节理解"},{"prompt":"What did the old picture show?","options":["A new airport","An empty classroom","An unfinished bridge","A crowded theatre"],"correctIndex":2,"explanation":"第二段说旧照片中桥尚未完工。","skill":"细节理解"},{"prompt":"When had the partner class updated its model?","options":["In May","In January","In August","In December"],"correctIndex":0,"explanation":"第三段说明对方班级在五月更新了城市模型。","skill":"细节理解"},{"prompt":"What did the writer’s class add to its pages after the visit?","options":["Ticket prices","New advertisements","Music downloads","Dates and clearer labels"],"correctIndex":3,"explanation":"最后一段写到学生给自己的页面加上日期和更清楚的标签。","skill":"细节理解"},{"prompt":"What mistaken impression might a visitor get from viewing only the old photograph?","options":["The library is currently closed and the bridge is unfinished.","The partner class has no website.","The town project is about cooking.","Every photograph was taken during the live session."],"correctIndex":0,"explanation":"旧图显示未完工的桥和关闭的图书馆，但直播状态已经变化；忽略日期就可能误当成现状。","skill":"推断资料误读"}]},"dialogue":{"title":"Checking a Museum Page","turns":[{"speaker":"Henry","text":"I found two different opening times on the museum website for our online project."},{"speaker":"Isla","text":"Did you check the dates? One page may be an old announcement."},{"speaker":"Henry","text":"You’re right. The first page was posted in 2021. The visitor page was updated yesterday and says the museum opens at nine."},{"speaker":"Isla","text":"Let’s use the visitor page and record its date. We should still check again before an actual visit."},{"speaker":"Henry","text":"I have also found a virtual gallery. Shall we explore it after school?"},{"speaker":"Isla","text":"Yes, at half past four. I’ll write down two questions that the online pictures cannot answer."}],"questions":[{"prompt":"What problem did Henry find?","options":["Two different opening times","Two missing tickets","A broken school screen","A lost photograph"],"correctIndex":0,"explanation":"Henry 发现同一网站上有两个不同的开放时间。","skill":"细节理解"},{"prompt":"In which year was the first page posted?","options":["2018","2019","2020","2021"],"correctIndex":3,"explanation":"Henry 说明第一张页面发布于2021年。","skill":"细节理解"},{"prompt":"What opening time does the updated visitor page give?","options":["Eight","Nine","Ten","Eleven"],"correctIndex":1,"explanation":"更新后的访客页面显示九点开放。","skill":"细节理解"},{"prompt":"When will they explore the virtual gallery?","options":["At three","At four","At half past four","At five"],"correctIndex":2,"explanation":"Isla 最后约定四点半探索虚拟展厅。","skill":"细节理解"},{"prompt":"What will Isla write down?","options":["Two questions the pictures cannot answer","A list of souvenir prices","The guide’s address","Three invented opening times"],"correctIndex":0,"explanation":"Isla 会记录两个仅看在线图片无法解决的问题。","skill":"细节理解"}]},"writing":{"prompt":"写80—110词，介绍一次线上参观或资料查询。说明你获取了什么、如何核对日期与来源，以及还有什么问题。","outline":["交代活动：Last ..., our class visited ... online.","描述核对过程：We compared ... / The page has ...","说明收获与局限：We learnt ..., but we still want to know ..."],"model":"Last week, our class explored an online gallery for a school project. I enjoyed being able to look closely at the pictures and read their labels. However, I found two pages with different information about one display. I checked the dates and discovered that the older page described a previous exhibition. I have added the source and date beside my project notes. The visit has given me several useful ideas, but photographs cannot answer every question. I still want to ask how the objects were chosen and how visitors experience the gallery in person."},"speakingPrompts":["What can you learn from a virtual visit?","How do you check whether an online page is current?","What might a photograph fail to tell you about a place?"],"textbook":{"status":"edition-checked","referenceEdition":"已核 2026 春目录；版权页未取得","grammarScope":"一般过去时与现在完成时的比较","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"8b-u4","bookId":"8b","number":4,"title":"A good read","theme":"阅读与读书习惯","goals":["依据人物选择与情节线索理解故事","使用疑问词加不定式讨论阅读选择","用具体理由推荐一本书或一则原创故事"],"grammarKeys":["question_infinitive","modals_obligation"],"vocabulary":[{"word":"chapter","meaning":"章节","example":"I wrote a question after each chapter.","reviewId":0},{"word":"character","meaning":"人物；角色","example":"The main character changes her mind near the end.","reviewId":1},{"word":"mystery","meaning":"谜；神秘故事","example":"The missing letter creates a small mystery.","reviewId":2},{"word":"recommend","meaning":"推荐","example":"I would recommend this story to curious readers.","reviewId":3},{"word":"borrow","meaning":"借入","example":"You can borrow the book from our reading corner.","reviewId":4},{"word":"return","meaning":"归还","example":"Please return it before the next club meeting.","reviewId":5},{"word":"ending","meaning":"结尾","example":"We discussed the ending without spoiling it for others.","reviewId":6},{"word":"clue","meaning":"线索","example":"A date on the envelope gives the reader a clue.","reviewId":7}],"reading":{"id":"8b-u4-reading","title":"The Question on Page Forty","level":"进阶","text":"Our book club was reading an original school story called The Clockmaker’s Letter. In it, two friends find an unopened envelope behind a broken clock. I wanted to reach the ending quickly, but our club leader asked us to stop after page forty.\n\nEveryone had to bring one question to the meeting. Mine was simple: who had written the letter? Priya asked a different question. Why had the main character hidden the envelope from her friend? At first, I thought this was less important than solving the mystery.\n\nAs we discussed the chapters, we found clues about the character’s fear of being wrong. Her choice affected their friendship, not just the search for the writer. I returned to an earlier scene and noticed details I had rushed past.\n\nWe finished the story the following week. I enjoyed learning the answer to my first question, but Priya’s question stayed with me longer. Now, when I choose what to read, I look for stories that make me think about people as well as events. A good discussion can change how we read.","summary":"读书会把注意力从猜谜答案转向人物动机，帮助叙述者学会更深入地阅读。","questions":[{"prompt":"Where do the friends find the envelope in the story?","options":["Under a bench","Behind a broken clock","Inside a school bag","Beside a river"],"correctIndex":1,"explanation":"第一段说明信封藏在坏掉的钟后面。","skill":"细节理解"},{"prompt":"At which page did the club stop before the meeting?","options":["Page twenty","Page thirty","Page forty","Page sixty"],"correctIndex":2,"explanation":"读书会负责人要求读到第四十页暂停。","skill":"细节理解"},{"prompt":"What did Priya ask about?","options":["Why a character hid the envelope from her friend","The price of the clock","The number of pages","Where the book was printed"],"correctIndex":0,"explanation":"Priya 关注人物为何向朋友隐瞒信封。","skill":"细节理解"},{"prompt":"When did the group finish the story?","options":["That same afternoon","At the end of the term","Two months later","The following week"],"correctIndex":3,"explanation":"最后一段说明他们下一周读完故事。","skill":"细节理解"},{"prompt":"How did Priya’s question change the writer’s reading?","options":["It made endings unimportant in every story.","It encouraged attention to motives and relationships.","It made the writer stop reading mysteries.","It proved that fast reading is always wrong."],"correctIndex":1,"explanation":"叙述者重新注意到人物害怕出错及友谊的变化，可推断讨论促使其关注人物动机与关系。","skill":"推断阅读变化"}]},"dialogue":{"title":"Choosing a Club Book","turns":[{"speaker":"Nina","text":"We need to choose a short book for next month’s club. Should we read a mystery or a travel diary?"},{"speaker":"Oscar","text":"A mystery might work well. We can discuss clues without needing to know many places."},{"speaker":"Nina","text":"The school library has five copies of The Lost Parcel. It is ninety pages long."},{"speaker":"Oscar","text":"There are ten of us, so we can borrow one copy for each pair. When must we return them?"},{"speaker":"Nina","text":"Within three weeks. Let’s read thirty pages a week and bring one question to each meeting."},{"speaker":"Oscar","text":"Agreed. We should not reveal the ending before everyone has finished the last section."}],"questions":[{"prompt":"Which kind of book do they choose?","options":["A travel diary","A mystery","A cookbook","A dictionary"],"correctIndex":1,"explanation":"Oscar 建议选悬疑故事，后面两人按这一方向安排。","skill":"细节理解"},{"prompt":"How many copies does the library have?","options":["Three","Four","Five","Ten"],"correctIndex":2,"explanation":"Nina 说学校图书馆有五本。","skill":"细节理解"},{"prompt":"How many members are in the club?","options":["Ten","Five","Six","Twelve"],"correctIndex":0,"explanation":"Oscar 明确说共有十人，可以两人一本。","skill":"细节理解"},{"prompt":"How long may they keep the books?","options":["One week","Two weeks","Four weeks","Three weeks"],"correctIndex":3,"explanation":"Nina 说必须在三周内归还。","skill":"细节理解"},{"prompt":"Why should they avoid revealing the ending early?","options":["The book has no ending.","Some members may not have finished it.","They must write a new book.","The librarian dislikes mysteries."],"correctIndex":1,"explanation":"他们约定等所有人读完最后部分再谈结局，是为了照顾尚未读完的成员。","skill":"细节理解"}]},"writing":{"prompt":"写80—110词，推荐一本你读过的书，或介绍一则你自己构思的故事。给出人物、情节概况与推荐理由，避免透露关键结局。","outline":["说明推荐对象：I would like to recommend ...","概述人物与冲突：The story follows ...","解释阅读价值：It made me think about ..."],"model":"I would like to recommend an original story from our school writing club, The Missing Map. It follows two classmates who prepare a walking tour but lose their only map before the visitors arrive. They must decide whether to hide the problem or ask for help. The story is short, and the dialogue is easy to follow. I especially like the way the characters learn to trust other people. I will not reveal the ending, because readers should discover their solution themselves. This story made me think about why admitting a mistake can be a brave choice."},"speakingPrompts":["How do you decide what to read next?","Which question would you bring to a book discussion?","How can you recommend a story without revealing its ending?"],"textbook":{"status":"edition-checked","referenceEdition":"已核 2026 春目录；版权页未取得","grammarScope":"疑问词+动词不定式；must 与 have to","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"8b-u5","bookId":"8b","number":5,"title":"Good manners","theme":"礼仪与得体交往","goals":["理解礼貌行为背后对他人的尊重","使用too ... to和enough to描述情境","练习礼貌请求、倾听与轮流表达"],"grammarKeys":["too_enough"],"vocabulary":[{"word":"polite","meaning":"有礼貌的","example":"A polite question gives the speaker room to answer.","reviewId":0},{"word":"interrupt","meaning":"打断","example":"Try not to interrupt someone in the middle of a story.","reviewId":1},{"word":"permission","meaning":"允许；许可","example":"Ask permission before sharing another person’s photograph.","reviewId":2},{"word":"volume","meaning":"音量","example":"We lowered the volume during the discussion.","reviewId":3},{"word":"offer","meaning":"主动提供","example":"I offered a seat to the guest near the door.","reviewId":4},{"word":"respect","meaning":"尊重","example":"Listening carefully is one way to show respect.","reviewId":5},{"word":"turn","meaning":"轮次","example":"Everyone had a turn to introduce an object.","reviewId":6},{"word":"considerate","meaning":"体贴的","example":"A considerate host notices what guests need.","reviewId":7}],"reading":{"id":"8b-u5-reading","title":"Let the Story Finish","level":"进阶","text":"At our neighbourhood story afternoon, each guest brought an object and explained why it mattered. I volunteered to welcome people and help keep the conversation moving. I wanted to be the most helpful host in the room.\n\nOne guest, Mr Wu, placed a tiny wooden boat on the table. He spoke quietly and sometimes paused before choosing a word. I thought he was finding the task too difficult, so I began finishing his sentences. Then I told everyone about a boat trip I had taken.\n\nDuring the break, our teacher asked whether Mr Wu had actually finished his story. I realised that I had never heard why the little boat was important. After the break, I invited him to continue and waited quietly when he paused.\n\nThe boat had been made by his brother during their childhood. They lived in different cities now, but the object kept a shared memory close. Mr Wu did not need me to tell his story for him. He needed enough time to tell it himself. Being helpful sometimes means speaking less and listening more.","summary":"小主持人从替客人接话转向耐心倾听，理解礼貌帮助应给对方保留表达空间。","questions":[{"prompt":"What did guests bring to the event?","options":["A school report","An object with personal meaning","A sports ticket","A new phone"],"correctIndex":1,"explanation":"开头说每位客人带来一个物品，并解释它为何重要。","skill":"细节理解"},{"prompt":"What did Mr Wu bring?","options":["A model train","A paper plane","A small wooden boat","An old clock"],"correctIndex":2,"explanation":"第二段明确写到一只小木船。","skill":"细节理解"},{"prompt":"What mistake did the writer make at first?","options":["Finished Mr Wu’s sentences and changed the topic","Forgot to open the room","Lost the boat","Asked everyone to leave"],"correctIndex":0,"explanation":"叙述者替 Mr Wu 接话，又转而讲自己的乘船经历，打断了客人的故事。","skill":"细节理解"},{"prompt":"Who had made the little boat?","options":["Mr Wu’s teacher","The writer","A neighbour","Mr Wu’s brother"],"correctIndex":3,"explanation":"最后一段说明木船是 Mr Wu 的兄弟在他们童年时制作的。","skill":"细节理解"},{"prompt":"What would the writer most likely do if another guest paused during a future story?","options":["Immediately replace the guest’s story with a personal one.","Announce that the guest cannot speak.","Allow time before deciding whether help is needed.","End the event as soon as possible."],"correctIndex":2,"explanation":"叙述者在等待后才听到木船的意义，也认识到客人需要时间；可推断今后会先耐心等待。","skill":"推断后续行动"}]},"dialogue":{"title":"Before Taking a Photo","turns":[{"speaker":"Emma","text":"This display of student drawings looks wonderful. May I take a photo for our class newsletter?"},{"speaker":"Lucas","text":"Let’s ask Ms Lin first. Some drawings have students’ names written on the front."},{"speaker":"Emma","text":"Good point. I can photograph the whole display from a distance if she agrees."},{"speaker":"Lucas","text":"Please wait a moment. Two visitors are standing there, and the path is too narrow for everyone to pass."},{"speaker":"Emma","text":"I’ll move beside the window. We should leave enough space for other people."},{"speaker":"Lucas","text":"Thanks. After we get permission, we can take the photo without including the visitors."}],"questions":[{"prompt":"Why does Emma want a photograph?","options":["For a class newsletter","For a travel ticket","For a shop sign","For a sports notice"],"correctIndex":0,"explanation":"Emma 要把照片用于班级通讯。","skill":"细节理解"},{"prompt":"Whom will they ask first?","options":["A visitor","The head cook","Emma’s brother","Ms Lin"],"correctIndex":3,"explanation":"Lucas 建议先征得 Ms Lin 同意。","skill":"细节理解"},{"prompt":"What is written on some drawings?","options":["Ticket prices","Students’ names","Bus numbers","Shop addresses"],"correctIndex":1,"explanation":"Lucas 提到部分作品正面写有学生姓名。","skill":"细节理解"},{"prompt":"Why does Lucas ask Emma to wait?","options":["The camera has no battery.","The room is closed.","The path is too narrow while visitors are there.","The display has fallen down."],"correctIndex":2,"explanation":"两名访客站在那里，通道太窄，暂时不方便通行和拍摄。","skill":"细节理解"},{"prompt":"Where does Emma move?","options":["Beside the window","Behind the visitors","Into the next classroom","Under the display"],"correctIndex":0,"explanation":"Emma 说自己先移到窗边，为别人留出空间。","skill":"细节理解"}]},"writing":{"prompt":"写80—110词，讲述一次你学会礼貌沟通的经历，或给校园展览的学生志愿者提出建议。至少使用enough或too ... to。","outline":["交代情境：At our school exhibition, ...","说明得体做法：We should ask ... / Leave enough ...","解释理由：This helps ... feel ..."],"model":"At a school exhibition, being polite means thinking about other visitors as well as the pictures. We should keep our voices low enough for people to talk comfortably. If a path is too narrow to stand in, we should move aside before taking photographs. We also need to ask permission when a picture includes someone else’s work or personal details. When a guest is speaking, we should wait instead of finishing the story for them. Small actions like these help everyone feel welcome. A considerate visitor gives other people both physical space and time to express themselves."},"speakingPrompts":["When might it be helpful to wait before speaking?","How can you ask permission politely?","What does leaving enough space mean at a crowded event?"],"textbook":{"status":"edition-checked","referenceEdition":"已核 2026 春目录；版权页未取得","grammarScope":"enough 与 too；enough to 与 too ... to","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"8b-u6","bookId":"8b","number":6,"title":"Sunshine for all","theme":"帮助他人与志愿服务","goals":["理解志愿服务中的倾听与合作","使用It is ... for/of ... to ...表达评价","设计尊重参与者需求的服务活动"],"grammarKeys":["adjective_infinitive"],"vocabulary":[{"word":"volunteer","meaning":"志愿者；自愿服务","example":"Several students volunteered to record the stories.","reviewId":0},{"word":"accessible","meaning":"便于使用的；无障碍的","example":"Clear labels made the recordings more accessible.","reviewId":1},{"word":"feedback","meaning":"反馈","example":"We changed the file titles after receiving feedback.","reviewId":2},{"word":"participate","meaning":"参与","example":"Listeners were invited to participate in the planning.","reviewId":3},{"word":"request","meaning":"请求","example":"The team listened carefully to each request.","reviewId":4},{"word":"independent","meaning":"独立的","example":"A clear menu helps users make independent choices.","reviewId":5},{"word":"cooperate","meaning":"合作","example":"The two groups cooperated on the audio project.","reviewId":6},{"word":"community","meaning":"社区","example":"Our community centre hosts a monthly reading afternoon.","reviewId":7}],"reading":{"id":"8b-u6-reading","title":"A Voice in the Project","level":"进阶","text":"Our reading club wanted to share student stories with people who preferred listening. We volunteered to record six original stories for the community centre. I added music to every file because I thought it would make the recordings more exciting.\n\nBefore publishing them, we invited several listeners to try the project. Ming, a student who is blind, asked for clearer titles so that he could choose a story independently. Another listener said the background music made some words difficult to hear. A younger child wanted a short introduction explaining what each story was about.\n\nAt first, we felt disappointed. We had worked hard, and we hoped everyone would praise our efforts. Then Ming offered to help us test a new menu. He became part of the team rather than simply someone receiving our work.\n\nWe removed most of the music, added spoken introductions and rewrote the titles. The final collection was easier to use. It was kind of everyone to give honest feedback, and it was important for us to listen. Good volunteering begins with people’s needs, not only our own ideas.","summary":"学生录制原创故事后邀请使用者试用，通过倾听反馈和共同改进，让服务更容易使用。","questions":[{"prompt":"How many stories did the club record?","options":["Four","Six","Eight","Ten"],"correctIndex":1,"explanation":"第一段写到共录制六则原创故事。","skill":"细节理解"},{"prompt":"What did Ming request?","options":["More music","Longer stories","Clearer titles","Fewer choices"],"correctIndex":2,"explanation":"Ming 希望标题更清楚，便于自己选择故事。","skill":"细节理解"},{"prompt":"What problem did another listener mention?","options":["Music made some words hard to hear.","The centre was too far away.","The stories had no characters.","The files were all empty."],"correctIndex":0,"explanation":"另一名听众说背景音乐导致部分词句听不清。","skill":"细节理解"},{"prompt":"How did Ming help the team later?","options":["By buying new instruments","By writing every story","By choosing the winner","By testing a new menu"],"correctIndex":3,"explanation":"第三段说明 Ming 主动协助测试新菜单。","skill":"细节理解"},{"prompt":"Which action would best follow the club’s experience when making a new collection?","options":["Invite listeners to help test it before publishing.","Add more music without asking anyone.","Avoid feedback to protect students from disappointment.","Let only the student editor choose every feature."],"correctIndex":0,"explanation":"本次改进依靠使用者反馈和参与；将这一经验用于下次制作，应继续邀请听众试用。","skill":"推断经验迁移"}]},"dialogue":{"title":"Planning a Volunteer Reading Session","turns":[{"speaker":"Hugo","text":"Our reading group will visit the community centre on Saturday. There will be eight younger children."},{"speaker":"Ivy","text":"What have they asked us to prepare?"},{"speaker":"Hugo","text":"They would like a story about friendship and time to draw their favourite scene. The session lasts forty minutes."},{"speaker":"Ivy","text":"I can read the story, and you can lead the drawing activity. Should we also prepare large-print copies?"},{"speaker":"Hugo","text":"Yes. The centre has requested four copies. We should ask the children which activity they want to try first."},{"speaker":"Ivy","text":"Agreed. It is important for us to listen, not simply follow our own plan."}],"questions":[{"prompt":"When will the reading group visit?","options":["Saturday","Monday","Wednesday","Friday"],"correctIndex":0,"explanation":"Hugo 说周六去社区中心。","skill":"细节理解"},{"prompt":"How many younger children will attend?","options":["Four","Five","Six","Eight"],"correctIndex":3,"explanation":"第一轮明确有八名低龄儿童参加。","skill":"细节理解"},{"prompt":"Which topic have the children requested?","options":["Travel","Friendship","Sport","Cooking"],"correctIndex":1,"explanation":"孩子们想听关于友谊的故事。","skill":"细节理解"},{"prompt":"How long is the session?","options":["Twenty minutes","Thirty minutes","Forty minutes","One hour"],"correctIndex":2,"explanation":"Hugo 说明活动持续四十分钟。","skill":"细节理解"},{"prompt":"How many large-print copies are requested?","options":["Four","Eight","Ten","Twelve"],"correctIndex":0,"explanation":"中心要求准备四份大字版文本。","skill":"细节理解"}]},"writing":{"prompt":"写80—110词，介绍一项你想参加的志愿服务。说明服务对象提出的需求、你的任务以及如何取得反馈。","outline":["介绍活动与需求：Our group plans to ... They have asked for ...","说明分工：It is useful for us to ...","说明倾听：We will ask ... and change ... if needed."],"model":"Our group plans to help at the community reading afternoon. Before preparing the session, we will ask the centre what the children enjoy and what support would be useful. I would like to read a short story, while my partner prepares a drawing activity. It is important for us to offer choices instead of deciding everything ourselves. We can also bring clear, large-print copies if they are requested. After the session, we will ask the children which parts they liked and what they would change. Their feedback can help us plan a better visit next time."},"speakingPrompts":["What should volunteers ask before planning an activity?","Why is feedback useful even when it is critical?","How can people receiving a service also help design it?"],"textbook":{"status":"edition-checked","referenceEdition":"已核 2026 春目录；版权页未取得","grammarScope":"It is+形容词+不定式；It is+形容词+for/of+人+不定式","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"8b-u7","bookId":"8b","number":7,"title":"Charities","theme":"慈善组织与公益","goals":["理解公益物资从募集到送达的流程","使用一般现在时和一般过去时被动语态","区分募集数量与实际可用成果"],"grammarKeys":["passive_present_past"],"vocabulary":[{"word":"charity","meaning":"慈善机构；慈善事业","example":"Our teacher contacted a local charity before the collection.","reviewId":0},{"word":"donate","meaning":"捐赠","example":"Families were invited to donate clean winter coats.","reviewId":1},{"word":"sort","meaning":"分类","example":"The coats were sorted by size.","reviewId":2},{"word":"label","meaning":"标签；贴标签","example":"Each bag was labelled before delivery.","reviewId":3},{"word":"deliver","meaning":"送达","example":"The boxes were delivered on Friday morning.","reviewId":4},{"word":"condition","meaning":"状况","example":"Only clothes in good condition were accepted.","reviewId":5},{"word":"receipt","meaning":"收据；签收单","example":"The team kept a receipt from the collection centre.","reviewId":6},{"word":"request","meaning":"需求；请求","example":"We checked the centre’s request before advertising.","reviewId":7}],"reading":{"id":"8b-u7-reading","title":"Where the Coats Went","level":"进阶","text":"Our school held a winter coat collection for a fictional community project called Warm Welcome. Before making posters, the student team asked the project organiser what was needed. Clean coats in children’s sizes were requested, but shoes and blankets were not.\n\nOn collection day, thirty-two coats were brought to the school hall. I wanted to put that number on our final poster immediately. However, our teacher reminded us that collecting items was only the first step.\n\nThe coats were checked and sorted by a team of adults and students. Five were unsuitable for the request, so the families who had brought them were contacted. The remaining twenty-seven were labelled by size and packed in clearly marked bags. On Friday, they were delivered to the collection centre, and a receipt was given to our teacher.\n\nOur final report explained both numbers instead of hiding the difference. We also thanked the people who checked, packed and transported the coats. I had once thought a collection was mainly about how many things arrived. Now I understand that useful support includes listening, careful organisation and knowing what actually reached the project.","summary":"一次虚构的冬衣募集展示了需求确认、检查分类、送达与如实报告的重要性。","questions":[{"prompt":"What items were requested?","options":["Shoes in every size","Clean children’s coats","Blankets and pillows","School uniforms only"],"correctIndex":1,"explanation":"项目需要干净的儿童尺码外套，不需要鞋和毯子。","skill":"细节理解"},{"prompt":"How many coats were first brought to school?","options":["Twenty-seven","Thirty","Thirty-two","Thirty-five"],"correctIndex":2,"explanation":"第二段写到学校最初收到三十二件。","skill":"细节理解"},{"prompt":"Why were the families who brought five coats contacted?","options":["Those coats did not suit the request.","Every coat had been lost.","The collection was cancelled.","The school needed their addresses for a poster."],"correctIndex":0,"explanation":"有五件不符合此次需求，因此联系了提供这些衣物的家庭。","skill":"细节理解"},{"prompt":"How many coats were delivered to the centre?","options":["Five","Twenty","Thirty-two","Twenty-seven"],"correctIndex":3,"explanation":"符合需求的二十七件经过分类和装袋后被送达。","skill":"细节理解"},{"prompt":"Before organising another collection, what would the writer most likely do?","options":["Advertise for every type of item immediately.","Check the organiser’s needs and plan how items will be checked.","Promise that every donated item will be accepted.","Decide that counting delivered items is unnecessary."],"correctIndex":1,"explanation":"此次有五件不适合需求，叙述者又认识到组织与送达的重要性，可推断会先确认需求及检查流程。","skill":"推断后续行动"}]},"dialogue":{"title":"After the Book Collection","turns":[{"speaker":"Mason","text":"Our book collection has finished. How many books were delivered to the reading centre?"},{"speaker":"Alice","text":"Forty-eight. We received fifty-two, but four damaged books were returned to their owners."},{"speaker":"Mason","text":"Were the books packed by topic?"},{"speaker":"Alice","text":"Yes. Storybooks were put in blue boxes, and information books were put in green ones. Each box was labelled."},{"speaker":"Mason","text":"Who delivered them?"},{"speaker":"Alice","text":"Two parent volunteers delivered them on Tuesday. The centre confirmed the number, and we will share a short report with the class."}],"questions":[{"prompt":"How many books were delivered?","options":["Forty-eight","Fifty-two","Forty","Four"],"correctIndex":0,"explanation":"Alice 第一条回答说明送达四十八本。","skill":"细节理解"},{"prompt":"Why were four books returned?","options":["They were too short.","They had no pictures.","They were in English.","They were damaged."],"correctIndex":3,"explanation":"四本书因为损坏而退还给原主人。","skill":"细节理解"},{"prompt":"Which colour boxes held storybooks?","options":["Green","Blue","White","Yellow"],"correctIndex":1,"explanation":"Alice 说故事书放在蓝色箱子中。","skill":"细节理解"},{"prompt":"Who delivered the books?","options":["Two teachers","Three classmates","Two parent volunteers","The librarian alone"],"correctIndex":2,"explanation":"最后一轮说明由两位家长志愿者送书。","skill":"细节理解"},{"prompt":"On which day were the books delivered?","options":["Tuesday","Monday","Thursday","Saturday"],"correctIndex":0,"explanation":"Alice 明确说书在周二送达。","skill":"细节理解"}]},"writing":{"prompt":"写80—110词，描述一次真实或虚构的校内公益募集活动。说明需求、物品处理流程和结果，至少使用两个被动语态句子。","outline":["说明活动前的需求确认：The centre was asked ...","叙述处理步骤：The items were checked/sorted/labelled ...","报告实际结果：... were delivered. We learnt ..."],"model":"Our class organised a book collection for a fictional community project. Before the event, the organiser was asked which books would be useful. Families were then invited to bring suitable books in good condition. Each book was checked, and the accepted books were sorted by topic. Clear labels were attached to the boxes before they were delivered by adult volunteers. Our final report recorded how many books were received and how many were actually accepted. I learnt that a collection needs more than enthusiasm. Careful preparation and an honest record help turn donated items into useful support."},"speakingPrompts":["Why should a collection begin with a clear request?","Can you describe a donation process using the passive voice?","Why might the number collected differ from the number delivered?"],"textbook":{"status":"edition-checked","referenceEdition":"已核 2026 春目录；版权页未取得","grammarScope":"一般现在时和一般过去时的被动语态","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"8b-u8","bookId":"8b","number":8,"title":"A green world","theme":"绿色生活与环境保护","goals":["理解绿色活动方案中的任务与反馈","使用一般将来时被动语态说明安排","提出可记录、可检查的环保行动"],"grammarKeys":["passive_future"],"vocabulary":[{"word":"reusable","meaning":"可重复使用的","example":"Reusable cups will be provided at the event.","reviewId":0},{"word":"reduce","meaning":"减少","example":"We want to reduce the number of cups thrown away.","reviewId":1},{"word":"return point","meaning":"归还点","example":"A clear sign will mark the return point.","reviewId":2},{"word":"separate","meaning":"分开","example":"Used cups will be kept separate from clean ones.","reviewId":3},{"word":"wash","meaning":"清洗","example":"The cups will be washed by the kitchen team.","reviewId":4},{"word":"trial","meaning":"试行","example":"A small trial helped us improve the plan.","reviewId":5},{"word":"reminder","meaning":"提醒","example":"A reminder will be displayed near the exit.","reviewId":6},{"word":"result","meaning":"结果","example":"We will record the result after the open day.","reviewId":7}],"reading":{"id":"8b-u8-reading","title":"The Cup Library","level":"进阶","text":"Our school is preparing an open day, and the environment club has proposed a cup library. Visitors will borrow reusable cups instead of taking a new paper cup each time they have a drink. The cups will be supplied and washed by the school kitchen team.\n\nBefore the event, we tested the idea with one class. Forty clean cups were placed on a table. A return tray stood near the door, but several students left their cups beside their chairs. The tray was easy to reach, yet its small label was difficult to notice.\n\nWe changed the plan. A larger sign will be displayed above the return point, and a student volunteer will explain the system when visitors arrive. Used cups will be kept separate from clean ones. After the event, the cups will be counted and the club will record how many were returned.\n\nWe cannot judge the whole project from one small trial. However, it has already shown us an important detail: a good environmental idea must also be easy for people to follow. We will collect feedback before deciding whether to use the system again.","summary":"环保社团试行可重复使用杯子的借还制度，通过改善标识和记录归还情况评估方案。","questions":[{"prompt":"What is the main idea of the cup library?","options":["Visitors buy a new cup each time.","Visitors borrow reusable cups.","Students collect old bottles.","The school closes its kitchen."],"correctIndex":1,"explanation":"第一段说明访客借用可重复使用的杯子，代替每次拿新纸杯。","skill":"细节理解"},{"prompt":"How many clean cups were used in the trial?","options":["Twenty","Thirty","Forty","Fifty"],"correctIndex":2,"explanation":"试行时桌上放了四十个干净杯子。","skill":"细节理解"},{"prompt":"What problem did the trial reveal?","options":["The small return label was hard to notice.","The cups were too heavy for the table.","The door could not open.","Nobody wanted a drink."],"correctIndex":0,"explanation":"托盘容易接近，但归还标签太小、不醒目，导致一些同学把杯子留在座位旁。","skill":"细节理解"},{"prompt":"Who will wash the cups?","options":["Every visitor alone","The environment club’s youngest member","A visiting photographer","The school kitchen team"],"correctIndex":3,"explanation":"第一段明确由学校厨房团队提供并清洗杯子。","skill":"细节理解"},{"prompt":"If many visitors still left cups beside their chairs, what would the club most likely do next?","options":["Call the first plan a complete success anyway.","Stop collecting feedback.","Hide the return count from every member.","Review the signs and instructions using the new feedback."],"correctIndex":3,"explanation":"首次试行后社团已根据标签不醒目的问题修改计划，并准备继续收集反馈，遇到同类问题时很可能再检查指示设计。","skill":"推断后续行动"}]},"dialogue":{"title":"A Greener Class Fair","turns":[{"speaker":"Daisy","text":"Our class fair is on Friday. How will we reduce waste at the snack table?"},{"speaker":"Ethan","text":"Reusable plates will be borrowed from the school kitchen. We will need thirty plates."},{"speaker":"Daisy","text":"Where should visitors return them?"},{"speaker":"Ethan","text":"A return point will be set up beside the window. A large green sign will be placed above it."},{"speaker":"Daisy","text":"I’ll explain the plan at the beginning. Will the plates be washed by the kitchen team?"},{"speaker":"Ethan","text":"Yes. After the fair, returned plates will be counted, and we will ask visitors whether the signs were clear."}],"questions":[{"prompt":"When is the class fair?","options":["Friday","Tuesday","Wednesday","Sunday"],"correctIndex":0,"explanation":"Daisy 说班级义卖活动在周五。","skill":"细节理解"},{"prompt":"How many plates will be needed?","options":["Ten","Twenty","Forty","Thirty"],"correctIndex":3,"explanation":"Ethan 明确说需要三十个盘子。","skill":"细节理解"},{"prompt":"Where will the return point be?","options":["Beside the stage","Beside the window","Outside the gate","Under the stairs"],"correctIndex":1,"explanation":"归还点将设在窗边。","skill":"细节理解"},{"prompt":"What colour will the large sign be?","options":["Red","Blue","Green","Yellow"],"correctIndex":2,"explanation":"Ethan 说归还点上方会放一个大绿色标志。","skill":"细节理解"},{"prompt":"What will visitors be asked after the fair?","options":["Whether the signs were clear","Which plate was most expensive","How much homework they have","Whether the windows should be painted"],"correctIndex":0,"explanation":"最后一轮说明会询问标志是否清晰。","skill":"细节理解"}]},"writing":{"prompt":"写80—110词，介绍一项校园环保行动计划。说明分工、实施安排及如何检查结果，至少使用两个一般将来时被动语态句子。","outline":["说明行动目的：Our class wants to reduce ...","说明安排：... will be provided/collected/checked ...","说明评估方法：Afterwards, we will record ... and ask ..."],"model":"Our class wants to reduce waste at the next school fair. Reusable plates will be borrowed from the kitchen, and a clear return point will be set up beside the window. Visitors will be told how the system works before the fair begins. Used plates will be kept separate from clean ones and washed by the kitchen team. Afterwards, the returned plates will be counted. We will also ask visitors whether the signs were easy to follow. These records will help us decide what to change before the next event, rather than assuming that the first plan is perfect."},"speakingPrompts":["What simple action could reduce waste at a school event?","How will materials be collected or returned in your plan?","What information would you collect before calling the plan successful?"],"textbook":{"status":"edition-checked","referenceEdition":"已核 2026 春目录；版权页未取得","grammarScope":"一般将来时的被动语态","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"9a-u1","bookId":"9a","number":1,"title":"Know yourself","theme":"认识自我与合作","goals":["结合具体经历描述自己的长处与待改进之处。","从合作故事中识别人物的贡献，并用文本证据作出推断。","运用并列连词及成对连词表达不同特长如何相互配合。"],"grammarKeys":["conjunctions","paired_conjunctions","object_statements"],"vocabulary":[{"word":"thoughtful","meaning":"考虑周到的","example":"A thoughtful teammate asks whether everyone understands the plan.","reviewId":0},{"word":"curious","meaning":"好奇的","example":"Curious students often ask how a simple machine works.","reviewId":1},{"word":"confident","meaning":"自信的","example":"I feel more confident after practising my talk.","reviewId":2},{"word":"patient","meaning":"有耐心的","example":"Our patient coach explained the rules again.","reviewId":3},{"word":"organize","meaning":"组织；安排","example":"We need someone to organize the materials before the activity.","reviewId":4},{"word":"notice","meaning":"注意到","example":"Ke noticed that the two sides were different lengths.","reviewId":5},{"word":"strength","meaning":"长处；优势","example":"Listening carefully is one of her strengths.","reviewId":6},{"word":"cooperate","meaning":"合作","example":"The four students learned to cooperate during the project.","reviewId":7}],"reading":{"id":"9a-u1-reading","title":"A Bridge Built by Different Strengths","level":"进阶","text":"For the school activity fair, each team had to build a cardboard bridge that could hold ten books. Noah quickly became his team's leader because he enjoyed speaking. He gave everyone a job before asking what they liked doing. Fei said little and drew small shapes in her notebook. Ke kept checking the ruler.\n\nTheir first bridge fell over. Noah wanted to add more tape, but their teacher asked a different question: “What has each person noticed?” Fei showed a drawing of folded cardboard legs. Ke explained that the two sides of the bridge were different lengths. Lin, who had tested the bridge, pointed to its weakest part.\n\nThis time, they discussed their strengths before choosing jobs. Fei designed the shape, Ke measured the pieces, and Lin tested each change. Noah organized the materials and made sure every idea was heard. He discovered that leading meant listening as well as speaking.\n\nTheir final bridge held twelve books. It did not win the prize for the strongest bridge, yet the team felt proud. Fei was still quiet, but nobody thought she had nothing to say. They also agreed to try different jobs next time. Knowing a strength, they decided, should open a door rather than lock a person into one role.","summary":"四名学生第一次造桥失败后，开始倾听彼此的观察，并按当时的长处分工。桥最终承住十二本书，他们也认识到特长可以帮助合作，但不应把人固定在一种角色里。","questions":[{"prompt":"What was the basic requirement for the bridge?","options":["It had to be built by one student.","It had to use only one sheet of paper.","It had to be taller than a desk.","It had to hold ten books."],"correctIndex":3,"explanation":"开头说明桥必须能承住 ten books；十二本是他们最终达到的结果。","skill":"细节定位"},{"prompt":"What did Ke notice about the first bridge?","options":["The books were too small.","Its two sides were different lengths.","The team had lost all its tape.","It had too many folded legs."],"correctIndex":1,"explanation":"第二段明确写出 Ke explained that the two sides ... were different lengths。","skill":"原因线索"},{"prompt":"Which description of the new roles is correct?","options":["Fei designed the shape, and Noah organized the materials.","Lin drew the shape, and Fei collected the books.","Fei tested each change, and Lin measured the pieces.","Ke led every discussion, and Noah worked alone."],"correctIndex":0,"explanation":"第三段分别说明 Fei designed the shape 和 Noah organized the materials。","skill":"信息对应"},{"prompt":"What can we infer about Fei?","options":["She refuses to work with other people.","She knows nothing about building things.","She can contribute useful ideas even when she speaks little.","She wants to stop trying new jobs."],"correctIndex":2,"explanation":"Fei 开始话少，但后来展示了有用的折叠桥腿设计；结尾也说明大家不再把安静当作没有想法。","skill":"有证据的推断"},{"prompt":"What is the main message of the story?","options":["Each person should keep the same job forever.","Winning a prize is the only sign of success.","The loudest person should make every decision.","Good teamwork values different strengths and keeps room for growth."],"correctIndex":3,"explanation":"团队从单方面派任务转向倾听和协作，结尾又约定下次尝试不同工作，支持重视不同优势并保留成长空间这一主旨。","skill":"主旨概括"}]},"dialogue":{"title":"Planning a Class Newsletter","turns":[{"speaker":"Lina","text":"Our class newsletter needs both short interviews and drawings. Which part would you like to do?"},{"speaker":"Noah","text":"I enjoy asking people questions, but page design is difficult for me."},{"speaker":"Lina","text":"I like drawing. I am less confident about talking to people I do not know well."},{"speaker":"Noah","text":"Then I can interview the school cook, and you can sketch the kitchen. We can plan the questions together."},{"speaker":"Lina","text":"Could I ask one question during the interview too? I would like to practise, rather than always stay behind my notebook."},{"speaker":"Noah","text":"Of course. Let us rehearse first, and next month you can lead a short interview if you feel ready."}],"questions":[{"prompt":"What are Lina and Noah planning?","options":["A school concert.","A class newsletter.","A cooking competition.","A bridge exhibition."],"correctIndex":1,"explanation":"第一轮对话直接提到 our class newsletter。","skill":"对话主题"},{"prompt":"Which part does Noah find difficult?","options":["Page design.","Drawing a map to school.","Asking questions.","Reading a menu."],"correctIndex":0,"explanation":"Noah 在第二轮说 page design is difficult for me。","skill":"人物信息"},{"prompt":"Who will they interview?","options":["A young artist.","A bus driver.","The school cook.","The head teacher."],"correctIndex":2,"explanation":"Noah 提出 interview the school cook，Lina 可画厨房。","skill":"细节定位"},{"prompt":"Why does Lina want to ask one question?","options":["She has already finished every interview.","She wants to practise talking during an interview.","She wants to cancel the drawings.","She wants Noah to leave the team."],"correctIndex":1,"explanation":"Lina 明确说 I would like to practise，并表示不想总躲在笔记本后面。","skill":"意图理解"},{"prompt":"What does Noah suggest they do before the interview?","options":["Rehearse together.","Work without a plan.","Choose a new cook.","Print the newsletter immediately."],"correctIndex":0,"explanation":"最后一轮明确提出 Let us rehearse first。","skill":"计划顺序"}]},"writing":{"prompt":"写一篇 100—130 词的短文，介绍一次合作经历：成员有哪些不同长处，遇到问题后怎样调整，你对自己有了什么新认识。至少使用一次 both ... and ... 或 not only ... but also ...。","outline":["交代任务、伙伴和最初的分工。","写出一个具体问题及成员如何配合解决。","总结你发现的长处，并说明下一步想尝试的角色。"],"model":"Last month, our group prepared a photo corner for the school festival. I enjoy taking pictures, so I first wanted to do that job alone. However, I soon found that I could not welcome visitors and use the camera at the same time. We changed our plan. Mei welcomed people, Jin checked the light, and I took the photos. We not only finished on time but also helped shy visitors feel comfortable. I learned that asking for help does not make me less capable. Both careful preparation and friendly communication matter. At our next event, I want to practise welcoming visitors while another student tries the camera."},"speakingPrompts":["What is one strength you can support with a real example?","How can a quiet teammate share an idea during a group task?","Which new role would you like to try, and why?"],"textbook":{"status":"resource-crosschecked","referenceEdition":"2026 新版公开教学资源交叉核对","grammarScope":"并列连词；that 引导的宾语从句","unitStartPage":null,"grammarPages":[],"sections":[]},"grammarNote":"依据公开配套资料整理的语法复习；新版教材对应页尚未逐页核验，请与实书对照。"},{"id":"9a-u2","bookId":"9a","number":2,"title":"Teenage problems","theme":"沟通与烦恼","goals":["描述学习和同伴沟通中的具体烦恼，区分事实与猜测。","根据阅读和对话中的线索分析误会产生及解决的过程。","使用疑问句作宾语从句，礼貌询问信息并寻求支持。"],"grammarKeys":["object_questions"],"vocabulary":[{"word":"pressure","meaning":"压力","example":"A clear plan can help me manage the pressure of a busy week.","reviewId":0},{"word":"misunderstanding","meaning":"误会","example":"One short message caused a misunderstanding between the partners.","reviewId":1},{"word":"reply","meaning":"回复","example":"I waited until lunch to read her reply.","reviewId":2},{"word":"hesitate","meaning":"犹豫","example":"Do not hesitate to ask what the instructions mean.","reviewId":3},{"word":"explain","meaning":"解释","example":"Omar wanted to explain why his message was so short.","reviewId":4},{"word":"reasonable","meaning":"合理的","example":"We agreed on a reasonable time to finish the poster.","reviewId":5},{"word":"support","meaning":"支持","example":"My friend offered support without doing the task for me.","reviewId":6},{"word":"solution","meaning":"解决办法","example":"They found a solution after listening to each other.","reviewId":7}],"reading":{"id":"9a-u2-reading","title":"A Short Message, a Long Worry","level":"进阶","text":"On Monday evening, Nia sent Omar a draft of their science poster. His reply was just one word: “Fine.” There was no comment about her drawings. When he did not answer her next message, she began to wonder whether he cared about the project at all.\n\nNia wrote a long message saying that she would finish everything herself. However, she did not send it. Her older sister asked, “What do you know, and what are you guessing?” Nia knew that the reply was short. She did not actually know why.\n\nAt school the next morning, she asked Omar whether they could talk. “I felt unsure when I read your message,” she said. “Could you tell me which parts you liked and what we still need to change?” Omar looked surprised. He had been helping his father in their shop. He sent a quick reply before his phone battery died. He liked the drawings, but wanted to check the labels together.\n\nThey spent ten minutes making a list of changes. They also agreed to say when they could give a full reply. Nia kept her unsent message for a day, then deleted it. She had learned that a question could reveal information that a worried guess could not.","summary":"Nia 因搭档回复过短而担心对方不重视项目。在发送责备信息前，她先停下来区分事实与猜测，随后当面询问，发现回复简短另有原因，并与搭档约定更清楚的沟通方式。","questions":[{"prompt":"Why did Nia begin to worry?","options":["Their teacher cancelled the project.","Omar said her drawings were terrible.","Her sister refused to look at the poster.","Omar gave a very short reply and did not answer again."],"correctIndex":3,"explanation":"第一段说明 Omar 只回复 Fine，之后没有再答；文中并没有直接批评画作。","skill":"事件起因"},{"prompt":"What did Nia do with her first long message?","options":["She asked her teacher to publish it.","She sent it to the whole class.","She saved it without sending it.","She immediately replaced the poster with it."],"correctIndex":2,"explanation":"第二段写她虽然写了长信息，however, she did not send it。","skill":"细节定位"},{"prompt":"Why was Omar unable to keep replying that evening?","options":["He did not know Nia had sent a poster.","He had decided to leave the group.","He had already finished a different poster alone.","His phone battery died while he was helping in the shop."],"correctIndex":3,"explanation":"Omar 解释自己在帮父亲看店，发完简短回复后手机没电。","skill":"原因理解"},{"prompt":"What can we infer about Nia’s decision to wait before sending her message?","options":["It gave her a chance to learn the facts before blaming Omar.","It made the science poster unnecessary.","It proved that Omar disliked the project.","It meant she never wanted to speak to Omar again."],"correctIndex":0,"explanation":"她先未发送责备信息，次日通过提问了解真实情况并合作修改，可推知等待让她避免在信息不足时责怪对方。","skill":"有证据的推断"},{"prompt":"Which title best expresses the lesson Nia learned?","options":["Finish Every Task Alone","Ask Before You Assume","A Drawing Is Better Than Any Message","Never Reply to a Classmate"],"correctIndex":1,"explanation":"结尾强调提问能带来担忧猜测无法提供的信息，支持先询问再判断。","skill":"主旨概括"}]},"dialogue":{"title":"Finding the Missing Instruction","turns":[{"speaker":"Lara","text":"I am worried about the history poster. I have spent an hour choosing pictures, and I still do not know how much to include."},{"speaker":"Jun","text":"Do you know how many pictures the teacher expects? Let us check the task sheet together."},{"speaker":"Lara","text":"I read the title and the deadline, but I may have missed the details below them."},{"speaker":"Jun","text":"Here it is: choose two pictures and write three sentences about each. You already have two good pictures."},{"speaker":"Lara","text":"That makes the task much clearer. I can stop collecting pictures and finish the captions now."},{"speaker":"Jun","text":"Yes. If anything is still unclear, you can ask the teacher. Then make a short list of the steps that remain."}],"questions":[{"prompt":"What is Lara worried about?","options":["How to reach the museum.","Which sports club to join.","How much content to put on her history poster.","Where to buy a new phone."],"correctIndex":2,"explanation":"Lara 第一轮说不知道海报应包含多少内容。","skill":"烦恼定位"},{"prompt":"What does Jun suggest checking first?","options":["A weather report.","A bus timetable.","The school menu.","The task sheet."],"correctIndex":3,"explanation":"Jun 提议 Let us check the task sheet together。","skill":"建议识别"},{"prompt":"How many pictures are required?","options":["Two.","Six.","Four.","Three."],"correctIndex":0,"explanation":"第四轮明确写 choose two pictures；three 是每张图需要的句子数。","skill":"数字信息辨析"},{"prompt":"What will Lara do next?","options":["Keep collecting pictures all evening.","Remove every picture from the poster.","Finish the captions for the chosen pictures.","Ask Jun to complete the whole task."],"correctIndex":2,"explanation":"Lara 在第五轮说 stop collecting pictures and finish the captions now。","skill":"后续行动"},{"prompt":"What helped reduce Lara’s uncertainty?","options":["Finding a longer title.","Reading the detailed instructions she had missed.","Avoiding all questions about the task.","Changing the project deadline."],"correctIndex":1,"explanation":"她遗漏的具体要求明确了图片和句子数量，使任务变清楚。","skill":"信息整合"}]},"writing":{"prompt":"写一篇 100—130 词的短文，讲述一次因信息不清而产生的学习或沟通烦恼。说明你如何礼貌询问、得到什么信息，以及事情怎样改善。至少使用两处疑问句作宾语从句。","outline":["交代烦恼，并写出你当时知道和不知道的内容。","描述你向谁提问以及得到的具体解释。","说明采取的行动和以后会使用的沟通方法。"],"model":"Last week, I felt worried about our group presentation. I did not know whether I should prepare the pictures or write the opening. Instead of guessing, I asked our group leader what each person needed to do. She explained that I was responsible for the pictures and that Ben would write the opening. We put the jobs in a shared list and added a clear deadline. I finished my part without doing the same work as someone else. This experience taught me to describe a problem clearly and ask for information. Next time I feel unsure, I will check the instructions and talk to the people involved."},"speakingPrompts":["What is one question you could ask when a task feels unclear?","How can you describe a worry without blaming another person?","What might a short message mean besides “I do not care”?"],"textbook":{"status":"resource-crosschecked","referenceEdition":"2026 新版公开教学资源交叉核对","grammarScope":"if、whether及疑问词引导的宾语从句","unitStartPage":null,"grammarPages":[],"sections":[]},"grammarNote":"依据公开配套资料整理的语法复习；新版教材对应页尚未逐页核验，请与实书对照。"},{"id":"9a-u3","bookId":"9a","number":3,"title":"Never give up","theme":"努力与成长","goals":["描述遇到挫折后调整方法并继续尝试的过程。","依据行动变化判断人物怎样理解进步。","使用 when、before、after、until 等连接学习经历中的事件。"],"grammarKeys":["adverbial_time"],"vocabulary":[{"word":"effort","meaning":"努力","example":"Her effort became more focused after she made a plan.","reviewId":0},{"word":"progress","meaning":"进步","example":"A small change in the practice log showed real progress.","reviewId":1},{"word":"challenge","meaning":"挑战","example":"Playing against a stronger team was a useful challenge.","reviewId":2},{"word":"record","meaning":"记录","example":"I record one mistake after each practice game.","reviewId":3},{"word":"strategy","meaning":"策略；方法","example":"Changing the strategy helped him use his practice time better.","reviewId":4},{"word":"improve","meaning":"改善；提高","example":"I want to improve the way I check my answers.","reviewId":5},{"word":"review","meaning":"回顾；复习","example":"We review difficult moves before the next match.","reviewId":6},{"word":"encourage","meaning":"鼓励","example":"My partner encouraged me to try another approach.","reviewId":7}],"reading":{"id":"9a-u3-reading","title":"The Practice Log","level":"进阶","text":"After losing his first four games at the school chess club, Arun decided that he simply needed to play more. For a week, he played every lunchtime. Yet he kept making the same kind of mistake: he planned his own next move without checking what his opponent might do.\n\nBefore Arun left the club one afternoon, Ms Gao gave him a small notebook. She asked him to answer three questions after each game: Which move did I rush? What warning did I miss? What could I try next time? Arun expected a book of clever moves, so the empty pages disappointed him.\n\nHowever, he began keeping the log. When he noticed the same mistake twice, he stopped and reviewed that position with a partner. He also waited a few seconds before touching a piece. After two weeks, his notes became more detailed, and the same mistakes appeared less often.\n\nIn his next friendly match, Arun played a younger student. Neither player won; the game ended in a draw. Arun was smiling when he put the pieces away. He had noticed a threat that he would once have missed. “I still want to win,” he wrote that evening, “but now I know what I am working on before the next game.”","summary":"Arun 连续输棋后曾以为只要多下就会进步。老师让他记录和回顾失误，他逐渐学会观察对手、检查自己的决定，并开始用具体改进而非单一输赢评价成长。","questions":[{"prompt":"What mistake did Arun often make at first?","options":["He refused to play at lunchtime.","He always stopped before making any move.","He forgot to bring a chessboard every day.","He ignored what his opponent might do."],"correctIndex":3,"explanation":"第一段说明他只计划自己的下一步，没有检查对手可能怎样走。","skill":"问题识别"},{"prompt":"What did Ms Gao give Arun?","options":["A prize for winning four games.","An empty notebook for reviewing games.","A new set of chess pieces.","A book full of clever moves."],"correctIndex":1,"explanation":"老师给的是 small notebook，并让他赛后回答三个问题；他原本期待的是招法书。","skill":"事实与期待区分"},{"prompt":"What did Arun do when the same mistake appeared twice?","options":["He replaced every piece on the board.","He stopped attending the club.","He reviewed the position with a partner.","He asked the opponent to lose."],"correctIndex":2,"explanation":"第三段明确写他发现重复错误后，与搭档回顾那个局面。","skill":"行动细节"},{"prompt":"What does Arun’s smile suggest about how he now judges progress?","options":["He can value a specific improvement even without a win.","He believes every draw is better than any win.","He expects his mistakes to disappear without practice.","He has given up the wish to improve."],"correctIndex":0,"explanation":"Arun 在和棋后仍微笑，因为他发现了以前会漏看的威胁；可推知他开始认可具体改进，不只看输赢。","skill":"有证据的推断"},{"prompt":"Which statement best describes Arun’s change?","options":["He learned that keeping notes guarantees a win.","He stopped caring about any future improvement.","He moved from practising more to practising with clear reflection.","He decided that younger players cannot be strong opponents."],"correctIndex":2,"explanation":"他最初只是增加对局，后来记录、复盘和改进决策，体现练习方法的变化。","skill":"人物成长概括"}]},"dialogue":{"title":"Practising Three Sentences at a Time","turns":[{"speaker":"Ella","text":"I lost my place during yesterday’s practice talk. I wanted to put the script away and stop trying."},{"speaker":"Jin","text":"What happened just before you lost your place?"},{"speaker":"Ella","text":"I rushed through a long paragraph. When I looked at the audience again, I could not find the next line."},{"speaker":"Jin","text":"Let us mark short sections. Practise three sentences at a time, and pause before you begin the next section."},{"speaker":"Ella","text":"I will try that tonight. After I can explain each section clearly, I will practise the whole talk."},{"speaker":"Jin","text":"Good. I can listen on Thursday. You can tell me which part still needs work before Friday’s class presentation."}],"questions":[{"prompt":"What went wrong during Ella’s practice talk?","options":["She forgot the topic completely before starting.","She lost her place in the script.","She spoke to an empty classroom.","She arrived on the wrong day."],"correctIndex":1,"explanation":"Ella 开头直接说 I lost my place。","skill":"对话问题"},{"prompt":"What happened before Ella lost her place?","options":["She rushed through a long paragraph.","She asked the audience to leave.","She practised three short sentences slowly.","She marked several short sections."],"correctIndex":0,"explanation":"第三轮明确说先匆忙讲完一大段，再看观众时找不到下一行。","skill":"事件顺序"},{"prompt":"What does Jin suggest?","options":["Giving up the class presentation.","Changing the topic immediately.","Reading every sentence faster.","Practising short sections and adding pauses."],"correctIndex":3,"explanation":"Jin 建议划分小段、一次练三句，并在下一段前停顿。","skill":"建议理解"},{"prompt":"When will Ella practise the whole talk?","options":["After she can explain each section clearly.","Before she reads any section.","Only after Friday’s presentation.","While Jin is writing a new script for her."],"correctIndex":0,"explanation":"Ella 说 After I can explain each section clearly, I will practise the whole talk。","skill":"时间关系"},{"prompt":"What will Jin do on Thursday?","options":["Give the presentation instead of Ella.","Cancel the lesson.","Listen to Ella’s practice.","Write every sentence for Ella."],"correctIndex":2,"explanation":"最后一轮 Jin 说 I can listen on Thursday。","skill":"计划细节"}]},"writing":{"prompt":"写一篇 100—130 词的成长短文，描述你学习一项技能时的一次困难。重点说明你怎样改变练习方法，并用具体表现说明进步。使用至少两种时间连接表达。","outline":["说明学习的技能和最初遇到的困难。","按时间顺序介绍一次方法调整及练习过程。","写出可观察的进步和下一步目标。"],"model":"I used to stop whenever I met an unfamiliar word in an English story. Reading one page took a long time, and I often gave up. My teacher suggested a different plan. Before I read, I look at the title and pictures. While I read, I mark difficult words but continue to the end of a short section. After that, I check the words that matter most. Last week, I finished a whole story and explained its main idea to a friend. I still need help with some expressions, but I can see my progress. Next month, I want to read a longer story with the same method."},"speakingPrompts":["What is a sign of progress besides winning or getting a high score?","Describe a time when changing your method helped more than spending extra time.","What would you write in a short practice log?"],"textbook":{"status":"resource-crosschecked","referenceEdition":"2026 新版公开教学资源交叉核对","grammarScope":"时间状语从句及其连词","unitStartPage":null,"grammarPages":[],"sections":[]},"grammarNote":"依据公开配套资料整理的语法复习；新版教材对应页尚未逐页核验，请与实书对照。"},{"id":"9a-u4","bookId":"9a","number":4,"title":"Life is beautiful","theme":"观察生命与欣赏美","goals":["用具体细节描述日常环境和生活中的美。","结合人物观察与感受的变化解释文章主题。","根据意义使用 -ing/-ed 形容词及分词修饰表达。"],"grammarKeys":["verb_ing_ed","gerunds"],"vocabulary":[{"word":"observe","meaning":"观察","example":"We stopped to observe the shapes of the fallen leaves.","reviewId":0},{"word":"detail","meaning":"细节","example":"The tiny detail made her drawing more interesting.","reviewId":1},{"word":"ordinary","meaning":"普通的；平常的","example":"An ordinary courtyard became the subject of our art lesson.","reviewId":2},{"word":"pattern","meaning":"图案；有规律的形态","example":"She copied the pattern on a dry leaf.","reviewId":3},{"word":"delicate","meaning":"精巧的；纤细的","example":"The artist drew the delicate lines with a thin pencil.","reviewId":4},{"word":"amazed","meaning":"惊讶的","example":"I was amazed by the colours in the old stone wall.","reviewId":5},{"word":"appreciate","meaning":"欣赏；感激","example":"The activity helped us appreciate familiar places.","reviewId":6},{"word":"renew","meaning":"重新激起；更新","example":"The walk helped renew my interest in drawing.","reviewId":7}],"reading":{"id":"9a-u4-reading","title":"Fifteen Minutes in a Familiar Courtyard","level":"进阶","text":"When Ms Lu announced an outdoor art lesson, Jun imagined a trip to a famous garden. Instead, she led the class into the small courtyard behind their classroom. Each student received an empty cardboard frame. They would look through it for fifteen minutes without using a phone.\n\nJun felt disappointed. He crossed this courtyard every day and thought there was nothing interesting to see. At first, he framed the whole space: a wall, a tree and an old bench. Then he moved closer to the wall. A small green plant was growing through a crack. Its fresh leaves stood out against the rough grey surface.\n\nNear the bench, Jun noticed several fallen leaves with delicate patterns. He also watched the school caretaker paint a damaged corner of the bench. The repaired wood was not perfectly smooth, but the careful work changed how Jun saw it. The bench showed that someone wanted the courtyard to remain welcoming.\n\nAt the end of the lesson, students shared quick sketches. Jun had drawn the plant, a leaf and the caretaker’s paintbrush. “The courtyard did not change much in fifteen minutes,” he said. “My attention did.” He decided to take a different route through school the next day, giving himself time to notice what he usually walked past.","summary":"Jun 原本觉得熟悉的小院没有看点，在短暂的观察中却发现裂缝中的植物、落叶纹理和修补长椅的细致劳动。他认识到，发现美不一定需要换一个著名景点，也可以从改变注意方式开始。","questions":[{"prompt":"What did the students use during the observation activity?","options":["Phone cameras.","Empty cardboard frames.","Printed maps of a famous garden.","Large mirrors."],"correctIndex":1,"explanation":"第一段说每人得到 an empty cardboard frame，且十五分钟内不使用手机。","skill":"活动细节"},{"prompt":"Where did Jun see the small green plant?","options":["Under a glass cover.","On the caretaker’s paintbrush.","Inside his schoolbag.","In a crack in the wall."],"correctIndex":3,"explanation":"第二段明确写植物 growing through a crack，与灰色墙面形成对比。","skill":"地点信息"},{"prompt":"Why did the repaired bench gain a new meaning for Jun?","options":["It had become perfectly smooth and new.","It showed that someone cared about keeping the courtyard welcoming.","It was the most expensive object at school.","It was no longer going to be used."],"correctIndex":1,"explanation":"第三段解释长椅体现有人希望小院继续让人感到亲切，修补并非完全光滑。","skill":"细节与意义联系"},{"prompt":"Which statement would Jun most likely agree with after the lesson?","options":["A place does not have to be new to offer something worth noticing.","An imperfect repair makes an object worthless.","A famous destination is necessary for every art lesson.","Only a rebuilt courtyard can become interesting."],"correctIndex":0,"explanation":"Jun 在每天经过的小院里发现此前忽略的细节，并说改变的是自己的注意方式，支持熟悉之地也值得观察这一推断。","skill":"有证据的推断"},{"prompt":"Which idea best fits the passage?","options":["Only famous gardens are worth drawing.","A good picture always requires a phone.","Careful observation can reveal beauty in familiar places.","Old objects must be perfect before people can value them."],"correctIndex":2,"explanation":"全文从觉得小院无趣到发现植物、纹理和劳动之美，支持在熟悉地方细看也能发现美。","skill":"主题理解"}]},"dialogue":{"title":"A Leaf for the Cover","turns":[{"speaker":"Ivy","text":"We need a cover for our nature notebook. This flower photo is pretty, but I would like to try a drawing."},{"speaker":"Sam","text":"What about this fallen leaf? Its edge is uneven, and the lines inside it make an interesting pattern."},{"speaker":"Ivy","text":"I nearly stepped over it without looking. I am surprised by how many colours it has."},{"speaker":"Sam","text":"We can draw the leaf that is already on the ground. There is no need to pull a fresh one from the tree."},{"speaker":"Ivy","text":"Good idea. I will use a pencil for the fine lines and add a little brown and gold later."},{"speaker":"Sam","text":"Let us write a short note under the drawing too. It can explain where we found the leaf and what caught our attention."}],"questions":[{"prompt":"What are Ivy and Sam designing?","options":["A sign for a bus stop.","A ticket for a film.","A menu for a café.","A cover for a nature notebook."],"correctIndex":3,"explanation":"第一轮直接说明需要 nature notebook 的封面。","skill":"任务定位"},{"prompt":"What attracts Sam to the leaf?","options":["Its uneven edge and the pattern of its lines.","A name printed on its surface.","A picture of a flower attached to it.","Its unusually large price tag."],"correctIndex":0,"explanation":"第二轮提到 uneven edge 和 lines inside it 形成的有趣图案。","skill":"描写细节"},{"prompt":"Which leaf will they use?","options":["A plastic leaf from a shop.","A fresh leaf they will pull from the tree.","The fallen leaf already on the ground.","A leaf hidden in the teacher’s book."],"correctIndex":2,"explanation":"Sam 第四轮明确说用地上已经落下的叶子，不必采新叶。","skill":"行动选择"},{"prompt":"How will Ivy draw the fine lines?","options":["With a thick paint roller.","By printing the flower photo over them.","By cutting the page.","With a pencil."],"correctIndex":3,"explanation":"Ivy 第五轮说 use a pencil for the fine lines。","skill":"工具信息"},{"prompt":"What will the note under the drawing explain?","options":["Why every leaf has the same colour.","Where they found the leaf and what attracted them.","How to buy a new camera.","Which student will win a competition."],"correctIndex":1,"explanation":"最后一轮说明短注要写找到叶子的地点及吸引他们注意的地方。","skill":"内容概括"}]},"writing":{"prompt":"写一篇 100—130 词的观察短文，介绍一个你曾忽略、后来发现值得欣赏的场景或物品。用至少三处具体细节说明你的发现，并恰当使用 -ing/-ed 形式。","outline":["交代观察对象以及最初印象。","描写颜色、形状、声音或人的动作等具体细节。","说明你的感受如何改变，以及这种美意味着什么。"],"model":"Yesterday, I watched my grandmother repair an old cloth bag. At first, I felt bored because I had seen the bag many times. Then I noticed her careful movements. She chose a piece of blue cloth, folded its edges and made a small pocket over the damaged part. The tiny stitches formed a neat line. I was surprised that a simple repair could change the bag so much. It was interesting to see something useful grow from patient work. The finished bag was not perfect, but it carried a story. I took a photograph of the new pocket and asked my grandmother to teach me one basic stitch."},"speakingPrompts":["What ordinary object would you like to observe more closely?","Describe a small detail that changed your impression of a place.","Can care or effort make an imperfect object beautiful? Give an example."],"textbook":{"status":"resource-crosschecked","referenceEdition":"2026 新版公开教学资源交叉核对","grammarScope":"动词 -ing 和 -ed 形式","unitStartPage":null,"grammarPages":[],"sections":[]},"grammarNote":"依据公开配套资料整理的语法复习；新版教材对应页尚未逐页核验，请与实书对照。"},{"id":"9a-u5","bookId":"9a","number":5,"title":"Music speaks","theme":"音乐与情感","goals":["用旋律、节奏和具体听觉线索描述个人感受。","比较不同听者的理解，并区分作品信息与个人联想。","运用 because、as、since 及说明原因的 for 解释选择或判断。"],"grammarKeys":["adverbial_reason"],"vocabulary":[{"word":"melody","meaning":"旋律","example":"The melody returned softly at the end of the piece.","reviewId":0},{"word":"rhythm","meaning":"节奏","example":"We tapped the rhythm gently on the table.","reviewId":1},{"word":"mood","meaning":"情绪；气氛","example":"The quiet opening created a thoughtful mood for me.","reviewId":2},{"word":"memory","meaning":"记忆；回忆","example":"The sound brought back a memory of a bus ride home.","reviewId":3},{"word":"gentle","meaning":"轻柔的","example":"A gentle piano sound accompanied the reading.","reviewId":4},{"word":"express","meaning":"表达","example":"The young composer used music to express a mixed feeling.","reviewId":5},{"word":"audience","meaning":"观众；听众","example":"The audience listened before the speaker explained the title.","reviewId":6},{"word":"perform","meaning":"表演；演奏","example":"Our group will perform a short piece at the festival.","reviewId":7}],"reading":{"id":"9a-u5-reading","title":"The Same Tune, Different Journeys","level":"进阶","text":"Pei wrote a short piano piece for the school arts evening. It began with a quick, repeating rhythm and ended with a slower version of the same melody. He called it “The Bus Ride Home” because he had imagined watching streets pass through a bus window.\n\nBefore the performance, his music teacher played a recording to a small group without giving them the title. She asked each listener to write down an image and a reason for it. One student imagined a busy station becoming quiet. Another remembered saying goodbye to a cousin. A third pictured finishing a difficult book in a peaceful room.\n\nPei was surprised. He had expected everyone to hear a bus journey. At first, he wanted to explain the “correct” picture. Then he read the listeners’ reasons. The repeated rhythm reminded one person of footsteps. The slowing ending gave another a feeling of finally being able to rest. Their ideas were different, but they had listened closely, for each could point to a sound in the piece.\n\nFor the arts evening, Pei kept his title but changed his introduction. “This piece began with my journey,” he said. “It may lead you somewhere else.” He still explained what had inspired him, since that was part of the story. However, he left space for the audience’s own memories as well.","summary":"Pei 为自己的钢琴曲设想了一段回家车程，却发现听者根据相同音乐线索产生不同联想。他保留创作背景，同时学会欣赏听者有依据的个人理解。","questions":[{"prompt":"What happens to the melody near the end of Pei’s piece?","options":["It returns in a slower form.","It is replaced by spoken directions.","It disappears before any note is played.","It becomes a completely different song by another composer."],"correctIndex":0,"explanation":"第一段说结尾是同一旋律较慢的版本。","skill":"音乐结构细节"},{"prompt":"What did the teacher withhold before the group listened?","options":["The chance to write a reason.","The name of the school.","The title of the piece.","The recording itself."],"correctIndex":2,"explanation":"第二段明确说播放录音时 without giving them the title。","skill":"活动信息"},{"prompt":"Which image did one listener connect with the music?","options":["Winning a swimming race during a storm.","Finding a lost camera on a mountain.","Building a bridge out of cardboard.","Finishing a difficult book in a peaceful room."],"correctIndex":3,"explanation":"第二段列出的第三种画面是读完一本难书后身处安静房间。","skill":"细节定位"},{"prompt":"What can we infer about the listeners’ different responses?","options":["They were copied from the title before listening.","They were based on sounds in the piece as well as personal associations.","They proved that none of the students listened carefully.","They all described events from Pei’s own life."],"correctIndex":1,"explanation":"第三段将重复节奏与脚步、慢结尾与休息联系起来，并说听者认真倾听，支持声音线索与个人联想相结合。","skill":"有证据的推断"},{"prompt":"Why did Pei change his introduction?","options":["He no longer wished to perform his piece.","He decided the audience must imagine exactly one bus.","He wanted to share his inspiration while allowing other interpretations.","He wanted to hide that he had written the music."],"correctIndex":2,"explanation":"最后一段保留标题和创作故事，同时给听众自己的记忆留空间。","skill":"人物意图"}]},"dialogue":{"title":"Music Behind a Poem","turns":[{"speaker":"Mina","text":"We need music behind the poem at the reading evening. Should we use the fast tune from our last concert?"},{"speaker":"Yao","text":"I would choose the gentler piece because it leaves more space for the reader’s words."},{"speaker":"Mina","text":"I see. Since the poem already has spoken words, perhaps we should use instruments without singing."},{"speaker":"Yao","text":"Yes. We can keep the volume low and stop for a moment at the poem’s final line."},{"speaker":"Mina","text":"Let us rehearse it in the hall. I want to know whether people at the back can hear the words clearly."},{"speaker":"Yao","text":"I will ask two classmates to listen from the last row. We can change the volume after hearing their comments."}],"questions":[{"prompt":"What will the music accompany?","options":["A cooking lesson.","A basketball match.","A science experiment.","A poem reading."],"correctIndex":3,"explanation":"第一轮说 music behind the poem at the reading evening。","skill":"情境定位"},{"prompt":"Why does Yao prefer the gentler piece?","options":["It will replace the poem entirely.","It leaves more space for the spoken words.","It is the loudest piece in the concert.","It has the largest number of singers."],"correctIndex":1,"explanation":"第二轮用 because 说明轻柔的曲子能给朗读的文字留更多空间。","skill":"原因理解"},{"prompt":"What kind of music do they plan to use?","options":["Instrumental music without singing.","Only a recording of people talking.","A tune with no instruments or sounds.","A song with several loud singers."],"correctIndex":0,"explanation":"Mina 提议 use instruments without singing，Yao 随后表示同意。","skill":"决策细节"},{"prompt":"What will happen at the poem’s final line?","options":["The reader will leave the hall.","The music will stop for a moment.","The audience will begin another song.","The volume will rise as high as possible."],"correctIndex":1,"explanation":"Yao 第四轮提出 stop for a moment at the poem’s final line。","skill":"表演安排"},{"prompt":"Why will two classmates sit in the last row?","options":["To choose the poem’s author.","To sell tickets during rehearsal.","To check whether the spoken words can be heard clearly.","To hide the instruments from the audience."],"correctIndex":2,"explanation":"Mina 想确认后排能否听清词句，Yao 因而请同学在末排听并给反馈。","skill":"信息整合"}]},"writing":{"prompt":"写一篇 100—130 词的短文，介绍一段你听过或想象中的音乐。描述至少两个听觉细节、它带给你的个人联想，以及你为什么有这样的感受；不要把个人感受说成所有人的必然反应。","outline":["交代聆听场景和音乐的大致特点。","用节奏、旋律或音量等细节解释自己的感受。","说明个人经历与理解的联系，并承认他人可能有不同联想。"],"model":"At our class music afternoon, a student played a short piece on the piano. The opening notes were quick and light. They reminded me of rain tapping against a window. As the melody became slower, I pictured the quiet street after a shower. I enjoyed the piece because it connected with a memory of walking home with my sister. My friend imagined a completely different scene: a train reaching its final station. Neither of us needed to change the other person’s picture. We compared the sounds that had shaped our ideas. I learned that explaining why music affects me can make a conversation richer than simply saying it is nice."},"speakingPrompts":["Describe a sound or rhythm that brings back a personal memory.","Why might two people imagine different scenes while hearing the same music?","How would you choose suitable background music for a spoken performance?"],"textbook":{"status":"resource-crosschecked","referenceEdition":"2026 新版公开教学资源交叉核对","grammarScope":"because、since、as 和 for 表达原因","unitStartPage":null,"grammarPages":[],"sections":[]},"grammarNote":"依据公开配套资料整理的语法复习；新版教材对应页尚未逐页核验，请与实书对照。"},{"id":"9a-u6","bookId":"9a","number":6,"title":"The art of the brush","theme":"书法与中国艺术","goals":["用具体线条、布局和创作过程介绍书法作品。","通过草稿与成品的联系推断艺术创作中的选择。","使用 who、which、that、whose 引导的定语从句补充人物和作品信息。"],"grammarKeys":["relative_clauses"],"vocabulary":[{"word":"stroke","meaning":"笔画；一笔","example":"The final stroke gave the character a firm ending.","reviewId":0},{"word":"ink","meaning":"墨；墨水","example":"A small drop of ink remained on the edge of the dish.","reviewId":1},{"word":"brush","meaning":"毛笔；刷子","example":"She lifted the brush slowly at the end of the line.","reviewId":2},{"word":"balance","meaning":"平衡；协调","example":"We compared the balance between the dark lines and empty space.","reviewId":3},{"word":"expression","meaning":"表达；神情","example":"The artist discussed the expression she wanted in the work.","reviewId":4},{"word":"tradition","meaning":"传统","example":"The club invites families to share an art tradition they value.","reviewId":5},{"word":"exhibit","meaning":"展出；展品","example":"We will exhibit the practice sheets beside the final work.","reviewId":6},{"word":"revise","meaning":"修改","example":"The student revised the arrangement before writing again.","reviewId":7}],"reading":{"id":"9a-u6-reading","title":"The Sheets Beside the Finished Work","level":"挑战","text":"Han thought the calligraphy display would be easy to arrange. He planned to choose the neatest sheet from each student and place a name below it. Then Ms Tang, the artist who guided the club, brought in several versions of the same character: “山”, meaning mountain.\n\nOne version had thick, dark strokes. Another left more space between thinner lines. Han asked which one was correct. Ms Tang explained that she had made different choices while exploring the feeling she wanted. She demonstrated how she pressed and lifted the brush. The line changed as her movement changed. Clear shape and careful control mattered, but copying one printed shape was not the only aim of that afternoon’s exercise.\n\nHan was especially interested in a sheet whose last stroke had been crossed out. Beside it was a note about making the lower part more balanced. He could follow a decision that would have been invisible in the finished work alone.\n\nFor the school display, Han placed one practice sheet beside each final piece. Students wrote short labels explaining a change they had made. Visitors could read the meaning of the character and also see part of the process. Han still admired the finished works. Now, however, the sheets that showed effort and revision seemed worth looking at too.","summary":"Han 最初只想挑选最整齐的书法成品展出。通过观察同一字的不同写法、笔触示范和修改笔记，他理解了创作中的选择，最后把练习稿与成品并置，让观众也看见过程。","questions":[{"prompt":"What was Han’s first plan for the display?","options":["Choose the neatest sheet from each student.","Show only the brushes and ink.","Invite visitors to vote before students wrote anything.","Display every sheet without any label."],"correctIndex":0,"explanation":"第一段明确说他原计划挑每位学生最整齐的一张并放上姓名。","skill":"最初计划"},{"prompt":"What did the different versions of “山” help Ms Tang discuss?","options":["Ways to print every character in exactly one shape.","The price of buying a new school building.","The rules of a running competition.","Choices about strokes, space and the feeling of the work."],"correctIndex":3,"explanation":"第二段对比笔画粗细、留白和想表达的感觉，并说明不只追求复制单一印刷字形。","skill":"示例作用"},{"prompt":"What did the note beside the crossed-out stroke mention?","options":["Throwing away all practice sheets.","Making the lower part more balanced.","Changing the character into an English word.","Removing every dark stroke."],"correctIndex":1,"explanation":"第三段明确写旁边笔记涉及 making the lower part more balanced。","skill":"细节定位"},{"prompt":"Which item would Han most likely include in a later art display?","options":["A rule forbidding visitors to see any drafts.","A row of identical printed letters without explanations.","A sketch with notes explaining how a design changed.","Only a price list, without the artworks."],"correctIndex":2,"explanation":"Han 因修改笔记理解了创作决定，并主动展示过程，可推知他今后也会重视能解释设计变化的草图。","skill":"有证据的推断"},{"prompt":"How did Han change the final display?","options":["He paired practice sheets with finished pieces and explanations of changes.","He displayed only Ms Tang’s tools without writing.","He hid every sheet that showed a revision.","He removed all student work and showed printed letters."],"correctIndex":0,"explanation":"最后一段说明练习稿与最终作品并置，学生用短标签解释修改。","skill":"结果概括"}]},"dialogue":{"title":"A Label That Helps Visitors Look","turns":[{"speaker":"Bo","text":"I like the piece that Chen wrote for the exhibition. The character means “quiet”, but some visitors may not read Chinese."},{"speaker":"Wen","text":"Then the label should give the meaning in English. We can also explain what Chen wanted people to notice."},{"speaker":"Bo","text":"She told me that she left wide spaces around the character to give it a calm feeling."},{"speaker":"Wen","text":"Could we show the earlier sheet whose strokes were much closer together? Visitors could compare the two."},{"speaker":"Bo","text":"Yes. Chen has agreed to lend us that sheet. I will write a short label about the change in spacing."},{"speaker":"Wen","text":"Let us ask a classmate to read the label before we print it. The explanation should help people look at the work, not take all their attention away from it."}],"questions":[{"prompt":"What does the character in Chen’s piece mean?","options":["Spring.","River.","Mountain.","Quiet."],"correctIndex":3,"explanation":"Bo 第一轮明确说该字意思是 quiet；mountain 来自本单元阅读而不是这段对话。","skill":"对话细节"},{"prompt":"Why do they want an English meaning on the label?","options":["Chen wants to replace the character with numbers.","Some visitors may not read Chinese.","English letters were already painted over the work.","The exhibition has no visitors."],"correctIndex":1,"explanation":"Bo 提到部分观众可能不识汉字，Wen 因此建议给出英文意思。","skill":"原因理解"},{"prompt":"What effect did Chen want the wide spaces to create?","options":["A crowded scene.","A loud sound.","A calm feeling.","A sense that the page was unfinished by mistake."],"correctIndex":2,"explanation":"第三轮直接说明 wide spaces 是为了 give it a calm feeling。","skill":"创作意图"},{"prompt":"What will visitors be able to compare?","options":["Two different school buildings.","A river photo and a music recording.","The prices of several ink bottles.","The earlier crowded strokes and the later wider spacing."],"correctIndex":3,"explanation":"Wen 提议展示笔画更紧凑的早期稿，与当前留白较大的作品对比。","skill":"比较信息"},{"prompt":"What will they do before printing the label?","options":["Ask a classmate to read it.","Sell the earlier sheet.","Change Chen’s name.","Remove the final artwork."],"correctIndex":0,"explanation":"Wen 最后一轮明确建议印制前请同学读标签。","skill":"步骤顺序"}]},"writing":{"prompt":"写一篇 100—130 词的作品介绍，推荐一件书法、绘画或手工作品。描写它的具体特征、创作者的一项选择以及你希望观众注意的内容。至少使用两处定语从句。","outline":["介绍作品、创作者和展示场景。","描述线条、颜色、材料或布局，并解释一项创作选择。","说明你欣赏的原因及希望观众仔细观察的细节。"],"model":"The artwork I want to introduce is a calligraphy piece that my classmate made for our school exhibition. She wrote a character meaning “home” with a brush and dark ink. The upper strokes are small, while the lower part feels open and steady. My classmate, who practised several arrangements, said she wanted the character to feel welcoming. Beside the final piece, we displayed a draft whose lines were crowded together. Comparing the two helped me understand her choice. I admire the patience behind the work as much as its appearance. I hope visitors will pause, look at the spaces between the strokes and read the short explanation below it."},"speakingPrompts":["How could you introduce a Chinese artwork to someone who cannot read its characters?","What can a draft reveal that a finished piece may hide?","Choose one feature of an artwork and explain why it interests you."],"textbook":{"status":"resource-crosschecked","referenceEdition":"2026 新版公开教学资源交叉核对","grammarScope":"限制性定语从句","unitStartPage":null,"grammarPages":[],"sections":[]},"grammarNote":"依据公开配套资料整理的语法复习；新版教材对应页尚未逐页核验，请与实书对照。"},{"id":"9a-u7","bookId":"9a","number":7,"title":"The big screen","theme":"电影与评价","goals":["从情节、画面、声音等角度描述一部电影。","用具体场景支持评价，并比较不同观众的合理看法。","使用让步、结果和目的从句组织较完整的评论。"],"grammarKeys":["adverbial_concession","adverbial_result_purpose"],"vocabulary":[{"word":"scene","meaning":"场景；一场戏","example":"The final scene shows a map beside an open window.","reviewId":0},{"word":"plot","meaning":"情节","example":"The plot follows a girl who is preparing a farewell gift.","reviewId":1},{"word":"character","meaning":"人物；角色","example":"The main character changes her plan after a conversation.","reviewId":2},{"word":"soundtrack","meaning":"电影配乐；原声带","example":"The soundtrack was too loud during one quiet conversation.","reviewId":3},{"word":"review","meaning":"评论","example":"A useful review supports opinions with examples.","reviewId":4},{"word":"performance","meaning":"表演","example":"The actor gave a convincing performance without much dialogue.","reviewId":5},{"word":"recommend","meaning":"推荐","example":"I would recommend this film to viewers who enjoy quiet stories.","reviewId":6},{"word":"evidence","meaning":"证据；依据","example":"She used a specific scene as evidence for her opinion.","reviewId":7}],"reading":{"id":"9a-u7-reading","title":"More Than “Boring” or “Brilliant”","level":"进阶","text":"The school film club watched an eleven-minute student film called “The Unfinished Map”. In it, Yun draws a map for her friend Ada, who is moving away. She marks their favourite places: a bakery, a bus stop and a bench behind the library. In the final scene, she leaves one corner empty and writes, “For your next adventure.”\n\nAfter the screening, Laila wrote, “It was boring.” Toby wrote, “It was brilliant.” Their club leader asked what a reader could learn from those two comments. Neither review explained a scene or gave a reason.\n\nThey watched parts of the film again. Toby noticed close views of Yun’s hands, the erased pencil lines and the ink on her fingers. He felt these details showed how much care she put into the gift. Laila noticed a different problem: the music was so loud during one conversation that she could not hear two important lines. She also wanted more information about why Ada was leaving.\n\nBoth students rewrote their reviews. Although their opinions remained different, their explanations became more useful. Toby praised the careful images, while Laila described the sound problem and the missing information. They included enough of the story to help readers decide whether it might interest them, but left the final scene unexplained so that future viewers could discover it themselves.","summary":"电影社成员最初只用“无聊”或“精彩”评价一部学生短片。重看片段后，他们分别用画面细节和声音问题支持看法，写出了更具体、有参考价值且照顾未来观众的评论。","questions":[{"prompt":"Why is Yun making a map in the student film?","options":["It is a plan for a new shopping centre.","It is a ticket for a train journey.","It will replace the school’s fire notice.","It is a gift for Ada, who is moving away."],"correctIndex":3,"explanation":"第一段说明 Yun 为即将搬走的朋友 Ada 画地图。","skill":"情节信息"},{"prompt":"What was missing from Laila’s and Toby’s first reviews?","options":["The students’ names on a class list.","Scenes and reasons supporting their opinions.","A complete copy of the film script.","Instructions for drawing every street."],"correctIndex":1,"explanation":"第二段明确说两篇最初评论都没有解释场景或给出理由。","skill":"问题概括"},{"prompt":"Which detail supported Toby’s positive opinion?","options":["Close views of erased lines and ink on Yun’s fingers.","A long speech explaining every street.","The absence of any picture of the gift.","A list of ticket prices on the screen."],"correctIndex":0,"explanation":"第三段列出手部特写、擦过的线条和手指墨迹，Toby 从中看出用心。","skill":"观点与证据对应"},{"prompt":"Which statement would the club leader most likely agree with?","options":["Only positive reviews should ever be written.","Every viewer must reach the same judgement about a film.","A negative review can be useful when it explains specific problems.","A score without any detail always tells readers enough."],"correctIndex":2,"explanation":"负责人让两人补充场景与理由；Laila 保留负面评价却用声音问题作依据，评论变得更有用，因此可推知有依据的负面评论也有价值。","skill":"有证据的推断"},{"prompt":"Why did the students leave the final scene unexplained in their reviews?","options":["Because they had never watched it.","So future viewers could discover it themselves.","So readers would think the film was a news report.","Because the film had no ending at all."],"correctIndex":1,"explanation":"最后一句用 so that 明确说明把发现结尾的机会留给未来观众。","skill":"目的理解"}]},"dialogue":{"title":"Writing Without Giving Everything Away","turns":[{"speaker":"Mai","text":"My review explains the whole ending. Is that too much for someone who has not seen the film?"},{"speaker":"Sheng","text":"Probably. You can explain the main problem without revealing how it is solved."},{"speaker":"Mai","text":"Then I will say that the girl must find the owner of a lost bag, but I will leave out the final meeting."},{"speaker":"Sheng","text":"Good. Which detail supports your opinion that the film creates a tense mood?"},{"speaker":"Mai","text":"The camera stays close to the bag, and the footsteps become louder while the girl waits in the empty hall."},{"speaker":"Sheng","text":"Those examples will help. Although some viewers may not enjoy a slow scene, they will understand why you found it effective."}],"questions":[{"prompt":"What is Mai worried about?","options":["Forgetting the school bus number.","Losing the film club’s camera.","Revealing too much of the film’s ending.","Writing a review in pencil."],"correctIndex":2,"explanation":"Mai 第一轮问完整解释结尾是否对未看电影的人透露过多。","skill":"问题定位"},{"prompt":"What does Sheng suggest describing?","options":["A different film that Mai has not seen.","Every surprise in the final meeting.","Only the actors’ names and nothing else.","The main problem without its complete solution."],"correctIndex":3,"explanation":"第二轮建议讲清主要问题，但不透露如何解决。","skill":"建议理解"},{"prompt":"What must the girl in the film do?","options":["Find the owner of a lost bag.","Repair a broken piano.","Draw a map for a tourist.","Build a bridge over a river."],"correctIndex":0,"explanation":"Mai 第三轮说明女孩必须找到遗失包的主人。","skill":"情节细节"},{"prompt":"Which sound does Mai mention?","options":["Birdsong fading into silence.","A loud bell at the school gate.","A band playing outside a shop.","Footsteps becoming louder."],"correctIndex":3,"explanation":"第五轮明确说 footsteps become louder。","skill":"声音线索"},{"prompt":"What does Sheng think the examples will do?","options":["Prove that all slow films are exciting.","Explain why Mai found the scene effective, even if others feel differently.","Force every viewer to give the film the same score.","Replace the need for any opinion."],"correctIndex":1,"explanation":"最后一轮承认有人不喜欢节奏较慢的场景，但具体例子能说明 Mai 的评价依据。","skill":"让步关系与意图"}]},"writing":{"prompt":"为一部真实看过或自行设想的短片写一篇 100—130 词的评论。简述基本情境，分别给出一项优点和可改进处，并用具体画面或声音细节支持评价。避免完整揭示结局，使用 although/though 和 so ... that 或 so that。","outline":["介绍片名或情境，以及适合怎样的观众。","用至少两处画面、声音或表演细节支持评价。","提出一项改进建议并给出整体推荐意见。"],"model":"I would recommend our class film, The Red Umbrella, to viewers who enjoy quiet stories. It follows a girl who borrows an umbrella during a sudden shower and later tries to return it. Although the plot is simple, the warm colours and careful acting make the characters believable. One close view of the wet handle tells us more than a long speech could. However, a conversation near the end is so soft that some words are difficult to hear. I hope the team improves the sound before the next screening. I will not explain the ending, so that new viewers can enjoy discovering how a small act of kindness continues."},"speakingPrompts":["What specific scene could support a positive or negative film review?","How can you explain a film’s basic situation without revealing its ending?","Can two opposite reviews both be useful? Explain your view."],"textbook":{"status":"resource-crosschecked","referenceEdition":"2026 新版公开教学资源交叉核对","grammarScope":"让步、结果和目的状语从句","unitStartPage":null,"grammarPages":[],"sections":[]},"grammarNote":"依据公开配套资料整理的语法复习；新版教材对应页尚未逐页核验，请与实书对照。"},{"id":"9a-u8","bookId":"9a","number":8,"title":"The world of literature","theme":"文学阅读与创作","goals":["结合人物行动和情节线索理解故事中的冲突。","为不同续写方案提供依据，检查选择与后果是否连贯。","使用 if、unless 等条件表达讨论情节可能怎样发展。"],"grammarKeys":["adverbial_condition"],"vocabulary":[{"word":"literature","meaning":"文学","example":"Our reading club explores literature in several forms.","reviewId":0},{"word":"narrator","meaning":"叙述者","example":"The narrator knows only what she can see and hear.","reviewId":1},{"word":"clue","meaning":"线索","example":"The muddy footprint is a clue that matters later.","reviewId":2},{"word":"conflict","meaning":"冲突","example":"The story’s conflict begins when two promises cannot easily be kept.","reviewId":3},{"word":"ending","meaning":"结尾","example":"A surprising ending still needs a connection to the earlier story.","reviewId":4},{"word":"imagination","meaning":"想象力","example":"Imagination helped us invent three possible journeys for the character.","reviewId":5},{"word":"draft","meaning":"草稿","example":"I changed the conversation in the second draft.","reviewId":6},{"word":"consequence","meaning":"后果；结果","example":"We discussed a likely consequence of each choice.","reviewId":7}],"reading":{"id":"9a-u8-reading","title":"Three Endings for a Blue Envelope","level":"挑战","text":"At the reading club, students received a short draft called “The Blue Envelope”. In the story, An promises to deliver an envelope to a neighbour before five. On the way, he sees a friend sitting alone at a bus stop, looking upset. The draft ends just as An checks his watch for the second time.\n\nThe class wrote possible endings. In one, An continues walking and keeps his promise. In another, he stops to listen and arrives late. Some students immediately called the first ending unkind and the second irresponsible. Their teacher asked them to look more closely at the earlier details. An had checked the time, but he had also slowed down when he noticed his friend.\n\nTara suggested a third ending: An invites the friend to walk with him, so he can listen while delivering the envelope. “What if the friend does not want to go?” someone asked. Tara added a short conversation that showed why the friend agreed. She realized that even a hopeful ending needed clear steps.\n\nThe group did not choose one answer that everyone had to copy. Instead, they compared choices and consequences. If they changed a character’s decision, they checked what else in the story would need to change. For Tara, writing an ending became a way of reading the beginning more carefully.","summary":"阅读社为未完成的故事设计不同结尾。学生从简单给选择贴标签，转向考察人物此前的行为、选择的后果以及情节衔接，理解续写需要想象，也需要文本依据。","questions":[{"prompt":"What has An promised to do?","options":["Deliver an envelope to a neighbour before five.","Write a complete novel in one evening.","Meet his teacher at the cinema after six.","Wait at the bus stop until midnight."],"correctIndex":0,"explanation":"第一段给出承诺：before five 将信封交给邻居。","skill":"故事设定"},{"prompt":"Which detail suggests that An is also concerned about his friend?","options":["He leaves home without looking at the time.","He asks the neighbour to move away.","He slows down when he notices the friend.","He throws the envelope into a bin."],"correctIndex":2,"explanation":"第二段回看原文细节，指出 An 看到朋友时放慢脚步，表现出关心。","skill":"人物线索"},{"prompt":"What is Tara’s proposed ending?","options":["An forgets both the envelope and his friend.","An invites the friend to walk with him while he delivers the envelope.","The teacher delivers the envelope inside the story.","The friend disappears without explanation."],"correctIndex":1,"explanation":"第三段明确提出邀请朋友同行，这样可边送信边倾听。","skill":"情节方案"},{"prompt":"What can we infer about Tara’s approach to feedback?","options":["She is willing to revise an idea when a question reveals a missing step.","She believes a hopeful ending never needs an explanation.","She ignores questions about her plot.","She will only copy an ending chosen by the whole class."],"correctIndex":0,"explanation":"同学问朋友若不愿同行怎么办后，Tara 加入对话说明其同意的原因，表现出根据反馈补足情节的意愿。","skill":"有证据的推断"},{"prompt":"What does the club learn about writing an ending?","options":["A happy result needs no explanation.","There is always one ending that every reader must choose.","The opening becomes useless once an ending is written.","Choices should connect with earlier details and lead to understandable consequences."],"correctIndex":3,"explanation":"结尾强调比较选择与后果，改动决定时检查其他细节，续写促使 Tara 更仔细读开头。","skill":"主题概括"}]},"dialogue":{"title":"Does the Talking Tree Belong in This Story?","turns":[{"speaker":"Rui","text":"In my story, a girl finds a note in the school garden. I want a talking tree to explain everything at the end."},{"speaker":"Sara","text":"That could work in a fantasy. Have you given the reader any earlier hint that trees can talk in this world?"},{"speaker":"Rui","text":"Not yet. So far, the story has been realistic. The girl has only met the school gardener."},{"speaker":"Sara","text":"If you choose the talking tree, you may need to add clues earlier. Otherwise, readers might feel that the answer appears from nowhere."},{"speaker":"Rui","text":"I will keep this draft realistic. Perhaps the gardener wrote the note, and the girl can discover why."},{"speaker":"Sara","text":"Then check the earlier scene with the gardener. Unless it connects with the note, the ending may still feel sudden."}],"questions":[{"prompt":"What does the girl find in Rui’s story?","options":["A lost violin in a theatre.","A map inside a camera.","A note in the school garden.","A blue envelope on a bus."],"correctIndex":2,"explanation":"Rui 第一轮说明女孩在学校花园找到一张便条。","skill":"故事信息"},{"prompt":"What is Rui’s first idea for explaining the mystery?","options":["The girl wakes up in a different school.","A talking tree explains everything.","The reader receives a phone call.","A bus driver finds a secret tunnel."],"correctIndex":1,"explanation":"Rui 最初想在结尾让一棵会说话的树解释一切。","skill":"最初构想"},{"prompt":"What problem does Sara identify?","options":["A fantasy can never contain a garden.","The story includes too many gardeners.","Rui has already explained too much about the tree.","There is no earlier hint that trees can talk in the story’s world."],"correctIndex":3,"explanation":"Sara 追问是否有会说话的树的前期提示，Rui 承认没有且目前故事是现实风格。","skill":"结构问题"},{"prompt":"What does Rui decide for this draft?","options":["Keep it realistic and consider the gardener as the note’s writer.","Remove both the note and the garden.","Copy the ending of another classmate’s story.","Make every character a talking tree immediately."],"correctIndex":0,"explanation":"第五轮明确说 keep this draft realistic，并考虑园丁写了便条。","skill":"决定理解"},{"prompt":"Why should Rui check the earlier scene with the gardener?","options":["To replace the whole story with a weather report.","To hide all clues from readers forever.","To connect the ending with information already in the story.","To make sure the gardener has no relation to the mystery."],"correctIndex":2,"explanation":"Sara 最后一轮说若早期场景与便条无联系，结尾仍会突兀，所以需建立联系。","skill":"条件与后果"}]},"writing":{"prompt":"写一个 100—130 词的原创短故事。让人物遇到一个选择，在前文埋下一条能支持结尾的线索，并写出选择带来的结果。至少使用一句 if 或 unless 条件表达。","outline":["交代人物、地点和一个引起好奇的发现。","让人物面对选择，并用细节推动行动。","写出与前面线索相呼应的结果，避免突然出现无铺垫的解决办法。"],"model":"On a rainy afternoon, I found a small envelope inside a library book. A note said, “If you have a story to share, leave it on the blue shelf.” I looked across the room and noticed several handwritten pages there. At home, I wrote about a train journey with my grandfather. I returned the next day and placed my page beside the others. A week later, a reply was waiting. Someone had written about a similar journey and asked a question about mine. The librarian smiled when I showed her. I had expected a hidden prize, but the shelf offered something different: a reader who wanted to hear more."},"speakingPrompts":["How can an earlier detail make a surprising ending feel believable?","If a character changes one important decision, what else might need to change?","Invent two possible endings for a story and explain the consequence of each choice."],"textbook":{"status":"resource-crosschecked","referenceEdition":"2026 新版公开教学资源交叉核对","grammarScope":"if / unless 引导的条件状语从句","unitStartPage":null,"grammarPages":[],"sections":[]},"grammarNote":"依据公开配套资料整理的语法复习；新版教材对应页尚未逐页核验，请与实书对照。"},{"id":"9b-u1","bookId":"9b","number":1,"title":"Asia","theme":"亚洲与旅行","curriculumNote":"已核验旧版九下四单元主题的原创配套复习；非教材课文或逐页复刻。","grammarKeys":["it_uses"],"goals":["区分具体旅行观察与对一个地区的笼统判断","用it表达时间、距离或形式主语结构","设计能呈现不同个人经验的文化交流任务"],"vocabulary":[{"word":"itinerary","meaning":"旅行日程","example":"Our itinerary leaves time for an unplanned walk.","reviewId":0},{"word":"landmark","meaning":"地标","example":"The old clock tower is a landmark in the student’s drawing.","reviewId":1},{"word":"neighbourhood","meaning":"街区；社区","example":"A local student described her neighbourhood to us.","reviewId":2},{"word":"pedestrian","meaning":"行人","example":"A pedestrian waits beside the crossing on our route.","reviewId":3},{"word":"tradition","meaning":"传统","example":"The family explained one tradition in their own words.","reviewId":4},{"word":"local","meaning":"本地的","example":"We asked a local volunteer which details to label.","reviewId":5},{"word":"exhibit","meaning":"展品；展示","example":"Each exhibit included a date and a short explanation.","reviewId":6},{"word":"route","meaning":"路线","example":"The map showed the route of one family’s visit.","reviewId":7}],"reading":{"id":"9b-u1-reading","title":"The Map Between Two Tables","level":"进阶","text":"It was Saturday morning when our school held an Asia travel fair with two partner schools. Our group prepared a table about a family visit to Nanjing. Across the room, students from a partner school shared photographs of their neighbourhood in Kyoto. It was only three metres between our tables, but our conversations opened a much wider space.\n\nAt first, I wanted to label our display “Life in China”. Our teacher asked whether one family’s weekend could represent such a large and varied country. We changed the title to “Our Two Days in Nanjing” and added the month of the visit.\n\nYuki, a student from the Kyoto group, explained a photograph of a quiet street. I assumed that all the streets near her home were peaceful. She laughed and showed me another picture taken beside a busy station. Both photographs were accurate, but neither told the whole story.\n\nWe decided to draw a map between our tables. Visitors could add questions, routes and memories from their own experiences. By lunchtime, it had become our most popular exhibit. There were no prizes for the country with the best food or the prettiest buildings. Instead, we compared specific experiences and asked what we still wanted to learn. It was important to keep our questions open.","summary":"一次亚洲旅行交流展让学生认识到，个人照片和短途经历不能代表整个国家，清楚标注情境有助于真实交流。","questions":[{"prompt":"What did the writer’s group originally prepare?","options":["A display about a family visit to Nanjing","A timetable for every Asian city","A collection of train tickets from Kyoto","A competition about world capitals"],"correctIndex":0,"explanation":"第一段说明小组准备的是一次南京家庭旅行的展示。","skill":"细节理解"},{"prompt":"Why did they change the title “Life in China”?","options":["The photographs had been lost.","The partner school disliked maps.","The trip lasted a month.","One family’s weekend could not represent the whole country."],"correctIndex":3,"explanation":"老师提醒他们，一个家庭的周末经历不足以代表幅员广阔且多样的国家。","skill":"细节理解"},{"prompt":"What did Yuki’s second picture show?","options":["A mountain village","A busy station area","An empty museum","A school playground"],"correctIndex":1,"explanation":"Yuki 用车站旁的繁忙景象补充了第一张安静街道的照片。","skill":"细节理解"},{"prompt":"What could visitors add to the shared map?","options":["Only prices","Only flags","Questions, routes and memories","The names of prize winners"],"correctIndex":2,"explanation":"第四段列出访客可补充的问题、路线与个人记忆。","skill":"细节理解"},{"prompt":"What is the main lesson of the fair?","options":["Specific experiences invite better questions than broad assumptions.","Every photograph gives a complete picture of a country.","Cultural exchanges must choose a winning country.","People should avoid discussing differences."],"correctIndex":0,"explanation":"两次纠正笼统判断、补充不同场景后，展览转向具体经验与开放提问，体现谨慎理解文化的价值。","skill":"推断主题"}]},"dialogue":{"title":"Preparing a Travel Display","turns":[{"speaker":"Leah","text":"Our Asia travel display opens at ten on Wednesday. Have you finished the map of our family’s route?"},{"speaker":"Ryan","text":"Almost. It took me two hours yesterday. I have marked the three places we actually visited, not every famous attraction."},{"speaker":"Leah","text":"Good. We should add the date of the trip. The photographs were taken in April, when the weather was cool."},{"speaker":"Ryan","text":"I’ll put that below the title. Shall we include the conversation with the local guide?"},{"speaker":"Leah","text":"Yes, but ask her permission before displaying her photograph. We can share our notes without including her picture if she prefers."},{"speaker":"Ryan","text":"Agreed. I’ll also leave a blank card for visitors to ask one question about the route."}],"questions":[{"prompt":"When will the display open?","options":["At nine on Monday","At ten on Wednesday","At eleven on Friday","At noon on Saturday"],"correctIndex":1,"explanation":"Leah 说展示在周三十点开放。","skill":"细节理解"},{"prompt":"How long did Ryan spend on the map yesterday?","options":["One hour","Three hours","Two hours","Four hours"],"correctIndex":2,"explanation":"Ryan 明确说昨天花了两小时。","skill":"细节理解"},{"prompt":"How many visited places has Ryan marked?","options":["Three","Four","Five","Six"],"correctIndex":0,"explanation":"地图标注的是家庭实际去过的三个地点。","skill":"细节理解"},{"prompt":"When were the photographs taken?","options":["In January","In March","In June","In April"],"correctIndex":3,"explanation":"Leah 说照片摄于四月。","skill":"细节理解"},{"prompt":"What will Ryan leave for visitors?","options":["A free travel ticket","A blank question card","A list of prizes","A photograph of every guide"],"correctIndex":1,"explanation":"Ryan 最后决定留一张空白卡供访客提问。","skill":"细节理解"}]},"writing":{"prompt":"写100—130词，为一次关于亚洲城市或地区的文化交流展撰写介绍。说明展示来自谁的什么经历、资料日期、能说明什么以及仍希望了解什么。","outline":["明确资料范围：Our display presents ... from ...","用具体例子介绍：One photograph shows ... / It was ...","邀请进一步交流：It is important to ... We would like to ask ..."],"model":"Our display presents one family’s weekend in Nanjing, rather than claiming to describe every part of the city. The photographs were taken in April, and each one includes a short note about the place and the people we met. It took us several evenings to select images that showed different experiences. One picture presents a busy street, while another shows a quiet reading corner. Visitors are invited to add questions or share a different memory of the same place. It is important to remember that a short journey gives us only a partial view. We hope the display encourages conversation and helps us decide what to explore more carefully next time."},"speakingPrompts":["What can one travel photograph tell us, and what might it leave out?","How can you use it to describe time or distance in a travel story?","What respectful question would you ask a visitor from another place?"],"vocabularyRevision":2,"textbook":{"status":"legacy-reference","referenceEdition":"旧版四单元；修订版目录待核","grammarScope":"it作代词、非人称代词及形式主语的用法","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"9b-u2","bookId":"9b","number":2,"title":"Great people","theme":"人物贡献与学习","curriculumNote":"已核验旧版九下四单元主题的原创配套复习；非教材课文或逐页复刻。","grammarKeys":["simple_present","present_continuous","simple_past","past_continuous","past_vs_perfect"],"goals":["从经历、行动与影响三个角度理解人物贡献","根据时间线复习常见时态的区别","用具体证据表达对人物品质的评价"],"vocabulary":[{"word":"contribution","meaning":"贡献","example":"Her contribution included years of patient community work.","reviewId":0},{"word":"achievement","meaning":"成就","example":"The finished bridge was a shared achievement.","reviewId":1},{"word":"engineer","meaning":"工程师","example":"The engineer listened to residents before changing the plan.","reviewId":2},{"word":"evidence","meaning":"证据","example":"The notebooks provided evidence of several improvements.","reviewId":3},{"word":"colleague","meaning":"同事","example":"She thanked the colleague who checked her drawings.","reviewId":4},{"word":"persistent","meaning":"坚持不懈的","example":"A persistent learner keeps asking useful questions.","reviewId":5},{"word":"recognition","meaning":"认可；表彰","example":"He accepted the recognition on behalf of the team.","reviewId":6},{"word":"influence","meaning":"影响","example":"Her example has influenced the way I approach group work.","reviewId":7}],"reading":{"id":"9b-u2-reading","title":"The People Outside the Photograph","level":"进阶","text":"For our school magazine, I interviewed Ms Luo, a retired engineer from our fictional town of Eastbank. She had received a community award for helping redesign a footbridge. I arrived with a camera and a question about her greatest achievement.\n\nWhen I entered her study, she was reviewing a thick notebook with a former colleague. The pages contained sketches, measurements and comments from residents. One note described a parent struggling to move a pushchair through a narrow entrance. Another recorded where rainwater collected after a storm.\n\nI expected a story about one brilliant idea. Instead, Ms Luo described months of listening, testing and revising. A maintenance worker had noticed a drainage problem. A local parent had suggested a different entrance. Her colleague had found an error in an early drawing before construction began.\n\nMs Luo said that the bridge had made daily journeys easier, but she refused to claim all the credit. “Take a photograph of the notebook too,” she suggested. “The people outside the picture matter.”\n\nI have written several school profiles, but this interview changed my approach. My final article includes a timeline and three short accounts from other members of the team. Ms Luo still appears in the main photograph. This time, however, readers can see the wider work behind the award.","summary":"采访一位虚构的社区工程师时，学生记者发现个人荣誉背后有持续改进与多人协作。","questions":[{"prompt":"What award had Ms Luo received?","options":["A national music prize","A community award","A school sports medal","An international film award"],"correctIndex":1,"explanation":"第一段明确说她因参与人行桥改造获得社区奖项。","skill":"细节理解"},{"prompt":"What was Ms Luo doing when the writer entered?","options":["Painting a wall","Recording a song","Reviewing a notebook with a former colleague","Taking photographs outside"],"correctIndex":2,"explanation":"第二段说明她正在和以前的同事查看厚笔记本。","skill":"细节理解"},{"prompt":"Who noticed a drainage problem?","options":["A maintenance worker","The school reporter","A shop owner","Ms Luo’s brother"],"correctIndex":0,"explanation":"第三段指出维修人员发现了排水问题。","skill":"细节理解"},{"prompt":"What did Ms Luo suggest photographing as well as herself?","options":["The award ceremony","Her old camera","The school magazine","The notebook"],"correctIndex":3,"explanation":"Ms Luo 建议记者也为笔记本拍照。","skill":"细节理解"},{"prompt":"Why did the writer include other team members in the final article?","options":["To avoid mentioning the bridge","To show that the achievement depended on shared work","To prove that awards never matter","To replace evidence with opinions"],"correctIndex":1,"explanation":"采访显示方案来自多人的观察、检查与建议，因此记者补充其他成员的叙述呈现共同贡献。","skill":"推断写作决定"}]},"dialogue":{"title":"Writing a Profile","turns":[{"speaker":"Aiden","text":"I’m writing a profile of our fictional town’s science teacher, Ms Park. She started the repair club in 2018."},{"speaker":"Grace","text":"What has the club achieved since then?"},{"speaker":"Aiden","text":"Students and adult volunteers have repaired more than eighty classroom items. Last month, they repaired six reading lamps."},{"speaker":"Grace","text":"What was Ms Park doing when you visited her yesterday?"},{"speaker":"Aiden","text":"She was helping two students check a damaged model. She is now preparing a workshop about careful observation."},{"speaker":"Grace","text":"You should include an example of how she teaches, as well as the numbers. That will help readers understand her influence."}],"questions":[{"prompt":"When did Ms Park start the repair club?","options":["In 2018","In 2020","In 2022","In 2024"],"correctIndex":0,"explanation":"Aiden 说明社团成立于2018年。","skill":"细节理解"},{"prompt":"How many classroom items have been repaired since then?","options":["Exactly six","Fewer than twenty","Exactly forty","More than eighty"],"correctIndex":3,"explanation":"Aiden 说学生与成人志愿者累计修好了八十多件教室用品。","skill":"细节理解"},{"prompt":"What did the club repair last month?","options":["Six desks","Six reading lamps","Eight models","Eight chairs"],"correctIndex":1,"explanation":"上个月修理的是六盏阅读灯。","skill":"细节理解"},{"prompt":"What was Ms Park doing during Aiden’s visit?","options":["Giving a public speech","Writing a travel diary","Helping two students check a damaged model","Moving all the classroom furniture"],"correctIndex":2,"explanation":"Aiden 到访时，她在帮助两名学生检查损坏的模型。","skill":"细节理解"},{"prompt":"What does Grace suggest including?","options":["An example of Ms Park’s teaching","Only a large photograph","A list of every student’s address","An invented award"],"correctIndex":0,"explanation":"Grace 建议加入具体教学事例，帮助读者理解她的影响。","skill":"细节理解"}]},"writing":{"prompt":"写100—130词，介绍一位你尊敬的人，可以是真实人物，也可以是明确说明的虚构人物。用一件具体事情说明其贡献，并注意不同时间对应的时态。","outline":["介绍人物与持续贡献：... has helped ... for ...","叙述一次具体经历：When I visited ..., ... was ...","评价影响：This experience has taught me ..."],"model":"I respect our school librarian, Ms Chen, because she has helped students develop their own reading interests for many years. Last term, I visited her while she was sorting books for a new reading corner. Instead of choosing everything herself, she asked students which topics were missing. She then worked with teachers and families to collect suitable books. The corner opened in May, and several classmates have started borrowing regularly since then. Ms Chen says that her work is successful when students feel confident enough to choose a book and discuss it. Her example has taught me that a valuable contribution does not always attract attention. Patient listening and steady work can also change people’s daily lives."},"speakingPrompts":["What specific action makes a person worth learning from?","How can you describe a lasting contribution and a past event using different tenses?","Why should a profile sometimes include the people behind an award?"],"textbook":{"status":"legacy-reference","referenceEdition":"旧版四单元；修订版目录待核","grammarScope":"一般现在时与现在进行时比较；一般过去时与过去进行时比较；一般过去时与现在完成时比较","unitStartPage":null,"grammarPages":[],"sections":[]}},{"id":"9b-u3","bookId":"9b","number":3,"title":"Robots","theme":"机器人与日常生活","curriculumNote":"已核验旧版九下四单元主题的原创配套复习；非教材课文或逐页复刻。","grammarKeys":["simple_complex_conversion"],"goals":["区分机器人完成规则任务与判断任务的能力","结合主题复习简单句与复合句的表达转换","描述一种机器人用途及需要人工处理的情形"],"vocabulary":[{"word":"sensor","meaning":"传感器","example":"The model robot used a sensor to detect a coloured card.","reviewId":0},{"word":"instruction","meaning":"指令","example":"A clear instruction told the robot where to stop.","reviewId":1},{"word":"label","meaning":"标签","example":"The label did not match the book inside the cover.","reviewId":2},{"word":"routine","meaning":"常规的","example":"The machine was designed for a routine delivery task.","reviewId":3},{"word":"operator","meaning":"操作员","example":"The operator could stop the model during a test.","reviewId":4},{"word":"reliable","meaning":"可靠的","example":"We tested whether the result was reliable in different situations.","reviewId":5},{"word":"limitation","meaning":"局限","example":"The test revealed a limitation of the robot’s rules.","reviewId":6},{"word":"judgement","meaning":"判断","example":"The damaged label required a person’s judgement.","reviewId":7}],"reading":{"id":"9b-u3-reading","title":"Pip and the Wrong Label","level":"进阶","text":"For our school technology exhibition, we designed a fictional library robot called Pip. In our story, Pip could read coloured labels and carry returned books to three collection tables. Blue meant stories, green meant science and yellow meant history. We imagined that this would save librarians time on a routine task.\n\nDuring the demonstration, our teacher placed a science book inside a cover with a blue label. Pip carried it to the story table exactly as its instructions required. The audience laughed, but our group was puzzled. The robot had followed the rule correctly and still produced the wrong result.\n\nNext, the teacher offered a book with a damaged label. Our first design simply sent it to the nearest table. We realised that this was a hidden guess, not a useful decision. We rewrote the plan so that Pip would stop and display a request for an operator whenever a label could not be read clearly.\n\nOur final poster described both the robot’s job and its limitations. Pip could move suitable books according to their labels; it could not decide whether the labels were truthful. A librarian would still need to check unusual cases. Visitors asked fewer questions about whether Pip was “clever” and more questions about when people should take responsibility. That made our exhibition discussion much more interesting.","summary":"一个虚构的图书搬运机器人在错误标签测试中暴露局限，学生据此明确机器规则与人工判断的分工。","questions":[{"prompt":"What did a green label mean in the design?","options":["History","Science","Stories","Art"],"correctIndex":1,"explanation":"第一段定义绿色标签代表科学类书籍。","skill":"细节理解"},{"prompt":"Where did Pip take the science book with a blue label?","options":["The history table","The entrance","The story table","The teacher’s office"],"correctIndex":2,"explanation":"机器人依蓝色标签执行规则，把科学书送到了故事书桌。","skill":"细节理解"},{"prompt":"What did the first design do with a damaged label?","options":["Sent the book to the nearest table","Stopped and called an operator","Repaired the label","Read the whole book"],"correctIndex":0,"explanation":"第三段明确说初版遇到破损标签会送到最近的桌子。","skill":"细节理解"},{"prompt":"What did the students add to the revised plan?","options":["A promise to understand every book","A new colour for every reader","A longer moving route","A request for an operator when a label was unclear"],"correctIndex":3,"explanation":"修订后，标签无法辨认时机器人应停下并请求操作员处理。","skill":"细节理解"},{"prompt":"What can we infer from the wrong-label test?","options":["Following a rule always produces a correct real-world result.","A system needs checks for unreliable information.","A damaged label proves the robot is dishonest.","Librarians have no useful role in sorting books."],"correctIndex":1,"explanation":"错误输入导致机器人忠实执行规则却产生错误分类，说明还需要检查资料和处理例外。","skill":"推断系统局限"}]},"dialogue":{"title":"Designing a Classroom Helper","turns":[{"speaker":"Chloe","text":"For our story project, let’s design a robot that carries exercise books between the classroom and the office."},{"speaker":"Leo","text":"It should carry no more than twelve books at a time. A teacher will check the route before each demonstration."},{"speaker":"Chloe","text":"What should it do if a chair blocks its path?"},{"speaker":"Leo","text":"It should stop and show a help message. It must not push the chair or choose an unknown route by itself."},{"speaker":"Chloe","text":"Good. I’ll draw the screen message: Please call the operator. We can test the plan with empty boxes first."},{"speaker":"Leo","text":"And our poster should explain that this is a fictional design, not a robot the school has already bought."}],"questions":[{"prompt":"What task is the fictional robot designed to do?","options":["Carry exercise books","Cook school lunches","Mark every essay","Clean the sports field"],"correctIndex":0,"explanation":"Chloe 设计的是往返教室与办公室搬运练习本的机器人。","skill":"细节理解"},{"prompt":"What is the planned maximum load?","options":["Six books","Eight books","Ten books","Twelve books"],"correctIndex":3,"explanation":"Leo 规定一次最多搬十二本。","skill":"细节理解"},{"prompt":"Who will check the route before a demonstration?","options":["A visitor","A teacher","The youngest student","A shop assistant"],"correctIndex":1,"explanation":"Leo 说演示前由教师检查路线。","skill":"细节理解"},{"prompt":"What should the robot do if a chair blocks its path?","options":["Push the chair","Invent another route","Stop and show a help message","Drop all the books"],"correctIndex":2,"explanation":"遇椅子挡路时，应停下并显示求助信息。","skill":"细节理解"},{"prompt":"What must the poster make clear?","options":["The robot is a fictional design.","The school has bought ten robots.","The robot can solve every problem.","The design has passed every possible test."],"correctIndex":0,"explanation":"最后一轮要求明确这是虚构设计，并非学校已购买的产品。","skill":"细节理解"}]},"writing":{"prompt":"写100—130词，介绍一种你设想的日常辅助机器人。说明具体任务、工作条件和一种必须请求人工帮助的情况。转换简单句或复合句时保持原意，不必硬套教材分项。","outline":["说明具体用途：I would like a robot that ...","说明条件与边界：It could ..., provided that ... / If ..., it should ...","表达人的责任：A person would still need to ..."],"model":"I would like a small robot that carries returned books to the library desk. Its job would be limited to moving clearly labelled boxes along a checked route. It could save staff time, but it would not decide which books are suitable for each reader. If an object blocked its path, it should stop and ask an adult operator for help. It should also report a damaged label instead of guessing where a box belongs. Before using such a robot, the school would need supervised tests in different situations. I would describe it as a useful helper with clear limits. Human judgement would remain important, especially when information was missing or unexpected problems appeared."},"speakingPrompts":["Which routine task would you like a robot to help with?","When should a robot stop and ask a person for help?","Can you express the same idea with a simple sentence and a compound or complex sentence?"],"textbook":{"status":"legacy-reference","referenceEdition":"旧版四单元；修订版目录待核","grammarScope":"简单句与复合句之间的转换（第一部分；细项待课本核验）","unitStartPage":null,"grammarPages":[],"sections":[]},"grammarNote":"旧版主题配套复习：简单句与复合句的常见转换。未将下列内容标为教材转换 I / II 的逐项原题。"},{"id":"9b-u4","bookId":"9b","number":4,"title":"Life on Mars","theme":"太空生活设想","curriculumNote":"已核验旧版九下四单元主题的原创配套复习；非教材课文或逐页复刻。","grammarKeys":["simple_complex_conversion"],"goals":["理解科幻设定与现实资料的区别","用简单句和复合句组织条件、原因与想法","在未来生活设想中考虑人的情感与共同需求"],"vocabulary":[{"word":"settlement","meaning":"定居点","example":"The fictional settlement had a shared study room.","reviewId":0},{"word":"supply","meaning":"供应品；供给","example":"The characters checked their supplies in the story.","reviewId":1},{"word":"privacy","meaning":"隐私；私人空间","example":"Each resident wanted a little privacy after work.","reviewId":2},{"word":"communication","meaning":"交流；通信","example":"A regular message helped the family maintain communication.","reviewId":3},{"word":"adapt","meaning":"适应","example":"The young character gradually adapted to the new routine.","reviewId":4},{"word":"routine","meaning":"日常安排","example":"Their routine included work, exercise and free time.","reviewId":5},{"word":"imagine","meaning":"想象","example":"We imagined a future without presenting it as fact.","reviewId":6},{"word":"cooperate","meaning":"合作","example":"The residents had to cooperate to solve a shared problem.","reviewId":7}],"reading":{"id":"9b-u4-reading","title":"A Quiet Hour on Mars","level":"进阶","text":"In our science-fiction writing project, we imagined a small settlement on Mars. Our teacher asked us to label every invented technology clearly and to focus on how people might live together. My first draft contained fast vehicles, helpful robots and a room full of colourful screens. Everyone seemed happy all the time.\n\nMy partner asked a question that changed the story: where could a person go to be alone? I had designed spaces for growing food, working and exercising, but nowhere quiet. I added a character named Niko, a student who missed his family after several months away.\n\nIn the revised story, Niko enjoys learning from the other residents, yet he finds the shared rooms tiring. One evening, he asks to use an empty storage room to record a private message home. Another resident explains that supplies must still be accessible, so they cannot simply lock the room.\n\nThe group works out a different solution. They create a daily quiet hour in part of the study room and agree how to signal when someone needs privacy. Niko helps design a shared notice instead of making the decision alone.\n\nOur story does not predict a real settlement or provide instructions for surviving on Mars. It explores a human question through an imagined setting. Better machines may solve some problems in fiction, but cooperation and consideration still make the place feel like a home.","summary":"学生在火星科幻写作中加入私人空间与思乡情节，借虚构设定讨论共同生活的情感需求。","questions":[{"prompt":"What did the teacher ask students to label clearly?","options":["Every character’s favourite colour","Every invented technology","The price of real space tickets","The names of all planets"],"correctIndex":1,"explanation":"第一段说明老师要求清楚标注所有想象的技术。","skill":"细节理解"},{"prompt":"What was missing from the writer’s first settlement design?","options":["Screens","Vehicles","A quiet place to be alone","A work area"],"correctIndex":2,"explanation":"搭档提出独处空间的问题，叙述者发现原设计缺少安静的私人空间。","skill":"细节理解"},{"prompt":"Why does Niko want to use the storage room?","options":["To record a private message home","To hide all the food","To start a new business","To repair a real spacecraft"],"correctIndex":0,"explanation":"第三段明确说明 Niko 想在那里录制私人家信。","skill":"细节理解"},{"prompt":"What solution does the group finally choose?","options":["Locking every shared room","Stopping all communication","Sending Niko away","Creating a quiet hour in part of the study room"],"correctIndex":3,"explanation":"第四段给出的最终方案是在阅览室部分区域设置每日安静时段。","skill":"细节理解"},{"prompt":"Why is it reasonable for Niko to help design the notice with the group?","options":["The study room belongs only to Niko.","The change affects shared space used by everyone.","Niko cannot write a message himself.","Nobody else needs the supplies."],"correctIndex":1,"explanation":"储藏室需要保持可用，阅览室也是共用空间；结合这些限制，可推断安静时段的安排需要兼顾所有居民，而不是由一人决定。","skill":"推断合作原因"}]},"dialogue":{"title":"Planning a Fictional Space Home","turns":[{"speaker":"Molly","text":"Our writing group needs a plan for an imagined space home. There will be six residents in our story."},{"speaker":"Isaac","text":"Let’s include three shared areas: a work room, a food-growing room and a quiet study room."},{"speaker":"Molly","text":"The characters will also need time to communicate with their families. How can we show that without inventing scientific facts?"},{"speaker":"Isaac","text":"We can describe a character preparing a message, but leave the technical details as clearly labelled story assumptions."},{"speaker":"Molly","text":"Good. I’ll write the scene in the study room. After dinner, the group will meet to discuss a daily quiet hour."},{"speaker":"Isaac","text":"I’ll write a note explaining that the home and its equipment are fictional. Our main question is how residents share space fairly."}],"questions":[{"prompt":"How many residents are planned in the story?","options":["Six","Four","Eight","Ten"],"correctIndex":0,"explanation":"Molly 第一轮说明故事中有六名居民。","skill":"细节理解"},{"prompt":"Which room is NOT among the three shared areas?","options":["A work room","A food-growing room","A quiet study room","A concert hall"],"correctIndex":3,"explanation":"Isaac 列出的三个区域不包含音乐厅。","skill":"细节理解"},{"prompt":"What will Molly write about?","options":["Buying a real space ticket","A scene in the study room","Building an actual rocket","Measuring a planet’s atmosphere"],"correctIndex":1,"explanation":"Molly 说自己负责写阅览室里的场景。","skill":"细节理解"},{"prompt":"When will the characters discuss the quiet hour?","options":["Before breakfast","At midday","After dinner","During a flight lesson"],"correctIndex":2,"explanation":"Molly 说明角色会在晚餐后讨论安静时段。","skill":"细节理解"},{"prompt":"What is the group’s main question?","options":["How residents can share space fairly","Which planet is the hottest","How to sell travel tickets","Which real spacecraft is fastest"],"correctIndex":0,"explanation":"Isaac 最后明确核心问题是居民如何公平共用空间。","skill":"细节理解"}]},"writing":{"prompt":"写100—130词，描绘一处明确标为科幻想象的未来太空居住空间。说明一项共同需求、一个分歧及合作解决办法；不把虚构设备参数写成现实事实。","outline":["交代想象设定：In my science-fiction story, ...","提出人的需求与问题：Although ..., one resident ...","说明共同决定：The group agrees to ... because ..."],"model":"In my science-fiction story, six people share a small home on Mars. The settlement and its machines are imaginary, so the story is not a guide to real space travel. I want to explore how the residents make room for different needs. One character enjoys group activities, while another needs quiet time to write messages home. At first, they argue about the study room. Later, they create a timetable together and agree on a signal that means someone needs privacy. The plan can be changed when a new problem appears. I would like readers to see that a future home depends on more than equipment. Listening and fair decisions help people live together."},"speakingPrompts":["What human need might be easy to forget in a story about future technology?","How could people share a small space fairly?","How would you distinguish a story assumption from a scientific fact?"],"textbook":{"status":"legacy-reference","referenceEdition":"旧版四单元；修订版目录待核","grammarScope":"简单句与复合句之间的转换（第二部分；细项待课本核验）","unitStartPage":null,"grammarPages":[],"sections":[]},"grammarNote":"旧版主题配套复习：简单句与复合句的常见转换。未将下列内容标为教材转换 I / II 的逐项原题。"}],"previewOnly":false,"textbookSources":[{"label":"南京市政府：2026 秋新教材启用情况","url":"https://www.nanjing.gov.cn/msxx/202608/t20260824_5898135.html"},{"label":"芜湖市教育局：2026 秋电子教材目录更新","url":"https://jyj.wuhu.gov.cn/xwzx/tzgg/8953250.html"}]};
